P.transport["npc:aggem-thorncurse"] = {
  hash = "6512f7",
  fullHash = "6512f7",
  text = "Aggem Thorncurse. Aggem Thorncurse is a living quilboar shaman in Razorfen Kraul, bearing the title Death's Head Prophet. He calls a boar spirit to his aid when threatened. Aggem guards a part of Razorfen Kraul occupied by the Death's Head tribe. His shamanic powers include summoning a boar spirit, reflecting the quilboar's reverence for Agamaggan.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_aggem-thorncurse-94d289862dfb91c753e5/1-0000.mp3", duration = 18.964898, start = 0},
  },
}
P.transport["npc:bazzalan"] = {
  hash = "9b288e",
  fullHash = "9b288e",
  text = "Bazzalan. Bazzalan is a sinister satyr rogue lurking within the volcanic depths of Ragefire Chasm. Alongside Jergosh the Invoker, he commands the dark activities of the Searing Blade cult directly beneath the Horde capital of Orgrimmar. While Thrall works to establish the Orcs' new home across Durotar, ancient evils have found a roost beneath his feet. Bazzalan, a cunning satyr rogue, has allied with the Searing Blade cult inside the winding lava caverns of Ragefire Chasm. Swift and lethal with twin blades, he serves as one of the cult's primary field commanders. Perched upon a dark volcanic ledge overlooking the central chamber where Jergosh the Invoker conducts demonic rituals, Bazzalan oversees his cultist guards. Like all satyrs, his ultimate loyalty lies with demonic masters, using poisons, fast strikes, and dark stealth to eliminate any Horde scouts who venture too close to the cult's staging ground.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bazzalan-7557084d7a6c324752a0/1-0000.mp3", duration = 55.9542857, start = 0},
  },
}
P.transport["npc:blind-hunter"] = {
  hash = "19a2b8",
  fullHash = "19a2b8",
  text = "Blind Hunter. The Blind Hunter is an elusive, albino bat that roosts deep within Razorfen Kraul. Unlike the ordinary bats nesting near the cavern entrances, this rare creature prowls the sunless depths of the quilboar redoubt. Razorfen Kraul is riddled with winding briars and dark subterranean caverns. While common Kraul bats roost nearer to the surface where faint light filters in from the outside world, the Blind Hunter has adapted entirely to the furthest, darkest alcoves of the tangle. Its pale, albino hide and milky gaze are likely the result of generations spent completely isolated from natural sunlight. True to its name, scholars and scouts believe the creature has lost most or all of its conventional eyesight, relying instead on keen senses of hearing and echolocation to track prey through the gloom. It rarely shows itself, appearing only on occasion to hunt through the dense thickets, making an encounter with this phantom beast a prized occurrence among cavern explorers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_blind-hunter-96ae8937e00b1436a010/1-0000.mp3", duration = 58.8538776, start = 0},
  },
}
P.transport["npc:bruegal-ironknuckle"] = {
  hash = "958172",
  fullHash = "958172",
  text = "Bruegal Ironknuckle. Bruegal Ironknuckle is an infamous dwarven prisoner held within the Stormwind Stockade. Unlike the petty criminals and rioting rabble that fill the holding cells, he is a formidable brawler whose presence deep inside the corridors spells immediate danger to anyone trying to restore order. When the Stormwind Stockade erupted into open revolt, many of the city's most volatile cutthroats took control of the subterranean cellblocks. Among them is Bruegal Ironknuckle, a particularly dangerous dwarf inmate known for brutal brawling strength. Rather than staying confined to a single cell, he prowls the riot-torn hallways, ready to bash anyone attempting to quell the uprising. While much of the uprising inside the facility is orchestrated by the Defias Brotherhood and their ringleaders, inmates like Bruegal highlight that the prison houses assorted rogues and outlaws from across the eastern realms. Whatever crimes earned him a sentence deep beneath Stormwind, his fierce resilience makes him an elusive target and one of the deadliest lone inmates walking the prison corridors.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bruegal-ironknuckle-77da1dac90a08649bb2e/1-0000.mp3", duration = 61.2310204, start = 0},
  },
}
P.transport["npc:dark-iron-ambassador"] = {
  hash = "24ccda",
  fullHash = "24ccda",
  text = "Dark Iron Ambassador. The Dark Iron Ambassador is an emissary of the Dark Iron clan found deep within Gnomeregan. His presence raises questions about the clan's interest in the ruined gnome capital. The Dark Iron Ambassador is found among the dangers of irradiated Gnomeregan. He represents the Dark Iron clan, but the purpose of his mission is not explained.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dark-iron-ambassador-9110f95c1ea1b4e26309/1-0000.mp3", duration = 19.8791837, start = 0},
  },
}
P.transport["npc:dextren-ward"] = {
  hash = "6fd2b3",
  fullHash = "6fd2b3",
  text = "Dextren Ward. Dextren Ward is an infamous criminal and grave robber locked away inside the Stormwind Stockade. Before his capture, he profited by exhuming bodies from Duskwood's Raven Hill Cemetery and delivering them to the necromancer Morbent Fel. Now caught in the midst of the prison's bloody uprising, he remains marked for death by the town council of Darkshire. Before ending up in chains beneath the streets of Stormwind, Dextren Ward conducted a grim and lucrative business in the fog-choked woods of Duskwood. Raven Hill Cemetery was already a site of sorrow and growing horror, but Ward treated its burial grounds as a private quarry. Rather than hunting merely for trinkets and heirlooms left with the dead, Ward dealt in flesh, unearthing fresh graves to supply local dark practitioners. Ward's primary customer was Morbent Fel, a necromancer whose dark rituals have plagued Duskwood and swelled the ranks of the undead. In supplying bodies to Fel, Ward actively contributed to the terror that grips Darkshire. Though eventually caught by Stormwind authorities and dragged into the Stockade, his crimes earned him the undying enmity of the people of Duskwood, prompting Councilman Millstipe to demand Ward's hand as proof of justice served. When a sweeping rebellion broke out inside the Stockade, Ward was not liberated by allies, but rather freed from his cell to join the chaos within the locked-down dungeon. Armed and vicious, he commands his own corner of the prison and uses terror to ward off interlopers, making him one of the priority targets Alliance forces seek to eliminate while restoring order.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dextren-ward-b6e13eea31d9cf794b99/1-0000.mp3", duration = 91.7159184, start = 0},
  },
}
P.transport["npc:fenrus-the-devourer"] = {
  hash = "814f51",
  fullHash = "814f51",
  text = "Fenrus the Devourer. Fenrus the Devourer is an enormous worg that prowls the upper sanctum of Shadowfang Keep. Kept as a personal pet and guardian by Archmage Arugal, the ravenous beast is bloated on unnatural magics. Anyone daring to breach the archmage's personal study must contend with this feral horror and the master who watches over it. Deep within Shadowfang Keep, just outside Archmage Arugal's personal chambers, lurks the monstrous worg known as Fenrus the Devourer. Unlike the lupine worgen roaming the ramparts, Fenrus is an actual worg, swollen to gargantuan proportions. Prowling the shelves, scrolls, and arcane apparatuses of Arugal's private study, the beast serves both as a pet and as a violent perimeter guard against any intruder seeking the mad mage's head. Fenrus's unnatural bulk suggests he was subjected to the dark magics saturating the keep since Baron Silverlaine's downfall. Archmage Arugal or his unleashed worgen clearly warped the creature with arcane or shadowy experiments, transforming a native predator into a ravenous juggernaut. Fenrus is so feral and magically bound that no hunter can charm or tame his mind.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_fenrus-the-devourer-0c510fd2a55aa31f4566/1-0000.mp3", duration = 67.8922449, start = 0},
  },
}
P.transport["npc:herod"] = {
  hash = "61aa1b",
  fullHash = "61aa1b",
  text = "Herod. Herod is a renowned champion and berserker of the Scarlet Crusade, commanding the Armory within the Scarlet Monastery. Known for his ferocious martial prowess and unyielding zeal, he trains recruits in the brutal melee combat needed to wage holy war. His death is sought by both Alliance dissidents and the Horde's rulers in Undercity to weaken the Crusade's military core. Within the fortified halls of the Scarlet Monastery's Armory, Herod stands as the embodiment of the Crusade's martial aggression. Unlike the spellcasters and paladins who channel holy magic in the Cathedral, Herod relies on raw, bloodthirsty physical power. Clad in mail and wielding a massive two-handed axe, he personally trains cohorts of Scarlet Trainees, instilling a furious devotion to exterminating anyone not allied with their fanatical cause. Because Herod oversees the armaments and martial training of the Crusade's front-line warriors, taking him down is essential for anyone seeking to dismantle the order. Raleigh the Devout, an ex-Crusader disillusioned with the order's madness residing in Southshore, calls for Herod's demise to shatter their military leadership. Across Lordaeron, the dreadlord Varimathras in the Undercity similarly seeks his execution to clear out a dangerous human bastion bordering Forsaken territory.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_herod-86bb6a5cad6f1e21a462/1-0000.mp3", duration = 76.7477551, start = 0},
  },
}
P.transport["npc:kam-deepfury"] = {
  hash = "41905d",
  fullHash = "41905d",
  text = "Kam Deepfury. Kam Deepfury is a notorious Dark Iron saboteur incarcerated within the depths of the Stormwind Stockade. Unlike the majority of the prison's inmates, he has no allegiance to the Defias Brotherhood, having been captured for orchestrating a devastating explosion along the Thandol Span far to the north. While the Stockade is overwhelmingly filled with disgruntled Stonemasons and Defias rebels, Kam Deepfury stands apart. A Dark Iron dwarf of cunning and violence, Deepfury was captured and brought to Stormwind after masterminding an operation that crippled vital northern infrastructure. He is locked deep within the prison's cells, isolated from his kin beneath Blackrock Mountain but just as hostile to the Alliance as any rebel rioter sharing the corridors. Alliance intelligence stationed at Dun Modr, near the northern border of the Wetlands, identified Deepfury as the chief architect behind the explosion that shattered the Thandol Span. The blast severed one of the massive stone bridges linking the Wetlands to the Arathi Highlands. Beyond crippling a critical trade and military route for Ironforge and the Alliance, the sabotage claimed the life of a kin of the dwarf commander Longbraid the Grim.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kam-deepfury-d1f92bf134bcb46b0077/1-0000.mp3", duration = 69.4334694, start = 0},
  },
}
P.transport["npc:lady-sarevess"] = {
  hash = "f3f0c0",
  fullHash = "f3f0c0",
  text = "Lady Sarevess. Lady Sarevess is a twisted naga sorceress dwelling within the flooded ruins of Blackfathom Deeps, where she dabbles in dark sorceries. Within the Pool of Ask'ar, Lady Sarevess conducts her rituals in a flooded grotto of the ruined temple. A very twisted spellcaster, she dabbles in dark magic while the Twilight's Hammer cultists who also haunt the sunken temple pursue their own worship deeper in the cavern. Much like a sea witch of the deep oceans, Sarevess commands elemental currents and crackling arcs of lightning. Surrounded by loyal naga sentinels and summoned water elementals, she fiercely defends her sanctuary against any intruders who threaten her dark work.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lady-sarevess-9a3048cdac7a050f3006/1-0000.mp3", duration = 41.9265306, start = 0},
  },
}
P.transport["npc:lord-serpentis"] = {
  hash = "d1d42a",
  fullHash = "d1d42a",
  text = "Lord Serpentis. Lord Serpentis is a corrupted night elf druid who stands as one of the four leaders of the rogue Druids of the Fang within the Wailing Caverns. Once a druid of great power and prestige in the order of Naralex, he was twisted into madness when Naralex's dream became a nightmare within the subterranean springs. Now, he helps command the serpent-worshipping sect deep in the caverns where the corrupted Naralex lies slumbering. Before darkness overtook the cavern springs, Serpentis was a druid of great power and prestige, one of the noble order led by Naralex that hoped to use the caverns' springs and the Emerald Dream to heal the Barrens. However, when Naralex's vision became a corrupting nightmare, Serpentis was among the druids whose minds fell to the emerging madness. Succumbing completely to the corruption radiating from Naralex's twisted dreams, Serpentis and his fellow druids became the Druids of the Fang. Forsaking traditional Cenarion balance and the totem animals of old, they now seek to remake the Barrens to match their own twisted dreams rather than heal it. Serpentis rules the sect as one of its four leaders, alongside Lady Anacondra, Lord Cobrahn and Lord Pythas.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-serpentis-c6eb458c51a76ff90dd1/1-0000.mp3", duration = 68.7281633, start = 0},
  },
}
P.transport["npc:lorgus-jett"] = {
  hash = "050660",
  fullHash = "050660",
  text = "Lorgus Jett. Lorgus Jett is a human member of the Twilight's Hammer cult operating within the flooded corridors of Blackfathom Deeps. Wandering the Moonshrine Ruins, he serves as a ruthless commander in the cult's service to the Old Gods. Horde leaders have singled him out as a primary target to disrupt the cult's encroaching presence along the Ashenvale coast. While many members of the Twilight's Hammer working under Blackfathom Deeps hail from orcish or tauren lineages, Lorgus Jett stands out as a human in the deep recesses of ancient night elf ruins. Roaming anywhere between the upper Moonshrine Ruins and the cavernous tunnels beyond the murloc defiler Gelihast, Jett coordinates the cult's dark rituals and violent ambitions.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lorgus-jett-1cbe755eb8294aaa464a/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["npc:miner-johnson"] = {
  hash = "11eb79",
  fullHash = "11eb79",
  text = "Miner Johnson. Miner Johnson is an elusive, seasoned miner affiliated with the Defias Brotherhood deep inside the Deadmines. Tucked away in a side alcove alongside ordinary laborers, this dangerous prospector oversees excavation efforts ahead of the heavy machinery found deeper underground. Because he wanders the subterranean tunnels erratically, adventurers only occasionally cross his path. While hundreds of laborers pick at the subterranean veins of the Deadmines to supply Edwin VanCleef's hidden fortress, Miner Johnson stands out as an unusually formidable figure among them. Lurking in a shadowed alcove to the left before the lumbering shredders of the Mast Room, he is far tougher and more aggressive than the regular workforce. His unpredictable presence makes him a legendary target for explorers traversing the Defias tunnels. The Defias Brotherhood's clandestine operation beneath Moonbrook requires vast amounts of raw ore to forge weapons, reinforce shafts, and assemble mechanical contraptions. Miners like Johnson provide the muscle behind the metal, hacking away at the rich mineral seams beneath Westfall. Anyone stumbling into Johnson's workspace will quickly discover that he defends his dig site with lethal fervor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_miner-johnson-b6b3679d71839e661994/1-0000.mp3", duration = 73.4563265, start = 0},
  },
}
P.transport["npc:mr-smite"] = {
  hash = "a83852",
  fullHash = "a83852",
  text = "Mr. Smite. Mr. Smite is the imposing tauren first mate serving aboard the Defias Brotherhood's flagship deep inside the Deadmines. An expert weaponmaster under Captain Greenskin, he commands the dockside approach to the hidden juggernaut with ruthless discipline. Intruders who face him must contend with his shifting arsenal and devastating physical strength. Guarding the docks of Ironclad Cove, Mr. Smite serves as first mate to the goblin Captain Greenskin. While the Defias Brotherhood is predominantly composed of disenfranchised humans and allied goblin tinkerers, Smite stands as a striking anomaly: a massive, battle-hardened tauren far from the plains of Kalimdor. Tasked with maintaining strict order among a rowdy pirate crew, he ensures that the labor fitting out Edwin VanCleef's secret dreadnaught proceeds without disruption. Smite is not merely a brute enforcer; he is a theatrical and versatile weaponmaster. He delights in toying with would-be heroes, deliberately prolonging combat to offer opponents a false sense of hope. When pressed, he unleashes a staggering, earth-shattering stomp that leaves foes stunned while he rummages through his nearby weapon chest. Beginning combat with a nimble dueling blade, he will escalate to twin cleaving reavers, and finally resort to his colossal two-handed warhammer when thoroughly provoked.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mr-smite-4497048c1752122fd19d/1-0000.mp3", duration = 78.837551, start = 0},
  },
}
P.transport["npc:rhahk-zor"] = {
  hash = "289cb6",
  fullHash = "289cb6",
  text = "Rhahk'Zor. Rhahk'Zor is a hulking ogre serving as the head foreman within the Deadmines. Overseeing Edwin VanCleef's subterranean construction efforts, he keeps the Defias laborers and miners in line through sheer brute force and heavy-handed discipline. Deep beneath the rolling hills of Westfall, the Defias Brotherhood has transformed the abandoned gold mines of Moonbrook into an underground fortress. Coordinating this sprawling construction requires harsh discipline, a role filled by the ogre Rhahk'Zor. Appointed as head foreman, he oversees the excavation crews and laborers, driving them forward to carve out tunnels and assemble VanCleef's secret projects. Rhahk'Zor maintains order through relentless muscle rather than careful engineering. Armed with an immense stone-headed hammer, his idea of workplace supervision is direct and unforgiving. Defias diggers and goblin engineers alike step lively around him, knowing that falling behind schedule or showing defiance invites a crushing blow from the towering taskmaster.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rhahk-zor-f3fbec36cf165d495d8a/1-0000.mp3", duration = 63.0334694, start = 0},
  },
}
P.transport["npc:sneed"] = {
  hash = "ec56b9",
  fullHash = "ec56b9",
  text = "Sneed. Sneed is the Defias Brotherhood's goblin lumbermaster stationed deep within the Deadmines. Operating from the lumber chamber known as the Mast Room, he pilots a heavy shredder of his own design to process timber for Edwin VanCleef's secret juggernaut. While the Defias Brotherhood draws its core membership from disenfranchised human stonemasons and common laborers, building an ironclad warship requires specialist trades. Edwin VanCleef recruited Sneed specifically for his engineering know-how and ruthless goblin efficiency. Stationed in the Mast Room along the subterranean rail network, Sneed oversees the rapid felling, cutting, and shaping of timber needed to frame VanCleef's colossal dreadnaught. Sneed's primary concern is cutting costs and meeting deadlined quotas, consequences be damned. To speed up the process, he commands the floor from inside a customized shredder equipped with oversized buzz saws. The deadly machine turns raw trunks into shipbuilding timber in seconds. If cornered by intruders, Sneed relies on the armor of his machine to grind them down, but he is more than willing to scramble out of the wreckage and fight with his bare hands if his contraption fails.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sneed-ab6b169d4f773f2259a3/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["npc:sneed-s-shredder"] = {
  hash = "b6eb62",
  fullHash = "b6eb62",
  text = "Sneed's Shredder. Sneed's Shredder is an imposing mechanised lumber harvester stationed deep within the Deadmines. Piloted by the goblin taskmaster Sneed, this deadly machine acts as both heavy industrial machinery for Edwin VanCleef's shipwrights and a terrifying perimeter defender. Within the goblin-dominated foundry of the Deadmines, mechanical shredders serve a dual purpose: processing vast amounts of timber and lumber required for Edwin VanCleef's hidden juggernaut, and serving as armored shock engines against intruders. Sneed, the overseer of the lumber works, operates this modified mechanical beast directly, turning an oversized buzzsaw into an instrument of defense. Defeating the machine does not end the threat. Sneed perches inside an open cockpit above the spinning blades, relying on heavy iron plating and terrifying clatter to scatter his foes. Even when the machinery breaks down and the shredder collapses in a shower of sparks, Sneed leaps from the smoking wreckage to fight to the bitter end.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sneed-s-shredder-4fd667499c66ed4e028d/1-0000.mp3", duration = 61.4922449, start = 0},
  },
}
P.transport["npc:targorr-the-dread"] = {
  hash = "133751",
  fullHash = "133751",
  text = "Targorr the Dread. Targorr the Dread is an infamous Blackrock orc executioner imprisoned deep within the Stormwind Stockade. Known for his brutal tortures of captured Stormwind soldiers, his execution was indefinitely delayed by bureaucratic incompetence and corruption. When the Stockade erupted into revolt under the Defias Brotherhood, Targorr broke free and allied with the rioting convicts. Before his capture, Targorr the Dread served as the supreme executioner for the Blackrock clan under Warlord Gath'Ilzogg. Operating out of the occupied ruins in Redridge, his cruelty stood out as exceptionally savage even by the violent standards of the Dark Horde. Stormwind guards and militiamen who fought to defend the borderlands were subjected to agonizing torment and slow death at his hands, making his name one of the most reviled in the kingdom. When Alliance forces finally managed to capture Targorr alive, he was brought in chains to the capital and locked inside the high-security Stockade to await execution. However, the rot within Stormwind's judicial and political bureaucracy stalled the proceedings. Paralyzed by graft, endless paperwork, and neglect, the courts failed to deliver the death sentence he had earned, leaving a bloodthirsty war criminal sitting in a cell beneath the heart of the city. When the Defias Brotherhood staged their violent prison break, Targorr saw his opportunity. Breaking free from his cell, the ruthless orc threw his lot in with the Defias rioters, turning his cellblock into a slaughterhouse. With the prison entirely out of Warden Thelwater's control, towns like Lakeshire—still nursing the bitter wounds Targorr inflicted on their defenders—seek adventurers willing to venture into the riots and bring back the butcher's head.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_targorr-the-dread-8cc6b6faca1475c1e206/1-0000.mp3", duration = 103.000816, start = 0},
  },
}
P.transport["subzone:camp-narache"] = {
  hash = "cf22fe",
  fullHash = "cf22fe",
  text = "Camp Narache. Camp Narache is a secluded village nestled upon Red Cloud Mesa in southern Mulgore. It serves as the ancestral home of the Hawkwind tribe and the proving ground where young tauren begin their training. Sheltered high above the plains, the camp maintains ancient traditions while constantly guarding against encroaching quilboar and lingering centaur threats. Situated at the northern edge of the elevated Red Cloud Mesa, Camp Narache is the primary settlement of the Hawkwind tribe. The village consists of several large hide lodges and pavilions, including a communal tent for wounded braves, an armory, a bakery tent, and a spirit lounge dedicated to meditation and ancestral communion. At the center of the camp, tribal elders and path trainers stand in a circle at the heart of the camp, where the venerable Greatmother Hawkwind still offers guidance, guiding newly initiated youth as they step into their roles as defenders of the Earth Mother. Though naturally fortified by the steep sheer cliffs of the mesa, Camp Narache faces persistent unrest. Bristleback quilboar from Brambleblade Ravine continuously encroach upon Hawkwind lands, while centaur scouts linger in the distance. Young hunters, shamans, druids, and warriors prove their mettle here by culling the aggressive local wildlife, protecting the village's water well, and turning back quilboar raiders before descending the grand path into the wider valleys of Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_camp-narache-687408e73247da1c1bd8/1-0000.mp3", duration = 82.1028571, start = 0},
  },
}
P.transport["subzone:coldridge-valley"] = {
  hash = "57bb9c",
  fullHash = "57bb9c",
  text = "Coldridge Valley. Coldridge Valley is a sheltered, snow-covered vale tucked into the southwestern heights of Dun Morogh. Centered around the hamlet of Anvilmar, it serves as the training ground where young dwarves and gnome refugees first take up arms in service of Ironforge. A single tunnel, Coldridge Pass, connects this secluded hollow to the wider mountain realm. Cradled by sheer mountain cliffs, Coldridge Valley remains largely cut off from the bustling trade routes of Dun Morogh. At its heart sits Anvilmar, a sturdy stone hall and hamlet where veteran dwarven instructors and displaced gnome scholars train fresh recruits in the arts of battle, stealth, and sorcery. Outside the warmth of Anvilmar's hearths, the valley floor is carpeted in thick snow and prowled by boars and hungry winter wolves, providing novices with their first real taste of frontier survival. Despite its isolation, Coldridge Valley faces immediate danger from two relentless enemies. Indigenous Frostmane trolls have established camps like the Frostmane Hovel, skirmishing with mountaineers and defending their ancestral claims against dwarven encroachment. Worse still, savage Rockjaw troggs have overrun Coldridge Pass, the natural tunnel linking the valley to Kharanos. Until these subterranean brutes are pushed back, travelers and supplies cannot freely move between the valley and the high seat of Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_coldridge-valley-1cf1c67e2e4c522d2f89/1-0000.mp3", duration = 81.6326531, start = 0},
  },
}
P.transport["subzone:deathknell"] = {
  hash = "162934",
  fullHash = "162934",
  text = "Deathknell. Deathknell is a fortified village nestled in a secluded valley in southwestern Tirisfal Glades. It serves as the primary awakening grounds for newly freed undead breaking free from the Lich King's grasp to join the Forsaken. Besieged by mindless Scourge remnants, local zealots, and aggressive wildlife, the settlement is a harsh proving ground for those claiming a place in Sylvanas Windrunner's kingdom. Tucked away behind jagged hills just north of the Silverpine border, Deathknell is where newly awakened undead first open their eyes to their bleak reality. Unlike most settlements in Tirisfal Glades that preserved their human names from the fallen Kingdom of Lordaeron, Deathknell was explicitly renamed by the undead who claimed it. The town itself is cleaved in two: the Forsaken cling stubbornly to the southern grounds around the old church, while the northern half—including the village forge—remains overrun by mindless Scourge zombies and feral ghouls. Elite Deathguards keep the narrow gorge out of the valley securely sealed against intruders, allowing local caretakers to induct new arrivals into the Banshee Queen's service. Survival in Deathknell is precarious. To the northwest, Night Web's Hollow—a gold mine vital for the Forsaken's fledgling economy—has been lost to monstrous spiders. To the southeast, an aggressive encampment of the Scarlet Crusade maintains constant watch, trading couriers with their strongholds to the east and probing the valley's defenses. Meanwhile, the village caretakers must continually fight off the mindless undead wandering the northern ruins while gathering scrap metal, tools, and supplies to equip newly arisen souls for the long road ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_deathknell-e98cdaa7d3a6df823e4a/1-0000.mp3", duration = 99.5526531, start = 0},
  },
}
P.transport["subzone:northshire-abbey"] = {
  hash = "a9b66a",
  fullHash = "a9b66a",
  text = "Northshire Abbey. Northshire Abbey is a historic monastery nestled in Northshire Valley within the northern foothills of Elwynn Forest. Rebuilt after its destruction in the First War, it serves as the spiritual heart of the Brotherhood of Northshire and a premier training center for new defenders answering the kingdom of Stormwind's call. Centuries ago, clerics from Lordaeron traveled south into the kingdom of Stormwind to spread the worship of the Holy Light, establishing the Holy Order of Northshire Clerics and their abbey. The monastery quickly became an anchor of kingdom life, caring for the sick and even tending to the young Guardian Medivh during his years in a coma. During the First War, the abbey suffered repeated assaults by brigands and the Orcish Horde, culminating in its utter destruction. When the Alliance of Lordaeron liberated the region in the Second War, Archbishop Alonsus Faol helped rebuild the sanctuary, refounding its protectors as the Brotherhood of Northshire. Today, Northshire Abbey functions as the starting ground for volunteers, militia recruits, and novices seeking to defend a beleaguered Stormwind. Split into the Main Hall, Hall of Arms, and Library Wing, it houses instructors in the martial, arcane, and holy arts, while scouts and rogues train in the outer yards. Despite the watchful presence of the Knights of the Silver Hand, peace here remains precarious. Kobolds overrun nearby mines, aggressive wolves roam the orchards, and agents of the Defias Brotherhood stalk the valley roads, pilfering ancient scrolls and sacred librams from the abbey's storied archives.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_northshire-abbey-b7327bf22011961f4120/1-0000.mp3", duration = 92.8130612, start = 0},
  },
}
P.transport["subzone:shadowglen"] = {
  hash = "154808",
  fullHash = "154808",
  text = "Shadowglen. Shadowglen is a secluded, twilit vale nestled within the northeastern boughs of Teldrassil. Dominated by the great barrow-tree Aldrassil, it serves as the safe haven where young night elves take their first steps into service before journeying out into the wider world. Tucked away in the northeastern canopy of Teldrassil, Shadowglen is ringed by high ridges that shelter it from the rest of the world. Bathed in eternal dusk, the vale centers on Aldrassil, a massive barrow-tree whose hollowed trunk houses elders, priestesses, and mentors for young night elves beginning their training. The only route out of the valley leads south through a narrow mountain pass toward Starbreeze Village and Dolanaar, making Shadowglen one of the most naturally fortified and peaceful sanctuaries on the World Tree. Despite its tranquil seclusion, Shadowglen is not entirely free from danger. In the extreme northwest lies Shadowthread Cave, a dark cavern infested with venomous spiders that constantly threaten the tranquil glade. Even on the pristine branches of Teldrassil, vigilance is required, and fledgling defenders are tasked with driving back the encroaching vermin and untamed wildlife before venturing into the broader expanse of the boughs beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_shadowglen-0fc31ff370b6dd350280/1-0000.mp3", duration = 72.8032653, start = 0},
  },
}
P.transport["topic:anduin-lothar"] = {
  hash = "67a3d9",
  fullHash = "67a3d9",
  text = "Anduin Lothar. Sir Anduin Lothar, known as the Lion of Stormwind, was the last descendant of the ancient Arathi bloodline and the Supreme Commander of the Alliance of Lordaeron. A childhood companion of King Llane Wrynn and the Guardian Medivh, Lothar led humanity through the horrors of the First War and rallied the northern nations during the Second War before falling at Blackrock Mountain. Carrying the ancient bloodline of the Arathi kings, Lothar grew up within Stormwind's royal court alongside Prince Llane Wrynn and Medivh. The trio embarked on reckless excursions into the wilderness, skirmishing with Gurubashi trolls in Stranglethorn Vale. Lothar rose rapidly through Stormwind's martial ranks, joining the King's Honor Guard and earning renown as an Armsman of the Brotherhood of the Horse. Arriving on the shores of Lordaeron, Lothar presented the grim reality of the Horde to King Terenas Menethil II. Invoking his ancestral Arathi lineage and diplomatic gravitas, he unified the human realms, Ironforge dwarves, and high elves into the Grand Alliance of Lordaeron. Named Supreme Commander of the united forces, Lothar spearheaded the campaign that pushed the Horde back south to the foot of Blackrock Mountain. There, in a fateful clash near the end of the Second War, Lothar was slain by Warchief Orgrim Doomhammer. His death did not shatter the Alliance; instead, it galvanized his lieutenant, Turalyon, to lead the charge that broke the Horde forever.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_anduin-lothar-b8aba8b85a328ce448dc/1-0000.mp3", duration = 84.5844898, start = 0},
  },
}
P.transport["topic:arthas-menethil"] = {
  hash = "3dd0ea",
  fullHash = "3dd0ea",
  text = "Arthas Menethil. Once the golden prince of Lordaeron and a celebrated paladin of the Silver Hand, Arthas Menethil fell from grace during the Third War while pursuing the demonic orchestrators of the plague. After claiming the cursed runeblade Frostmourne in the frozen north, he surrendered his soul, murdered his father King Terenas, and spearheaded the destruction of his own homeland as the Scourge's dark champion. Born to King Terenas Menethil II, Arthas was raised to embody the ideals of the Alliance of Lordaeron. Trained in combat by Muradin Bronzebeard and inducted into the Order of the Silver Hand under the tutelage of Uther the Lightbringer, he was revered by high and low alike as the future of humanity. Bold, skilled, and fiercely protective of his people, he fought tenaciously against Blackrock clan orc incursions and forest troll warbands. Yet beneath his radiant exterior lay an uncompromising pride and an obsessive dread of failure.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_arthas-menethil-a1a2ca2fc4b90a178700/1-0000.mp3", duration = 57.8089796, start = 0},
  },
}
P.transport["topic:black-dragonflight"] = {
  hash = "e4da39",
  fullHash = "e4da39",
  text = "Black dragonflight. Once the stalwart Earth-Warders charged by the titans to safeguard Azeroth's deep subterranean realms, the black dragonflight fell to madness and treachery. Corrupted by the insidious whispers of the imprisoned Old Gods, their leader Neltharion became Deathwing, turning his brood into one of the most destructive and hated forces on the planet. Today, their surviving scions weave plots from the shadows and wage covert wars against mortal kingdoms. Long ago, the Titan Khaz'goroth bestowed his blessing upon Neltharion, creating the black dragonflight to watch over the earth, raise mountains, and guard Azeroth's deep caverns. For ages, they stood alongside the other flights as patient, unyielding guardians. Yet their intimate bond with the world's subterranean foundations proved their undoing. Dwelling within the deepest hollows, they lay dangerously close to the sunken prisons of the Old Gods. Over centuries, dark whispers eroded the noble Earth-Warder's mind, driving him to madness and twisting his entire brood into vicious instruments of ruin. During the ancient War of the Ancients, Neltharion shattered the unity of dragonkind, turning upon his kin as Deathwing the Destroyer. Ever since, the black flight has waged relentless, spiteful war against the red, blue, green, and bronze flights, who view their cruelty as an absolute profanation of life. Rather than tending the soil, black dragons now wield molten magma, black magic, and searing brimstone to scorch the lands they once nurtured, finding delight in sowing discord, misery, and endless strife across mortal realms.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_black-dragonflight-46df670e5eeb9201224c/1-0000.mp3", duration = 97.6195918, start = 0},
  },
}
P.transport["topic:bronzebeard-clan"] = {
  hash = "faf8c1",
  fullHash = "faf8c1",
  text = "Bronzebeard clan. The Bronzebeard clan is the ruling dwarven royal line and dominant population of Ironforge. Following their victory in the ancient War of the Three Hammers, they forged strong ties with humanity and the gnomes, standing today under King Magni Bronzebeard as a cornerstone of the Alliance. Long ago, dwarven society in Ironforge flourished under High King Modimus Anvilmar. When the king died of old age roughly 230 years ago, simmering rivalries erupted into civil war. Thane Madoran Bronzebeard commanded the traditional garrison and largest standing army within Ironforge, successfully driving both the Wildhammer and Dark Iron clans from under the mountain. When Sorcerer-Thane Thaurissan mounted an assault to reconquer Khaz Modan, Madoran Bronzebeard led his clan in a decisive campaign that shattered the Dark Iron host, solidifying Bronzebeard supremacy over Ironforge. Human kingdoms first encountered the Bronzebeards nearly two millennia ago, building mutual respect through shared mastery of metalcraft, trade, and a passion for battle. When the Orcish Horde swept through the continent in the Second War, King Magni Bronzebeard brought his realm into the Alliance of Lordaeron. Despite withstanding brutal sieges within their subterranean fortress, Bronzebeard engineers, gunners, and demolitionists provided pivotal firepower and arms that helped turn the tide of the war.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_bronzebeard-clan-ac41a2615b16b2abc20d/1-0000.mp3", duration = 80.6138776, start = 0},
  },
}
P.transport["topic:burning-blade-clan"] = {
  hash = "4f0c45",
  fullHash = "4f0c45",
  text = "Burning Blade clan. Once an ancient orcish clan renowned for its deadly blademasters and consumed by chaotic frenzy during the early wars, the Burning Blade now largely persists as a sinister demon-worshiping cult. Its acolytes infiltrate Durotar and the Barrens under the direction of the Shadow Council. Meanwhile, a handful of honorable blademasters have forsaken its demonic corruption to serve Warchief Thrall in the New Horde. Originating in the lands of Draenor alongside clans like the Warsong, the Burning Blade were long respected for the lethal tradition of their blademasters. When they drank the blood of Mannoroth and marched through the Dark Portal into Azeroth during the First War, however, the clan fractured mentally. By the Second War, they were scarcely an organized society, behaving instead like a berserk force of nature. Nomadic and demented, they threw themselves into battle with total disregard for survival, requiring ogres to hold them in check until unleashed. Ultimately, their numbers were battered and routed near the Dark Portal by the Alliance. Following the Second War, the surviving remnants of the Burning Blade split dramatically. A disciplined contingent of blademasters swore solemn oaths to liberate their people from demonic enslavement, pledging their blades directly to Warchief Thrall as his personal honor guard. Yet a far larger portion of the scattered clan fell entirely under the sway of the Burning Legion and the Shadow Council, morphing into a clandestine cult of warlocks, fel acolytes, and conspirators lurking throughout Kalimdor. The modern cult operates covens across Kalimdor, troubling newly arrived orcs and Darkspear trolls from their first days in the Valley of Trials. Burning Blade warlocks inhabit Thunder Ridge, and garrison a major hideout within Skull Rock near Orgrimmar's eastern gates. Their cultists rally around dark relics like the Demon Seed and harvest souls for demonic rituals, making them a primary internal menace against the fledgling Horde's stability in Durotar and the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_burning-blade-clan-042994d0a1fee6aa4c80/1-0000.mp3", duration = 119.170612, start = 0},
  },
}
P.transport["topic:burning-legion"] = {
  hash = "a7353f",
  fullHash = "a7353f",
  text = "Burning Legion. The Burning Legion is an infinite, apocalyptic host of demons led by the fallen titan Sargeras, dedicated to scouring all life from creation. Having already shattered ancient Kalimdor ten thousand years ago, the demons remain Azeroth's most relentless nemesis, orchestrating the corruption of the orcs and the horrors of the Third War. Long ago, Sargeras stood as the champion of the titans, tasked with hunting down and imprisoning the demons that plagued the cosmos. Over countless ages of battling their evil, he grew disillusioned and concluded that creation itself was fatally flawed and must be unmade in flame. To enact his crusade, he freed the demons he had imprisoned, bending them to his will through fel magic. He augmented their chaos with the intellect of the corrupted eredar—elevating Archimonde and Kil'jaeden as his chief lieutenants—and forged an unstoppable engine of cosmic annihilation. Ten millennia ago, the reckless sorceries of the Highborne drew the Legion's gaze to Azeroth. Whispering through the Well of Eternity, Sargeras seduced Queen Azshara and her councilor Xavius with promises of reshaping the world into paradise. Instead, the portal unleashed commanders like Mannoroth and Archimonde alongside swarms of doomguard, felhounds, and flaming infernals. The ensuing war reduced Kalimdor's civilization to ruin before an alliance of night elves, dragonflights, and demigods collapsed the gateway. The catastrophic implosion tore the supercontinent apart in the Great Sundering, casting the ruined lands across vast new seas. Though cast back into the Twisting Nether, the Legion never abandoned Azeroth. Deciding that direct invasion invited failure, Kil'jaeden orchestrated proxy cataclysms from afar. The deceiver bound the orcs of Draenor through demonic blood pacts, sending the Horde charging through the Dark Portal to weaken mortal defenses. When that failed, the Legion forged the Lich King and unleashed the undead Scourge across Lordaeron, paving the way for Archimonde's return in the Third War. Even after Archimonde fell at Mount Hyjal, remnants of the Legion linger across Felwood, the Blasted Lands, and hidden cults throughout the world.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_burning-legion-56c573c49e71baa80ddc/1-0000.mp3", duration = 130.742857, start = 0},
  },
}
P.transport["topic:cenarion-circle"] = {
  hash = "f49d12",
  fullHash = "f49d12",
  text = "Cenarion Circle. The Cenarion Circle is an ancient, independent order of druids founded by Malfurion Stormrage under the guidance of the demigod Cenarius. Operating from their sacred haven in Moonglade, they strive to maintain the balance of nature, safeguard the Emerald Dream, and mend Azeroth's blighted lands. Though historically composed of night elves, they have recently welcomed the tauren into their ranks, transcending factional divides to defend the living world. The roots of the Cenarion Circle go back thousands of years to the teachings of Cenarius, the Patron of Druids, who mentored the first mortal druid, Malfurion Stormrage. Following the Great Sundering, Malfurion bound together those who wished to study nature's ways. The order made its home in the sacred vale of Moonglade, and ever since, the Circle has held sacred vigil over Azeroth's wild places. While deeply intertwined with night elf history, the Cenarion Circle exists independently of Darnassus and the Sisterhood of Elune. Their heart remains the enchanted valley of Moonglade, centered around the peaceful town of Nighthaven, where weapons are sheathed and the wars of mortals hold no sway. This ancient neutrality was demonstrated anew following the Third War, when Malfurion befriended the tauren elder Hamuul Runetotem. Recognizing the tauren people's profound spiritual reverence for the Earth Mother, the Circle formally inducted Hamuul, reintroducing druidism to his race after thousands of years.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_cenarion-circle-b6896cb911b5470091af/1-0000.mp3", duration = 86.4914286, start = 0},
  },
}
P.transport["topic:church-of-the-holy-light"] = {
  hash = "c2cddd",
  fullHash = "c2cddd",
  text = "Church of the Holy Light. The Church of the Holy Light is the dominant religious institution of humanity, guiding mortal souls through the virtues of compassion, justice, and devotion. Originally centered in the lost northern kingdom of Lordaeron, its leadership now resides within the grand Cathedral of Light in Stormwind City following the devastation wrought by the Scourge. The Church's origins reach back over a millennium to the faith in the Holy Light that took root among the humans of Arathor, teaching them to channel sacred power to cure injuries and purge affliction. Driven by tenets of charity, righteousness, and the fundamental belief that the Light resides within all thinking beings, these teachings eventually coalesced into an organized faith. The kingdom of Lordaeron became the religious heartland of this doctrine, establishing revered sanctuaries throughout the north, including Stratholme, Andorhal, Tyr's Hand, and Light's Hope Chapel. In the First War, the Brotherhood of Northshire answered the call to battle, healing fallen defenders against the invading Orcish Horde. Because they lacked weapons or heavy armor, these frontline clerics suffered appalling casualties at the hands of the orcs. Recognizing the need for holy warriors who could both channel holy wrath and survive physical combat, Archbishop Alonsus Faol convened with Supreme Commander Anduin Lothar during the Second War to establish the Knights of the Silver Hand. Paladins and priests alike became the moral and martial bulwark of the Alliance of Lordaeron, preserving humanity from total annihilation. The Third War brought immense sorrow upon the faithful. When the Plague of Undeath crept across Lordaeron, the Church worked tirelessly to alleviate the sick and stem the contamination, only to be overwhelmed when the kingdom collapsed from within. With Lordaeron transformed into a Scourge-haunted wilderness, the seat of the Church transferred southward. Under the stewardship of Archbishop Benedictus, the clergy reconstituted its hierarchy within the newly constructed Cathedral of Light in Stormwind, offering solace, spiritual guidance, and military purpose to the battered survivors of the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_church-of-the-holy-light-875f3af38db1113e2388/1-0000.mp3", duration = 126.171429, start = 0},
  },
}
P.transport["topic:cult-of-the-damned"] = {
  hash = "5375e3",
  fullHash = "5375e3",
  text = "Cult of the Damned. The Cult of the Damned is a secretive cabal of mortal zealots, necromancers, and aristocrats devoted to the Lich King. Formed in northern Lordaeron prior to the Third War, its members poisoned the grain supplies that spawned the Scourge and engineered the downfall of humanity's greatest kingdom. Today, the surviving cultists manage the plague cauldrons and necromantic academies across the Plaguelands while actively infiltrating the cities of the living. The Cult of the Damned was forged by the exiled Archmage Kel'Thuzad after he answered the telepathic whispers of the Lich King emanating from the Frozen Throne. Returning to Lordaeron with vast wealth and forbidden dark arts, Kel'Thuzad offered two false gospels: to the desperate, impoverished lower classes, he promised social equality and liberation from misery; to the wealthy landowners, such as the noble House of Barov, he promised eternal life and an unshakeable grip upon their domains. In truth, both the destitute and the affluent were cattle intended for slaughter, bound into a death cult designed to betray their homeland from the inside. Operating in complete secrecy from the dungeons beneath Caer Darrow, the cultists honed their necrotic craft, built hulking abominations, and perfected the Plague of Undeath brought south from Northrend. They struck at Lordaeron's breadbasket, contaminating the grain stores at Andorhal. As tainted flour traveled through regular merchant routes to hearths across the Eastweald, commoners sickened and died within days, only to rise as shambling thralls under the Lich King's telepathic lash. When Prince Arthas slaughtered Kel'Thuzad in Andorhal, the cultist network was already so deeply rooted that the kingdom's doom was sealed. Though Arthas sailed to Northrend and ascended the Frozen Throne, the Cult of the Damned remains fully operational in northern Lordaeron under the command of the resurrected archlich Kel'Thuzad. From the shadows of Stratholme and the halls of Scholomance, living cultists perform dark rites, maintain the toxic plague cauldrons across the ruined farmsteads, and attempt to assassinate Scarlet Crusaders and Forsaken alike. Because they still breathe, these acolytes can walk unnoticed through living settlements, poisoning wells, sabotaging supply lines, and grooming new recruits to feed the Scourge machine.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_cult-of-the-damned-52e36e9b7322b2cc11ec/1-0000.mp3", duration = 139.964082, start = 0},
  },
}
P.transport["topic:dark-iron-clan"] = {
  hash = "e7c805",
  fullHash = "e7c805",
  text = "Dark Iron clan. The Dark Iron clan is an ancient, ash-skinned dwarven faction ruling from the volcanic depths of Blackrock Mountain. Cast out of Ironforge during the War of the Three Hammers, they accidentally summoned Ragnaros the Firelord, who enslaved their empire. Today, under Emperor Dagran Thaurissan, they wage shadow wars against both the Alliance and the Horde while serving their fiery elemental master. Long ago, three dwarven factions lived together in Ironforge under High King Modimus Anvilmar. When the king died, civil war erupted. The Bronzebeards defeated both rival factions, casting out the Wildhammers and Sorcerer-Thane Thaurissan's Dark Irons. Vowing vengeance, Thaurissan established a settlement in the Redridge Mountains while his sorceress wife, Modgud, led an army against Grim Batol. When both assaults failed and the united Bronzebeard and Wildhammer armies marched on his stronghold, Thaurissan attempted to unleash an apocalyptic subterranean entity to save himself. His ritual breached the core of the world and freed Ragnaros the Firelord. The rebirth of Ragnaros violently shattered the surrounding peaks, carving out the blazing caldera of Blackrock Mountain flanked by the Searing Gorge and the Burning Steppes. The sorcerer-thane perished in the cataclysm, and the surviving Dark Irons found themselves bound into perpetual servitude to the Firelord. Over centuries within the lower chambers of the mountain, they constructed the sprawling subterranean capital of Shadowforge City. Their artisans and sorcerers became masters of stone golems, dark sorceries, and steam-driven siege machinery, weaponizing the molten elements around them under the gaze of flamewakers and elemental overlords.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_dark-iron-clan-d0afc6b35acb4efbf397/1-0000.mp3", duration = 98.4816327, start = 0},
  },
}
P.transport["topic:dark-iron-dwarf"] = {
  hash = "1ecf43",
  fullHash = "1ecf43",
  text = "Dark Iron dwarf. Dark Iron dwarves are a distinct dwarven sub-race distinguished by their ashen skin, blazing red eyes, and innate affinity for fire. Banished from Ironforge following the civil War of the Three Hammers, they dwell deep within Blackrock Mountain where their society has fallen under the tyrannical rule of the Firelord, Ragnaros. Unlike their Bronzebeard and Wildhammer cousins, Dark Iron dwarves possess dark gray or soot-black skin and eyes that burn like glowing embers. Their history fractured during the War of the Three Hammers, when their Sorcerer-thane Thaurissan sought to conquer Ironforge. Defeated and driven south into the Redridge Mountains, Thaurissan attempted to summon dark powers to avenge his losses, inadvertently releasing Ragnaros the Firelord from the Elemental Plane. The catastrophic summoning shattered the surrounding peaks into the volcanic waste of Blackrock Mountain and bound the Dark Iron race into fiery servitude. Life in the deep subterranean city of Shadowforge is brutal and unforgiving. While the Dark Irons were once merely ambitious and cunning, generations beneath Blackrock Mountain under the oppressive aura of Ragnaros have warped much of their culture into cruelty, paranoia, and tyranny. Dark Iron law knows only one sentence for infractions: trial by combat in the brutal Ring of the Law. Poisoning and political intrigue are so prevalent that Dark Iron travelers customarily pack their own rations rather than trust food from strangers. Not all Dark Iron dwarves serve Emperor Dagran Thaurissan and the cult of Ragnaros. Dissident factions have broken away to pursue their own ends. The most prominent among them is the Thorium Brotherhood, a guild of master smiths based out of Thorium Point in Searing Gorge who have defected from the main clan to hire outside adventurers against their former masters. Others operate as mercenaries, spies, or trade engineers alongside neutral organizations like the Venture Company.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_dark-iron-dwarf-c0e5b1e4c9a789ec51a6/1-0000.mp3", duration = 115.147755, start = 0},
  },
}
P.transport["topic:dark-riders"] = {
  hash = "5f592c",
  fullHash = "5f592c",
  text = "Dark Riders. The Dark Riders are a band of mysterious, hooded horsemen who terrorize Duskwood. Merciless hunters of magical relics, they strike from hiding and leave only slaughter in their wake. Little is known of the Dark Riders' origins. Witnesses describe hooded horsemen who speak in voices both harsh and shrill, and one was seen using a small gem to take orders from a master it called only its 'Lord'. They hunt objects of magical power across the kingdom, cutting down anyone who stands between them and their prize.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_dark-riders-4bc8af0abdeb174075a5/1-0000.mp3", duration = 29.3616327, start = 0},
  },
}
P.transport["topic:elune"] = {
  hash = "7d356d",
  fullHash = "7d356d",
  text = "Elune. Elune is the revered moon goddess of Azeroth, worshipped primarily by the night elves as their benevolent protector and mother of the forest demigod Cenarius. Associated with the larger moon, the White Lady, she governs peace, healing, and lunar fury across the world. In tauren myth, she is honored as Mu'sha, the gentle left eye of the Earth Mother. Elune is one of the few true deities acknowledged across Azeroth, bound inseparably to the night sky and the larger of the world's two moons, the White Lady. While never appearing in a physical form on the world, night elven artisans portray her as a kaldorei of transcendent grace, bathed in luminescence with alabaster skin, silver hair, and eyes of pure moonlight. Ancient legends among the kaldorei claim she once rested in the depths of the Well of Eternity during the daylight hours, whispering wisdom to the early night elves. Night elven spiritual and civil life is anchored in devotion to Elune through the Sisterhood of Elune, an ancient matriarchal priesthood led by High Priestess Tyrande Whisperwind. The Sisters invoke Elune's grace to mend lethal wounds, but they can also channel her radiant wrath to call down searing starlight upon their enemies. Her divine union with the Great White Stag, Malorne, produced Cenarius, binding Elune's heavenly mysteries directly to the druidic traditions that tend the wildlands of Kalimdor. Though renowned for peace, harmony, and tranquil restoration, Elune is not a gentle pacifist. As the Night Warrior, she acts as a fierce patron of battle who gathers the spirits of fallen heroes from the field and places them in the heavens to ride across the night as stars. Beyond the kaldorei, the nomadic tauren know her as Mu'sha, the radiant left eye of the Earth Mother, who illuminates the night and guides wandering hunters alongside her fiery twin brother, An'she the sun.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_elune-e96b8539742cfee3bcd0/1-0000.mp3", duration = 111.46449, start = 0},
  },
}
P.transport["topic:emerald-dream"] = {
  hash = "8988fb",
  fullHash = "8988fb",
  text = "Emerald Dream. The Emerald Dream is a vast, ever-shifting spirit realm representing Azeroth in its primordial state, completely untouched by civilization. Watched over by the Dragon Aspect Ysera and her green flight, it serves as the spiritual blueprint of nature and the sacred domain where druids commune with the cycle of life. Existing outside the physical plane yet tethered to its heartbeat, the Emerald Dream reflects what Azeroth would look like had intelligent beings never cleared its forests or built cities upon its stone. Sculpted during the ancient ordering of the world, it is an ever-shifting wilderness of pristine forests, boundless plains, and primordial rivers. Time and distance hold little meaning within the Dream; days in the physical world can feel like decades in the spirit, and landmarks change shape like mist before mortal eyes. Following the ordering of the world, the titans entrusted this verdant plane to Ysera the Dreamer, the great Aspect of the green dragonflight. Charged with guiding the evolution and natural rhythm of Azeroth, Ysera dwells in an unending trance, gazing through enchanted dreamsight that perceives both the waking world and its mirrored spirit plane. The green dragons guard the rare, natural portals linking the physical plane to the Dream, maintaining eternal vigilance over the boundary between sleep and waking. To mortal druids, the Emerald Dream is the wellspring of their craft. By channeling nature magic, druids can project their spirits into the Dream, leaving their corporeal bodies resting safely in barrow dens for years or even centuries. In this untamed realm, they commune with ancient nature spirits and the Wild Gods, gaining profound insight into the Great Cycle of life and death. Skilled walkers of the Dream learn to transcend physical laws while in their dreamforms, traversing vast distances or slipping through solid barriers at will.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_emerald-dream-317e4c724c578d9d03ab/1-0000.mp3", duration = 114.520816, start = 0},
  },
}
P.transport["topic:first-war"] = {
  hash = "052f06",
  fullHash = "052f06",
  text = "First War. The First War was the devastating five-year conflict in which the Orcish Horde emerged through the Dark Portal and completely destroyed the human Kingdom of Stormwind. Orchestrated behind the scenes by the demon-possessed Guardian Medivh and the warlock Gul'dan, it concluded with the assassination of King Llane Wrynn I and the flight of human survivors north to Lordaeron. Before the war, the Kingdom of Stormwind enjoyed long years of peace following the Gnoll War, guarded by its Knights and the Clerics of Northshire Abbey. That stability shattered when the Guardian Medivh, secretly possessed by the demon lord Sargeras, contacted the orc warlock Gul'dan on Draenor. Together, they forged the Dark Portal in the swampy Black Morass. Driven by demon blood and the slow death of their homeworld, the Orcish Horde crossed into Azeroth in force. Early rumors dismissed the invaders as vengeful spirits or strange offshoots of trolls, but Sir Anduin Lothar's scouting patrols quickly confirmed the arrival of a disciplined, bloodthirsty army. Led openly by Warchief Blackhand and manipulated from the shadows by Gul'dan's Shadow Council, the Horde overran the southern reaches of the kingdom. While an attempt by the orcs to push into Stranglethorn Vale against the Gurubashi trolls failed, their campaign across human territory proved catastrophic. The Horde conquered outward until only Elwynn Forest remained under human control. Blackhand launched a first direct assault on Stormwind City, but Sir Anduin Lothar repelled the invasion with a brilliant, surprise flanking counterattack by sea, temporarily saving the capital from annihilation.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_first-war-6fd7901023f767b461f8/1-0000.mp3", duration = 96.9926531, start = 0},
  },
}
P.transport["topic:frostmane-tribe"] = {
  hash = "305eea",
  fullHash = "305eea",
  text = "Frostmane tribe. The Frostmane tribe consists of fierce ice trolls indigenous to the frigid peaks of Dun Morogh. Driven into caves and remote ridges by the dwarves of Ironforge centuries ago, they wage an unrelenting guerrilla war to reclaim their ancestral home. Long before the Bronzebeard clan united under Ironforge, the Frostmane trolls held dominion across the snowbound expanses of Dun Morogh. The rise and expansion of the dwarven kingdom crushed their realm, pushing the surviving ice trolls into retreat along the frozen ridges and crags. This humiliating defeat sparked a bitter generational hatred that endures to this day. The Frostmane treat every mountaineer, traveler, and homestead as an invading enemy to be driven out or slaughtered. For decades, the Ironforge Senate regarded the Frostmane as little more than a persistent nuisance lurking in the hills. However, the sudden emergence of the trogg menace deep beneath Dun Morogh has thrown dwarven defense into disarray. Sensing an opportune moment while the mountaineers are overwhelmed and dwarven forces fight Alliance wars abroad, the Frostmane have launched renewed and violent raids from strongholds such as Frostmane Hold and Shimmer Ridge to retake their ancient territories.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_frostmane-tribe-e82d3f5a325ca65acde4/1-0000.mp3", duration = 70.8963265, start = 0},
  },
}
P.transport["topic:gnoll"] = {
  hash = "76806d",
  fullHash = "76806d",
  text = "Gnoll. Gnolls are a savage, hyena-like race of humanoid scavengers and raiders found scattered across both the Eastern Kingdoms and Kalimdor. Renowned for their vicious infighting, brutal strength, and animal cunning, they survive by pillaging settlements, butchering wildlife, and ambushing unwary travelers. Left unchecked, their sprawling packs and warlords pose a constant threat to frontier hamlets and trade roads alike. Standing slightly shorter than the average human but possessing explosive physical power, gnolls are bipedal hyena-kin known for their spiky teeth, thick pelts, and distinct barking laugh. While fully capable of walking upright, they often drop to all fours to lope swiftly through brush or track prey by scent. Gnoll culture values raw physical dominance above all else. They organize into fractious packs led by the strongest, cruelest alpha, only yielding when battered into submission by a superior force. Though usually fractured by petty squabbles, united gnolls once waged open war on the kingdom of Stormwind. Stormwind's armies prevailed in that Gnoll War, and the kingdom enjoyed a lasting peace afterward until the orcs came through the Dark Portal. Gnoll menace is not limited to the human south. In northern Lordaeron, the Scourge necromancer Thule Ravenclaw raises undead Rot Hide gnolls to dig up corpses across Tirisfal and Silverpine. Near Hillsbrad, the Mudsnout harvest foul, toxic blossoms among ruined farmsteads. Across the Great Sea in Kalimdor, the Palemane pack butchers game across Mulgore despite tauren efforts to make peace, while the Woodpaw of Feralas wage a desperate, frenzied war against encroaching silithid swarms.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_gnoll-594a7a285d5b8276d393/1-0000.mp3", duration = 102.739592, start = 0},
  },
}
P.transport["topic:gnome"] = {
  hash = "6f99ae",
  fullHash = "6f99ae",
  text = "Gnome. Gnomes are a diminutive, eccentric, and astonishingly intelligent race renowned across Azeroth for their inventive engineering and mastery of the arcane. Despite their cheerful demeanor, they recently suffered a catastrophic tragedy when a subterranean trogg invasion and a disastrous defense plan irradiated their capital of Gnomeregan. Now living as refugees in Ironforge's Tinker Town, the gnomes remain staunch Alliance allies as they fight to reclaim their lost home. Small in stature but towering in intellect, gnomes approach the world with boundless curiosity and scientific ambition. While other races focus on recording histories and preserving traditions, gnomes look relentlessly forward, dedicating their lives to mechanical engineering, arcane studies, and technological innovation. Their inventions—ranging from clockwork devices and flying machines to complex subterranean trains—have shaped the modern world. Even after devastating hardships, gnomefolk maintain an irrepressible cheerfulness and an unshakable drive to rebuild and solve the impossible. The gnomes made their home in the frozen crags of Dun Morogh, and when they met the dwarves of Ironforge, the two peoples discovered an immediate kinship. Dwarven brawn and gnomish ingenuity united to carve out the marvelous subterranean techno-city of Gnomeregan in western Dun Morogh, where the gnomes are led by visionary leaders known as High Tinkers. The surviving gnomes fled their poisoned home, finding sanctuary among their dwarven cousins in Ironforge. High Tinker Mekkatorque and his people established a bustling enclave in Ironforge's Tinker Town, continuing to support the Alliance and oversee the Deeprun Tram linking Ironforge to Stormwind. From this adopted quarter, gnomish commandos and brave volunteers constantly mount expeditions into Gnomeregan's irradiated depths, striving to clear out the troggs, deal with mechanical abominations, and someday reclaim their grand city.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_gnome-d4d2365221a1bc53d951/1-0000.mp3", duration = 116.662857, start = 0},
  },
}
P.transport["topic:goblin"] = {
  hash = "cac159",
  fullHash = "cac159",
  text = "Goblin. Goblins are diminutive, cunning humanoids originating from the Isle of Kezan, renowned across Azeroth for their relentless pursuit of profit, explosive engineering, and aggressive trade cartels. While most maintain a stance of strict neutrality to maximize commerce between the Alliance and Horde, mercenary and cutthroat outfits like the Venture Company and Steamwheedle Cartel leave an indelible mark on every corner of the world. Goblins hail from the Isle of Kezan in the South Seas, where their society long ago divided into competing economic syndicates known as cartels. Rather than building kingdoms or armies of their own, goblin leaders channeled their ambitions into cutthroat mercantilism, volatile engineering, and industrial ventures that now reach every corner of the world. During the Second War, Trade Prince Steamwheedle allied his cartel with Orgrim Doomhammer's Horde, supplying maps, siege craft, and fleet-building expertise in exchange for Stormwind's captured plunder. Following the Horde's eventual defeat, the cartels learned that open allegiance cost them lucrative markets. In the modern era, the major cartels claim official neutrality, maintaining bustling trade havens like Booty Bay in Stranglethorn Vale and Gadgetzan in the Tanaris desert. Here, Alliance and Horde travelers cross paths without blades drawn—so long as port bruisers keep the peace.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_goblin-3e705b986fb1aeb77d2b/1-0000.mp3", duration = 79.3861224, start = 0},
  },
}
P.transport["topic:grimtotem-tribe"] = {
  hash = "7b8e92",
  fullHash = "7b8e92",
  text = "Grimtotem tribe. The Grimtotem tribe is an aggressive, fiercely traditionalist tauren clan that refuses to formally swear allegiance to Thrall's Horde. Distinguishable by their dark hides and fierce warpaint, they seek to purge foreign races from Kalimdor and retake ancestral lands by any means necessary. Even as their matriarch, the Elder Crone Magatha Grimtotem, resides atop Thunder Bluff playing regional politics, her kin actively raid settlements across Kalimdor. Unlike their peaceful cousins who honor the Earth Mother through reverence, the Grimtotem believe Kalimdor belongs exclusively to the tauren. From youth, they are trained not in the patient harmony of the Great Hunt, but in ruthlessness, stealth, and lethal combat. They harbor immense disdain for the other races that have settled upon their ancient soils. Though Cairne Bloodhoof has welcomed them into Thunder Bluff in an effort to unite all tauren people, the Grimtotem clan stands alone as the only major tribe that has never formally joined Thrall's Horde, maintaining their own insular and violent agenda. In the wilderness far from Thunder Bluff's watchful eyes, Grimtotem hostility flares openly into violence. In Stonetalon Mountains, they butcher local settlements and threaten Horde supply outposts. Across the towering mesas of Thousand Needles, centered around Darkcloud Pinnacle, they constantly menace Freewind Post and plot to seize the canyon. Encounters in Feralas prove equally perilous: the Grimtotem attack Horde travelers, Alliance caravans, and fellow tauren without hesitation. Horde garrisons at Sun Rock Retreat and Camp Mojache regularly post bounties and dispatch warriors to cut down these violent outcasts.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_grimtotem-tribe-79bd833bc77fb3434617/1-0000.mp3", duration = 101.746939, start = 0},
  },
}
P.transport["topic:grommash-hellscream"] = {
  hash = "6854bc",
  fullHash = "6854bc",
  text = "Grommash Hellscream. Grommash Hellscream was the legendary chieftain of the Warsong clan, a close brother-in-arms to Warchief Thrall, and the first orc to drink the blood of Mannoroth. Though his thirst for battle once bound his people to the Burning Legion, he redeemed the orcish race by slaying the demon lord in Ashenvale at the cost of his own life. Before the Dark Portal ever bridged worlds, Grom Hellscream led the Warsong clan with unyielding ferocity, distinguished by his pitch-black tattooed jaw and the deadly sweep of his two-handed axe, Gorehowl. When Gul'dan and the Shadow Council offered the chalice of demonic strength on Draenor, Grom was the first chieftain to drink the blood of the pit lord Mannoroth. That fateful draught doomed the orcish race to demonic subservience and a burning bloodlust. Yet unlike many chieftains who perished or succumbed entirely, Grom possessed an iron will that kept his fierce spirit intact, surviving the horrors of the old Horde while harboring an unspoken ache for what his people had surrendered. Kept behind on Draenor during the Second War, Grom later crossed through the Dark Portal only to be stranded when the rift was shattered. For nearly fifteen years, Grom and his surviving Warsong warriors evaded the Alliance of Lordaeron, enduring the lethargy and despair that fell upon the orcs after the demon blood faded. Hope rekindled when a young fugitive named Thrall sought him out in the wilderness. Recognizing Thrall's strength and noble heart, Grom mentored him in the proud heritage of their people. Alongside Orgrim Doomhammer, the two rallied their disparate clans, broke open the human internment camps, and ignited the birth of the New Horde. Upon arriving in Kalimdor during the Third War, Grom's unquenched aggression resurfaced in the ancient forests of Ashenvale. Beset by the night elves and the demigod Cenarius, Grom succumbed once more, drinking from a corrupted fountain infused with Mannoroth's blood to save his clan. Enslaved anew by the demon lord, Grom turned against his own people until Thrall and Jaina Proudmoore captured and cleansed his corrupted spirit with ancient shamanic and arcane rites. Fully restored to his senses and burdened by immense guilt, Grom pursued Mannoroth into Demon Fall Canyon. In a desperate final strike, he drove Gorehowl into the demon lord's chest, severing the demonic curse forever as hellfire claimed his life.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_grommash-hellscream-95d4bd9414a31253dc95/1-0000.mp3", duration = 141.191837, start = 0},
  },
}
P.transport["topic:highborne"] = {
  hash = "a8d499",
  fullHash = "a8d499",
  text = "Highborne. The Highborne, or quel'dorei, were the aristocratic sorcerer caste of the ancient Kaldorei Empire who served Queen Azshara. Their reckless manipulation of the Well of Eternity brought the Burning Legion to Azeroth, leading to the devastating War of the Ancients and the Great Sundering. Before the Sundering, the Highborne arose as the favored upper class surrounding Queen Azshara. Claiming superiority over common kaldorei through selective bloodlines, intelligence, and opulent privilege, they strictly controlled access to the Well of Eternity. They discovered how to tap and shape its primal arcane energies, erecting magnificent cities across ancient Kalimdor. Their endless thirst for greater sorcery led them to draw deeper from the Well, turning its calm waters turbulent and dark. The ripples of arcane power created by Highborne spellcraft caught the attention of the dark titan Sargeras and the Burning Legion. Convinced by Azshara and her counselor Xavius that the demons would remake the world into an untainted paradise, the Highborne opened a massive gateway within the Well itself. This unleashed the catastrophic War of the Ancients. As demonic hordes slaughtered the populace, rebel forces rallied by Malfurion Stormrage fought to close the portal, causing the Well of Eternity to implode and tear the supercontinent apart. The Highborne fate splintered after the Sundering. Those dragged beneath the waves alongside Azshara were twisted into serpentine naga, while others fell to demonic curses and became satyrs. A faction under Dath'Remar Sunstrider aided the resistance but refused to abandon arcane magic, ultimately suffering exile across the sea to found the high elven kingdom of Quel'Thalas. Today, isolated enclaves like the Shen'dralar remain cloistered in Eldre'Thalas, shunned relics of an empire that nearly destroyed Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_highborne-3b19c6c4be75a12c7336/1-0000.mp3", duration = 111.882449, start = 0},
  },
}
P.transport["topic:juggernaught"] = {
  hash = "c58e70",
  fullHash = "c58e70",
  text = "Juggernaught. A Juggernaught is an enormous, heavily armored battleship bristling with heavy naval cannons. Built with ogre help to serve as the iron core of the Old Horde's fleet during the Second War, these floating fortresses were built to pulverize coastal strongholds and trade routes. Reports of a great vessel beneath Westfall draw attention to the hidden workings of the Defias Brotherhood. Orcs were not traditionally a seafaring culture, so when the Horde required a fleet capable of crossing the Great Sea and contesting the Alliance's naval superiority during the Second War, they relied heavily on ogre ingenuity. The resulting craft—the ogre juggernaught—became the backbone of the Horde armada. Though vastly slower and less nimble than swift troll destroyers, these behemoths carried immense plating and devastating broadside batteries that could shatter Alliance hulls and smash shore fortifications to rubble.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_juggernaught-5adbd22d045c1c021516/1-0000.mp3", duration = 54.804898, start = 0},
  },
}
P.transport["topic:kul-tiras"] = {
  hash = "64b74d",
  fullHash = "64b74d",
  text = "Kul Tiras. Kul Tiras is an insular maritime human kingdom situated on an island archipelago in the Great Sea, west of Dun Morogh and Baradin Bay. Renowned for possessing the mightiest navy in Azeroth, it served as a cornerstone of the Alliance of Lordaeron during the Second War under Grand Admiral Daelin Proudmoore. Following the fracturing of the old Alliance and tragic losses in Kalimdor, the island realm has largely receded into isolated waters. Kul Tiras blossomed into an unmatched seafaring power, sustained by an industrious merchant marine, rich fishing grounds, and a naval armada without peer in human history. When the Orcish Horde swept through the Eastern Kingdoms, Kul Tiras answered the call of King Terenas Menethil II and committed its armada to the Alliance of Lordaeron. Lord Admiral Daelin Proudmoore commanded the naval forces of humanity, waging bloody warfare across the open ocean to sever the Horde's sea lanes and protect coastal shores. However, following the war's conclusion and the eventual splintering of the northern kingdoms, Kul Tiras pulled back its fleets, withdrawing into heavy coastal defense and quiet insularity.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_kul-tiras-d0141186108c63b262a0/1-0000.mp3", duration = 72.6465306, start = 0},
  },
}
P.transport["topic:medivh"] = {
  hash = "d1374e",
  fullHash = "d1374e",
  text = "Medivh. Medivh was the last Guardian of Tirisfal, an ancient order tasked with defending Azeroth from demonic corruption. Bound from before his birth by the spirit of the Dark Titan Sargeras, he opened the Dark Portal and brought the orcish Horde into the world, setting off decades of catastrophic warfare. Medivh was born to the powerful Guardian Aegwynn and the court conjurer Nielas Aran. Centuries earlier, Aegwynn had fought the fallen Titan Sargeras in Northrend, unaware that his dark essence slipped into her body to await an heir. When Medivh reached his fourteenth birthday, the vast magical inheritance bestowed by his mother manifested in a terrifying explosion of power, plunging the boy into a decade-long coma under the watch of the clerics at Northshire Abbey. Awakening from his slumber, Medivh took residence in the isolated tower of Karazhan, serving as court magus to his childhood friend King Llane Wrynn of Stormwind. Yet the dark spirit within him slowly eroded his sanity. Seeking to unleash devastation, Medivh made contact across the stars with the orc warlock Gul'dan and the Shadow Council. Together, they channeled tremendous magic to tear open the Dark Portal, delivering the Horde upon the Eastern Kingdoms and sparking the First War. Medivh was ultimately slain in his tower by his closest friend, Anduin Lothar, and his apprentice, Khadgar.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_medivh-98add26e0a0ad79b7a5a/1-0000.mp3", duration = 81.8155102, start = 0},
  },
}
P.transport["topic:mor-ladim"] = {
  hash = "c86fea",
  fullHash = "c86fea",
  text = "Mor'Ladim. Mor'Ladim is a dangerous, vengeful skeletal warrior wandering the grounds of Raven Hill Cemetery in Duskwood. Formerly the noble knight Morgan Ladimore, he succumbed to profound grief and madness upon discovering the loss of his family, rising in undeath to slaughter anyone crossing his path. Before he became the terror of Raven Hill, Mor'Ladim lived as Morgan Ladimore, a devoted knight and defender of the helpless from Grand Hamlet—the town now known as Darkshire. Married at eighteen to his wife Lys, he raised three children in peace until war summoned him north. Morgan marched alongside Uther the Lightbringer to Lordaeron during the Third War, witnessing the downfall of the Knights of the Silver Hand, the spread of Kel'Thuzad's plague, and the tragic death of Uther himself. Burial brought Morgan no peace. Bound by the heavy guilt of innocent blood and suffocating grief, his corrupted remains rose from the dirt as a hulking skeletal revenant. Calling him Mor'Ladim, travelers and members of the Night Watch quickly learned to dread his name. Armed with his ancestral blade Archeus, the mindless apparition patrols the mist-choked graves, cutting down both beasts and unwary adventurers who venture too close to his resting place.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_mor-ladim-95ef392c275bb259327a/1-0000.mp3", duration = 73.9265306, start = 0},
  },
}
P.transport["topic:murloc"] = {
  hash = "4bf757",
  fullHash = "4bf757",
  text = "Murloc. Murlocs are amphibious, bipedal humanoids famous for their gurgling battle cries, territorial coastal villages, and sudden swarming tactics. Though historically dwelling in the deep ocean, they have steadily migrated inland along the shores, lakes, and rivers of Azeroth, acting with far greater coordination and cunning than their primitive appearance suggests. Murlocs dwell in densely populated settlements along coastlines, riverbanks, and freshwater lakes. Averaging roughly four feet in height, they possess bulbous, slime-coated bodies, wide mouths filled with sharp fangs, and keen vision capable of piercing pitch-black water. While individuals are rarely seen wandering far from their kin, encountering one murloc invariably means a dozen more lurk just beneath the surface. They rely on overwhelming numbers and sharp crude weaponry. Though ancient lineages suggest murlocs have existed beneath the waves since before recorded history, their widespread encroachment onto the landmasses of Lordaeron and Kalimdor is relatively recent. Historians note that this inland migration coincided suspiciously with the reemergence of the serpentine naga from the ocean depths. Some tribes appear to worship deep-sea monstrosities waiting in the oceanic fathoms. Whether fleeing darker terrors or preparing the world for their masters' awakening, their coordinated movement into freshwaters poses a rising threat. Because their garbled language sounds like nonsensical bubbling to outsiders, many dismiss murlocs as mere feral pests. However, their coordinated ambushes, mastery of earth and water magic, and communal structures hint at a sharper intellect. Renowned explorer Brann Bronzebeard has suggested that murlocs are far smarter than civilized races realize, intentionally concealing their cunning. Their impact on global history is undeniable: it was a murloc raid upon the Darkspear tribe that spurred Thrall to intervene, forging the alliance between the orcs and trolls that built the modern Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_murloc-e8534a7e07d5633d0849/1-0000.mp3", duration = 118.543673, start = 0},
  },
}
P.transport["topic:naga"] = {
  hash = "5a88d5",
  fullHash = "5a88d5",
  text = "Naga. The naga are a monstrous, serpentine race dwelling beneath the ocean's depths, ruled by their ancient empress, Queen Azshara. Once the Highborne elite of the Kaldorei Empire, they were warped into amphibious horrors during the Great Sundering ten thousand years ago. Recently emerging from the dark waters, they have seized shorelines across Kalimdor and the Eastern Kingdoms to reclaim their forgotten surface empire. Ten millennia ago, the Highborne nobility of the Kaldorei Empire ruled supreme from their grand capital of Zin-Azshari. Consumed by an obsession with arcane power, Queen Azshara and her inner court tapped the Well of Eternity to draw the gaze of the Dark Titan Sargeras, inviting the catastrophic invasion known as the War of the Ancients. When the Well of Eternity collapsed into ruin, triggering the Great Sundering, the palace slipped into the crushing abyss. Facing utter annihilation, Azshara bargained with the malevolent Old Gods deep below. In exchange for survival, she and her followers were transformed into cold, scaly, serpentine beings bound to the deeps. Submerged at the seafloor beneath the swirling fury of the Maelstrom, the survivors erected the aquatic empire of Nazjatar. Nursing a ten-thousand-year grudge against the surface world, the naga preserved their Highborne arrogance while mutating into distinct casts: hulking, brute-like warriors and multi-armed, spell-weaving sea witches. Under Azshara's unyielding gaze, they perfected their mastery over sea creatures, storm magic, and frost sorcery, slowly rebuilding their strength in wait for an opportunity to strike back against land-dwellers. The naga broke their ten-thousand-year silence during the Third War. Thrall's Horde first encountered the sea witch Zar'jira in the Great Sea, while Lady Vashj answered the summons of Illidan Stormrage, marching naga forces across the ruins of Dalaran. Across the world today, naga encampments encroach aggressively upon coastlines in Azshara, Darkshore, Ashenvale, Desolace, Feralas, Dustwallow Marsh, Hillsbrad, Arathi, and Stranglethorn. Driven by ancient contempt and whispers of the Old Gods, they forge quiet alliances with the Twilight's Hammer and savage satyrs to claim what was once theirs.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_naga-8e7e2e3b49d4c4816823/1-0000.mp3", duration = 136.385306, start = 0},
  },
}
P.transport["topic:new-horde"] = {
  hash = "9b22d8",
  fullHash = "9b22d8",
  text = "New Horde. The New Horde is the modern coalition forged under Warchief Thrall, departing from the bloodthirsty, demon-corrupted Old Horde of the First and Second Wars. Founded upon shamanic tradition, honor, and mutual survival, it unites the liberated orcs, the Darkspear trolls, the tauren tribes of Kalimdor, and a tenuous pact with the Forsaken in Lordaeron. The original Horde was a weapon crafted by the Burning Legion and the Shadow Council, fueling the orcs with demonic bloodlust and driving them across the Dark Portal. After the Second War ended in devastation, surviving orcs were rounded up into Alliance internment camps, sinking into a soul-draining lethargy. Through the efforts of Orgrim Doomhammer, Grommash Hellscream, and the young shaman Thrall, the orcs cast off their demonic shackles, rediscovered their ancestral shamanism, and fought their way to freedom. Following prophetic visions from the mysterious Prophet, Thrall led his people across the Great Sea to the untamed continent of Kalimdor. Along the way, the Horde welcomed Sen'jin's displaced Darkspear trolls. Upon arriving on Kalimdor, Thrall allied with Cairne Bloodhoof and the nomadic tauren, helping drive back hostile centaur tribes. Together, these disparate peoples fought alongside humans and night elves at Mount Hyjal, breaking the Burning Legion's invasion and carving out their new home of Durotar. Today, the New Horde strives to build a durable society from their fortified capital of Orgrimmar. While anchored by the strong bond between orcs, Darkspear trolls, and tauren, survival has forced Thrall to accept uncomfortable alliances—chief among them Sylvanas Windrunner and the Forsaken in the ruins of Lordaeron. Thrall pursues an uneasy peace with the Alliance, but old enmities, resource shortages, and hawkish elements among both factions keep borders simmering on the brink of war.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_new-horde-15885a5ea7d4744ff0ed/1-0000.mp3", duration = 111.438367, start = 0},
  },
}
P.transport["topic:night-watch"] = {
  hash = "554b64",
  fullHash = "554b64",
  text = "Night Watch. The Night Watch is the beleaguered town militia responsible for defending Darkshire and the shadowy roads of Duskwood. Abandoned by the House of Nobles in Stormwind, these local volunteers stand alone against roaming undead, feral worgen, and lurking necromancy. Led by Commander Althea Ebonlocke, they rely heavily on visiting adventurers to keep darkness from overtaking their home. When foul magic overtook the once-vibrant Grand Hamlet and turned the forest into Duskwood, the kingdom of Stormwind turned its back. Following King Varian Wrynn's disappearance, the royal garrison was pulled back to the capital. Stripped of official royal troops and supplies, the townsfolk formed their own volunteer militia—the Night Watch—swearing to hold the borders of Darkshire against the creeping horrors of the woods. Operating out of their headquarters in Darkshire, the Watchers patrol along roads perpetually choked with unnatural mist. Their adversaries are relentless: ravenous skeletal fiends and ghouls spilling outward from Raven Hill and Tranquil Gardens cemeteries, alongside terrifying feral worgen prowling Roland's Doom and Brightwood Grove. Severely outmatched in numbers and resources, the militia has lost many of its finest defenders to ruthless threats like the wandering skeletal warrior Mor'Ladim. Commander Althea Ebonlocke, daughter of Darkshire's mayor, directs the defensive effort with grim pragmatism. Lacking veteran reinforcements, she enlists any capable traveler arriving at town to thin out skeletal legions, cull starving wolf packs, or investigate mysterious local murders. The Night Watch views itself as the final bulwark preserving human life in the region; if their lines break, Darkshire falls entirely into the shadow.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_night-watch-6ab29d21b371563cc29e/1-0000.mp3", duration = 104.489796, start = 0},
  },
}
P.transport["topic:nordrassil"] = {
  hash = "ba7450",
  fullHash = "ba7450",
  text = "Nordrassil. Nordrassil, the 'Crown of the Heavens,' is the original World Tree planted atop Mount Hyjal to shield the second Well of Eternity. Blessed by the Great Dragon Aspects, it granted the night elves ageless immortality and a deep connection to the Emerald Dream for ten thousand years. Its sacrifice during the climax of the Third War broke Archimonde's assault, leaving the tree wounded and the night elves mortal. Ten thousand years ago, in the ashes of the Great Sundering, Illidan Stormrage cast vials of the original Well of Eternity into a mountaintop lake atop Mount Hyjal, birthing a new font of arcane power. To prevent this raw magic from corrupting the world or drawing the Burning Legion anew, the Dragon Aspect Alexstrasza planted an acorn from the Mother Tree, G'Hanir, directly over the waters. From it grew Nordrassil. The roots spread deep beneath Azeroth, sealing the Well's volatile energies and distributing gentle, life-giving vigor across the continents. Nordrassil became the spiritual and cultural heart of night elf civilization through the blessings of three Great Dragon Aspects. Alexstrasza imbued the tree with peerless vigor, extending vitality to the kaldorei. Ysera bound the tree to the Emerald Dream, allowing night elven druids to enter her slumbering realm with effortless clarity. Crucially, Nozdormu the Timeless One cast his blessing across its boughs: as long as the colossal tree stood, the night elves would never age or fall prey to natural disease, gifting an entire race with enduring immortality. Nordrassil's tranquility ended with the Third War, when the demon lord Archimonde marched upon Mount Hyjal to tear the tree apart and claim the Well's infinite power. With mortal defenders pushed to the brink, Malfurion Stormrage made the ultimate choice. Sounding the Horn of Cenarius, he called upon thousands of nature spirits and unleashed the stored enchantments within Nordrassil itself. The ensuing cataclysmic blast obliterated Archimonde and decimated the Legion. Though Nordrassil survived to heal slowly, its enchantments shattered—stripping the night elves of their beloved immortality.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_nordrassil-e5501edeffdb33af617d/1-0000.mp3", duration = 133.146122, start = 0},
  },
}
P.transport["topic:old-horde"] = {
  hash = "799acd",
  fullHash = "799acd",
  text = "Old Horde. The Old Horde was the blood-crazed coalition of orcish clans manipulated by demonic power into conquering Draenor and invading Azeroth. Led first by Blackhand and later by Orgrim Doomhammer, its path of destruction shaped the First and Second Wars until its decisive defeat by the Alliance of Lordaeron. Today, Thrall's New Horde seeks to overcome that dark legacy, while isolated remnants like the Dark Horde still cling to its bloody past. Before it crossed into Azeroth, the Horde was forged on Draenor through demonic manipulation. The demon lord Kil'jaeden used the warlock Gul'dan and the elder shaman Ner'zhul to corrupt the proud, spiritual orc clans. As elemental spirits abandoned the warring orcs, shamanistic traditions were cast aside for warlock magic. Sealed by the consumption of the blood of Mannoroth, the clans surrendered to bloodlust, slaughtering the draenei and draining their homeland of life. With Draenor's lands withering away and resources exhausted, the warlock Gul'dan and the possessed human guardian Medivh opened the Dark Portal into Azeroth. The Horde poured through, igniting the First War against the Kingdom of Stormwind. Under Warchief Blackhand—and the covert strings of Gul'dan's Shadow Council—the Horde battered the southern realm. Toward the war's conclusion, Orgrim Doomhammer slew Blackhand and purged the Shadow Council, taking command of the Horde and razing Stormwind to the ground. Orgrim Doomhammer drove the Horde north across the seas into the Second War, forging alliances with forest trolls and goblin mercenaries. However, at the height of the siege of Lordaeron, Gul'dan deserted the war effort with his loyalists to seek the Tomb of Sargeras. Fractured and reeling from the betrayal, the Horde was pushed back to Blackrock Mountain and crushed by the Alliance of Lordaeron. Defeated, their portal destroyed, surviving orcs were herded into internment camps, afflicted with lethargy as the demonic blood haze faded.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_old-horde-abdf1299450185ac25df/1-0000.mp3", duration = 118.360816, start = 0},
  },
}
P.transport["topic:pirate"] = {
  hash = "96fd15",
  fullHash = "96fd15",
  text = "Pirate. Pirates and buccaneers are lawless seafaring plunderers operating across the Great Sea and coastal waters of Azeroth. Preying on Alliance, Horde, and neutral merchant vessels alike, they band together under loose flags to seize wealth, capture cargo, and control coastal coves. Their violent presence drives constant naval skirmishes from the waters of Kalimdor to the shores of the Eastern Kingdoms. Pirates—often called buccaneers, corsairs, or freebooters—are maritime raiders of nearly every race who make their living seizing ships and raiding coastal settlements. Their operations stretch far beyond simple robbery; crews regularly engage in smuggling, kidnappings, and mercenary contracts for whoever has coin. With the chaos left behind by the Third War and the collapse of northern kingdoms, naval enforcement has fractured, giving pirate factions the freedom to carve out fortified footholds on neglected islands and coastal coves. Despite common tales painting pirate life as one of romantic adventure, life aboard a buccaneer vessel is brutal and short. Crews endure squalid, rat-infested holds, harsh discipline, and the ever-present threat of scurvy, fought off only with supplies of limes. Betrayal is an everyday hazard, and captains maintain their command solely through strength and fear of punishment, which ranges from immediate execution to being marooned or fed to sharks. When battles end, buccaneers celebrate with roaring bouts of dice, song, and heavy rum. While independent crews roam every sea lane, major organizations wield enough ships to contest sovereign navies. The Southsea Freebooters harass shipping throughout the waters surrounding Kalimdor, while the notorious Bloodsail Buccaneers menace the southern seas and wage open war against the Steamwheedle Cartel in Booty Bay.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_pirate-b117541f4ab49b74983a/1-0000.mp3", duration = 106.13551, start = 0},
  },
}
P.transport["topic:plague-of-undeath"] = {
  hash = "41b387",
  fullHash = "41b387",
  text = "Plague of Undeath. The Plague of Undeath is a supernatural contagion concocted by the Lich King under the direction of the Burning Legion to scourge northern Eastern Kingdoms. Transmitted through infected grain, airborne cauldrons, and tainted waterways, the sickness rapidly kills living mortals and raises them as mind-bound thralls of the Scourge. The plague was devised by the fallen shaman Ner'zhul after he was transformed into the Lich King by Kil'jaeden. From his icy seat atop the Frozen Throne in Northrend, Ner'zhul perfected the sickness as an unholy vanguard for the Burning Legion's invasion. Testing his power on isolated human villages across Northrend, he discovered that he could snuff out life and psychically command the corpses that arose shortly after. Ner'zhul's telepathic summon reached across the Great Sea to the Kirin Tor mage Kel'Thuzad, who abandoned Dalaran to serve the entity. Kel'Thuzad organized the secretive Cult of the Damned, whose mortal infiltrators laid the groundwork to poison Lordaeron from within. The blight extends far beyond humanity. While non-human fauna generally suffer sickening fevers or rot rather than rising as undead thralls, the land itself bears the brunt of demonic and necromantic decay. Across the Plaguelands, massive plague cauldrons pump alchemical and magical vapors directly into the atmosphere, corrupting the surrounding land, where carrion grubs and colossal spore-choked mushrooms thrive. The Argent Dawn actively battles this airborne corruption by sabotaging these cauldrons, reversing their catalytic mixtures to burn the Scourge rather than feed it. Meanwhile, in the Undercity, the Royal Apothecary Society experiments tirelessly to refine a New Plague designed to slay both living foes and the undead.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_plague-of-undeath-dacd4898d3137e2265e2/1-0000.mp3", duration = 105.508571, start = 0},
  },
}
P.transport["topic:quilboar"] = {
  hash = "c54785",
  fullHash = "c54785",
  text = "Quilboar. Quilboar are aggressive, boar-like humanoids native to central Kalimdor, renowned for their sharp spinal quills and relentless territorial savagery. Claiming descent from the fallen demigod Agamaggan, they dwell within dense mazes of razor-sharp brambles across Durotar, Mulgore, and the Barrens. Their fierce struggle over water, soil, and sacred ground makes them a constant threat to travelers and Horde settlements. Quilboar revere Agamaggan, the colossal boar Ancient who perished battling the Burning Legion during the War of the Ancients ten thousand years ago. According to their sacred traditions, the quilboar are his mortal offspring. Where Agamaggan bled and died across central Kalimdor, enormous thorny vines erupted from the scorched earth, forming sprawling root-mazes that the quilboar treat as holy ground. His crystallized blood endures across the Barrens as crimson Blood Shards, which their geomancers dig up and revere as powerful talismans. Rather than building traditional towns of stone or timber, quilboar cultivate colossal briars that choke surrounding vegetation and render nearby ground barren. Tribes are typically guided by powerful geomancers—practitioners of an earthbound, crude shamanism who consult stones and crystals to direct the clan. These mystics call upon Agamaggan's spirit to summon spectral boars into combat. Because the arid central plains offer few oases, quilboar view water as the ultimate treasure; they stage lavish feasts when rare rains fall and defend water holes with vicious tenacity. For generations, quilboar clashed bitterly with the nomadic tauren and roaming centaur packs. When Thrall led the Orcish Horde into Kalimdor, orcs rapidly colonized Durotar and established trade routes through the Barrens, driving displaced tribes into open revolt. Quilboar war parties ambush supply wagons, are suspected of frightening tallstriders into wagon trains, and stage raids on outposts like Crossroads and Camp Taurajo. Two principal tribes dominate the open plains: the Razormane and the Bristleback, both engaged in simultaneous feuds against the Horde and each other.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_quilboar-fc25491aeaea7cd37c7d/1-0000.mp3", duration = 131.082449, start = 0},
  },
}
P.transport["topic:ravenholdt"] = {
  hash = "0c8208",
  fullHash = "0c8208",
  text = "Ravenholdt. Ravenholdt, also known as the Assassin's League, is an elite guild of rogues, thieves, and killers based out of a secluded mountain manor above the Hillsbrad Foothills. Led by Lord Jorach Ravenholdt, the league maintains strict neutrality from faction politics while waging an unending shadow war against their bitter rivals, the Syndicate. They test and recruit only the most cunning operatives across Azeroth, valuing peerless discipline, stealth, and lethal efficiency above all else. Tucked away in the craggy mountains connecting Hillsbrad to Alterac, Ravenholdt Manor serves as the nerve center for Azeroth's premier brotherhood of assassins. Led by Lord Jorach Ravenholdt, the organization operates far beyond the jurisdiction of kings and warchiefs. Within its walls, master specialists hone every lethal art: Master Kang instructs disciples in close combat and assassination, the Thunderwood brothers brew rare and deadly poisons, and gnome craftsmen engineer intricate locks to test fledglings. To non-rogues, entering the estate is an overt flirtation with death, where an unwary step easily ends with a poisoned dagger in the ribs. For years, Ravenholdt has been locked in an escalating feud with the Syndicate, an aristocratic criminal cartel infesting Alterac and Arathi. While the League regards the Syndicate as clumsy, arrogant amateurs, their sheer numbers make them impossible to eradicate through simple slaughter. Instead, Ravenholdt employs psychological and structural disruption: by tasking contracted rogues with pickpocketing the signet emblems worn by Syndicate ringleaders, the League relies on the Syndicate's own paranoia and cutthroat hierarchy to execute disgraced members internally.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_ravenholdt-60675eb1a3de89b5f783/1-0000.mp3", duration = 101.903673, start = 0},
  },
}
P.transport["topic:razorfen"] = {
  hash = "fe4ab7",
  fullHash = "fe4ab7",
  text = "Razorfen. Razorfen is the collective name associated with the predominant quilboar tribe of southern Kalimdor and their sprawling thorn-choked settlements. Carved into massive briars along the southern border of the Barrens and the edge of Thousand Needles, Razorfen encompasses the strongholds of Razorfen Kraul and Razorfen Downs. It serves as both the spiritual heart and the central bastion of quilboar power. According to legend, the colossal thorned brambles that make up the Razorfen sprouted ten thousand years ago during the War of the Ancients. When the giant boar Ancient, Agamaggan, fell in battle against the Burning Legion, his blood seeped into the earth wherever he bled and died. From that divine sacrifice grew massive vines of petrified bramble and iron-hard thorns, creating a natural fortress where his descendants, the quilboar, have dwelled ever since. The Razorfen tribe is among the most aggressive and entrenched of all quilboar populations. Rather than scattering into open warrens, they built complex labyrinthine communities directly within the colossal briars. From these fortresses, the tribe fiercely defends their ancestral territory against neighboring tauren tribes, Horde settlements in the Barrens, and any outsiders daring to trespass into their holy grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_razorfen-db56b222194c6e5b79f6/1-0000.mp3", duration = 75.0759184, start = 0},
  },
}
P.transport["topic:riverpaw-pack"] = {
  hash = "3e6b61",
  fullHash = "3e6b61",
  text = "Riverpaw pack. The Riverpaw pack is a savage clan of gnolls inhabiting the borderlands of Elwynn Forest and Westfall. Known for their brutal raids and ruthless dominance over local kobolds, they have grown increasingly organized and brazen following the Third War. With Stormwind's military stretched thin, their presence threatens vital roads and settlements throughout the heartland. For decades, the Riverpaw clan prowled the fringes of human civilization, but their boldness has surged in recent years. In Elwynn Forest, packs led by the infamous brute Hogger prowl the southern woods around Forest's Edge and roam the shores of Stone Cairn Lake. In Westfall, they roam across the Dust Plains and along the coasts, ambushing solitary travelers and raiding homesteads. Deputy Rainer at Westbrook Garrison and Captain Danuvin at Sentinel Hill rely heavily on mercenary blades to cull their numbers, issuing standing bounties for painted armbands and severed paws. Beyond petty ambushes, the Riverpaws exhibit an unusual drive for conquest and labor. They drove a clan of kobolds out of the Redridge Mountains and forced them into the gold mines of Elwynn Forest and Westfall, working the small creatures into relentless exhaustion to extract ore. This cruel tyranny over the mines suggests the gnolls are no longer simple scavengers living hand-to-mouth, but a faction amassing wealth and consolidating strategic ground right under the crown's nose.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_riverpaw-pack-0fd81755d6fedca74c2e/1-0000.mp3", duration = 84.8718367, start = 0},
  },
}
P.transport["topic:royal-apothecary-society"] = {
  hash = "f64484",
  fullHash = "f64484",
  text = "Royal Apothecary Society. The Royal Apothecary Society is an alchemical guild established under Lady Sylvanas Windrunner and based in the Apothecarium beneath the Undercity. Composed of Forsaken researchers, its primary mission is compounding a lethal New Plague capable of eradicating the Scourge while claiming vengeance against the living. While Horde allies believe the society seeks a cure for undeath, its researchers actively harvest venoms, slimes, and toxic reagents across Azeroth to perfect weapons of mass destruction. Founded in the wake of the Forsaken's liberation, the Royal Apothecary Society serves as the scientific and alchemical arm of Lady Sylvanas Windrunner's kingdom. From their vats and subterranean laboratories in the Apothecarium, researchers seek to weaponize the very force that damned them. Their preeminent endeavor is the creation of a 'New Plague'—a concoction intended to eradicate the Scourge and destroy the Lich King. Unlike traditional human alchemy, which prioritizes elixirs of healing or transmutation, the Society experiments ruthlessly with foul pathogens, caustic acids, and necromantic blends, raising fallen warhorses as skeletal steeds and brewing deadlier strains of toxic blight. The reach of the Apothecary Society extends far beyond the canals of the Undercity. Field apothecaries are dispatched to remote outposts across Lordaeron and Kalimdor. In Silverpine and Hillsbrad, agents like Apothecaries Renferrel and Lydon gather local floras and distill venoms. In the arid Barrens, Apothecary Helbrim catalogs strange desert flora and creatures, while Apothecary Zamah operates beneath Thunder Bluff in the Pools of Vision. Wherever natural toxins, shifting oozes, or virulent organisms exist, the Society sends acolytes to collect samples for the Apothecarium's cauldrons.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_royal-apothecary-society-68334b7b07729c26e745/1-0000.mp3", duration = 108.930612, start = 0},
  },
}
P.transport["topic:sargeras"] = {
  hash = "ca94fb",
  fullHash = "ca94fb",
  text = "Sargeras. Sargeras is the fallen titan and supreme creator of the Burning Legion, bent on scouring all life from the cosmos. Once the noble champion and defender of the Pantheon, his descent into madness led to the Sundering of ancient Azeroth and nearly every demonic catastrophe since. Before his fall, Sargeras was the greatest and noblest warrior among the titans. Entrusted by the Pantheon of Order to safeguard their grand creations across the Great Dark Beyond, he waged war against the chaotic demons spawned from the Twisting Nether. Incapable of conceiving pure evil, Sargeras trapped countless fiends away within a great prison. Yet eons of relentless warfare against cosmic horrors gradually wore down his altruistic spirit. Over eons of battle, Sargeras's faith in the titans' work eroded. Despairing at the evil he faced, he concluded that creation was fundamentally flawed and that order could never truly prevail. Turning his back on the Pantheon, he shattered the demons' prison, embraced the chaotic fel fire he had once fought, and marshaled the liberated demons into the unstoppable Burning Legion. Ten thousand years ago, the reckless magic of Queen Azshara and her Highborne reached across the stars, alerting Sargeras to Azeroth's existence. Whispering through the depths of the Well of Eternity, the Dark Titan seduced Azshara into opening a portal for his vanguard. Though that ancient invasion culminated in the catastrophic Sundering, Sargeras never ceased scheming to consume Azeroth—orchestrating the opening of the Dark Portal and guiding the demonic corruption of the orcish Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_sargeras-821820b9155123e32272/1-0000.mp3", duration = 95.6604082, start = 0},
  },
}
P.transport["topic:satyr"] = {
  hash = "b238d0",
  fullHash = "b238d0",
  text = "Satyr. Satyrs are twisted, caprine demons born from the curse of the Highborne sorcerer Xavius during the ancient War of the Ancients. Once night elves, they were warped by Sargeras into horned, hooved beasts dedicated to spreading fel corruption, tormenting their former kin, and furthering the Burning Legion's will. Across the wilds of Kalimdor, scattered satyr sects corrupt pristine woodlands, desecrate moonwells, and subvert vulnerable mortal cults. Ten thousand years ago during the War of the Ancients, the Highborne councilor Xavius failed to keep the Burning Legion's initial gateway stable against Malfurion Stormrage. Enraged by this blunder, Sargeras dismantled Xavius's spirit and rebuilt him as a punishment and tool: his torso retained elven features, but he gained wicked horns, taloned claws, a leonine tail, and the cloven lower body of a goat. Sent back into Zin-Azshari, Xavius gleefully passed his fel affliction to other power-hungry Highborne. Though Xavius was struck down, his demonic progeny survived, continually seeking to reproduce their kind by corrupting others. Following the Great Sundering, the surviving satyrs continued to menace the shattered night elf civilization. Over the ages they were broken and driven off, their remnants fracturing into scattered sects that linger in dark forests and ancient ruins while harboring deep hatred for their kaldorei cousins. Today, satyr clans inhabit deep woodland enclaves across Kalimdor, from Darkshore and Ashenvale to Felwood, Azshara, and Feralas. They feed directly on the land's pure magic, leeching and spoiling nature until their hooves swell with drained arcane energy. Satyrs frequently turn peaceful furbolg tribes violent, taint ancient moonwells, and serve as covert liaisons for the Shadow Council and the Burning Blade. While some work alongside Twilight's Hammer cultists or hide within ancient ruins like Dire Maul, all remain bound to the shadow of the Burning Legion.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_satyr-3be11ac347f2b6c1d38d/1-0000.mp3", duration = 123.506939, start = 0},
  },
}
P.transport["topic:scourge"] = {
  hash = "c03797",
  fullHash = "c03797",
  text = "Scourge. The Scourge is an apocalyptic army of undead monsters, necromancers, and enslaved spirits bound to the will of the Lich King. Originally created by the Burning Legion to destabilize Azeroth ahead of the Third War, the legion of walking corpses broke free from demonic control and shattered the kingdoms of Lordaeron and Quel'Thalas. Today, they wage unending war from their arctic stronghold in Northrend and their corrupt dominion over the Plaguelands. The Scourge was born as an instrument of destruction forged by the Burning Legion. The demon lords bound the spirit of the fallen orc shaman Ner'zhul to the Frozen Throne in distant Northrend, fashioning him into the Lich King. With terrifying telepathic power, he was commanded to prepare Azeroth for conquest. The Lich King unleashed the Plague of Undeath southward into the unsuspecting human realm of Lordaeron, relying on the mortal traitors of the Cult of the Damned to poison grain supplies. Those who perished arose not as restful dead, but as twisted thralls entirely subservient to the Lich King's iron mind. The Scourge achieved total devastation when Prince Arthas Menethil fell to the Lich King's whispers. Seeking vengeance in Northrend, Arthas claimed the cursed blade Frostmourne and forfeited his soul, becoming the Scourge's paramount death knight. Returning home, Arthas slew his father King Terenas, butchered Capital City, and unleashed the undead horde across Lordaeron. The Scourge swept through towns like Darrowshire and Andorhal, butchered the Silver Hand paladins, destroyed Dalaran to summon Archimonde, and carved a dead scar through Quel'Thalas to resurrect Kel'Thuzad as a lich. The Lich King never intended to serve the Burning Legion permanently. Through Arthas, Ner'zhul secretly engineered the Legion's defeat by goading Illidan Stormrage into slaying the dreadlord Tichondrius in Felwood. Enraged, the demon lord Kil'jaeden later ordered Illidan to obliterate the Frozen Throne. Illidan's assault fractured the icy prison, causing the Lich King's mental grip over his minions to waver. Seizing on this weakened control, a faction of free-willed undead led by the resurrected banshee Sylvanas Windrunner broke away, christened themselves the Forsaken, and seized the ruins of Lordaeron. Though weakened by the fracturing of the Frozen Throne and the rebellion of the Forsaken, the Scourge remains the deadliest force in the northern world. Led in the field by the lich Kel'Thuzad, its abominations, crypt fiends, and necromancers dominate the corrupted Eastweald and Westweald, now known as the Plaguelands. From grim bastions and blighted fields, they continuously wage war against the Forsaken of the Undercity, the fanatic zealots of the Scarlet Crusade, and the remaining enclaves of the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_scourge-369f12b461ee94d90f71/1-0000.mp3", duration = 164.022857, start = 0},
  },
}
P.transport["topic:second-war"] = {
  hash = "e9dc82",
  fullHash = "e9dc82",
  text = "Second War. The Second War was the continent-spanning clash across the Eastern Kingdoms between the Orcish Horde and the newly forged Alliance of Lordaeron. Sparked after the sack of Stormwind, the war devastated Khaz Modan and northern human realms before turning at the gates of Capital City. It ended in the destruction of the Dark Portal and the dispersal of the old Horde. Following the fall of Stormwind during the First War, Regent Anduin Lothar led human refugees north across the Great Sea to Lordaeron. King Terenas Menethil II convened the Council of Seven Nations, forging the Alliance of Lordaeron alongside the high elves of Quel'Thalas, the Bronzebeard dwarves of Ironforge, and the gnomes of Gnomeregan. Meanwhile, Warchief Orgrim Doomhammer consolidated the Horde, forging alliances with forest troll tribes and the Steamwheedle Cartel while subjugating red dragons through the Dragonmaw clan to invade the northern continents. The Horde launched devastating land and naval offensives, quickly overrunning Khaz Modan and driving the dwarves and gnomes behind the sealed gates of Ironforge and Gnomeregan. Advancing north across the Thandol Span and through the seas, orcish forces burned their way through Hillsbrad and the Hinterlands before laying siege to Capital City itself. The kingdom of Alterac betrayed the Alliance, guiding orc divisions through mountain passes. Despite devastating dragon attacks, the Alliance rallied around the newly created Knights of the Silver Hand and paladins who wielded the Holy Light against orcish warlocks and death knights. The war turned when the warlock Gul'dan deserted the Horde with his followers to pursue personal power, forcing Doomhammer to divert critical forces from the front lines. The Alliance counterattacked, breaking the siege of Lordaeron and systematically driving the Horde back south across the Thandol Span, liberating Khaz Modan along the way. In the final mountain passes of the Burning Steppes, Anduin Lothar fell in single combat against Doomhammer, but his lieutenant Turalyon rallied the troops and routed the orcs. The Alliance pursued the survivors all the way to the Black Morass, shattering the remnants and demolishing the Dark Portal.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_second-war-6e454c3f752e63e3e4dc/1-0000.mp3", duration = 130.168163, start = 0},
  },
}
P.transport["topic:sentinels"] = {
  hash = "65e5e1",
  fullHash = "65e5e1",
  text = "Sentinels. The Sentinels are the elite, predominantly female military force of the night elves, formed ten thousand years ago after the War of the Ancients. Guided by the Sisterhood of Elune and commanded by General Shandris Feathermoon, they guard kaldorei settlements and defend sacred lands from Ashenvale to Feralas. Today, they wage a bitter war against Horde deforestation while watching over their new home on Teldrassil. Before the Great Sundering, the military of the ancient Kaldorei Empire had devolved into a decadent hierarchy where rank was decided by noble lineage rather than martial skill. The devastation of the War of the Ancients proved that this aristocratic structure was utterly unfit to defend Azeroth. In the aftermath, High Priestess Tyrande Whisperwind spearheaded radical reforms across night elf society. She turned to the Sisterhood of Elune, an order that had survived intact and possessed extensive experience in tactics, combat, and healing. From its devout ranks, Tyrande forged the Sentinels: a standing martial army dedicated to selflessly protecting their emerging society without regard to noble heritage. While Tyrande Whisperwind remains the spiritual supreme commander, active military leadership belongs to her lieutenant, General Shandris Feathermoon, operating out of Feathermoon Stronghold in Feralas. The Sentinels are renowned for disciplined marksmanship, deadly moonglaives, and specialized divisions. Their forces consist of elite archers, nightsaber-riding huntresses, and scouting hippogryph riders who dominate the skies. Centuries before the Third War, they fought under Archdruid Fandral Staghelm during the brutal War of the Shifting Sands in Silithus, halting the qiraji swarm. Every night elf settlement—from Astranaar to the sprawling branches of Darnassus—relies upon Sentinel garrisons for security. During the Third War, the Sentinels mounted desperate defenses against both demonic invaders and early incursions by the Horde, suffering immense losses when Cenarius fell in Ashenvale. After surviving the Battle of Mount Hyjal and pursuing Illidan across Lordaeron, they returned to find Kalimdor irrevocably changed. Today, the Sentinels face peril on multiple fronts. On Teldrassil, garrisons contend with corrupted wildlife and enraged furbolgs. Farther south, the Silverwing Sentinels clash relentlessly with the Warsong Outriders in Warsong Gulch, resolved to drive the Horde out of Ashenvale and defend the ancient forests from further exploitation.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_sentinels-2723813b49022fc85d21/1-0000.mp3", duration = 149.603265, start = 0},
  },
}
P.transport["topic:skyborne"] = {
  hash = "3a4922",
  fullHash = "3a4922",
  text = "Skyborne. The Skyborne, or shen'dorei, are an offshoot of high elves descended from rebels who fled Eldre'Thalas after opposing Prince Tortheldrin's demonic pacts. Striking a desperate bargain with wind spirits, their ancestors escaped Azeroth to dwell atop the floating Zephras Isle within Skywall. Today, with their elemental benefactors abruptly gone, their floating sanctuary faces internal fractures and physical collapse. Following the Sundering, the Shen'dralar of Eldre'Thalas languished without the Well of Eternity. Prince Tortheldrin devised a dark salvation: summon the demon Immol'thar and siphon its power. Horrified nobles and citizens resisted, fearing another Legion invasion. In response, Tortheldrin executed a bloody purge of dozens of houses. From the surviving shadows rose a resistance spearheaded by a masked figure known only as the Shal'nan ('the Veiled One'). When a desperate rebel raid on Tortheldrin's ritual sanctum descended into catastrophic chaotic magic, the Shal'nan rallied the survivors and fled west to the port of Eldre'narr, taking to the seas pursued by the Prince's fleet. Cornered on the open ocean, the exiles forged a pact with primordial wind spirits. These beings lifted Zephras Isle straight into the skies, anchoring it safely within Skywall—the Elemental Plane of Air. Relieved of absolute rule, the Shal'nan stepped down during the consecration of the Shrine of the Four Winds, placing governance in the hands of an elected council. Over millennia in this alien realm, the night elf exiles evolved into fair, slender high elves. In recent generations, an elemental influence known as the Sky-Touched Blessing has emerged, causing a growing number of children to be born with pale blue skin.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_skyborne-071b0748816b84fd61b6/1-0000.mp3", duration = 105.247347, start = 0},
  },
}
P.transport["topic:skywall"] = {
  hash = "bf4c98",
  fullHash = "bf4c98",
  text = "Skywall. Skywall is the vast, storm-swept domain of the air elementals within the Elemental Plane. Banished here by the titans in ancient days, the creatures of wind, cloud, and lightning dwell under the reign of Al'Akir the Windlord. When the titans overthrew the Old Gods eons ago, they crafted the Elemental Plane as a secure dimensional prison to contain Azeroth's unruly elemental spirits. The lords of the elements fought fiercely amongst themselves, ultimately carving out distinct dominions. The realm of wind and storm became known as Skywall, ruled by Al'Akir the Windlord. While sealed away from the surface world, its tempests continue to swirl in eternal isolation. Banishment did not end the ancient animosity between the elemental rulers. Skywall has long waged border disputes against neighboring realms like the Firelands. One of the most infamous clashes was the Elemental Sundering, wherein Prince Thunderaan the Windseeker was ambushed and betrayed by Garr and Baron Geddon, the chief lieutenants of Ragnaros the Firelord. Ragnaros devoured the prince's essence and bound the fragments into a shattered talisman. Skywall is not composed solely of raging gales and djinn citadels. Among the cloudbanks drifts Zephras Isle, a sanctuary inhabited by the Shen'dorei. Mortals on Azeroth rarely pierce the veil into the domain of air, though reckless spellcasters and weapon-crafters across history have courted disaster attempting to siphon the living storms of the Windlord.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_skywall-02fb02cb6a16df8044a5/1-0000.mp3", duration = 89.3126531, start = 0},
  },
}
P.transport["topic:steamwheedle-cartel"] = {
  hash = "75fdc9",
  fullHash = "75fdc9",
  text = "Steamwheedle Cartel. The Steamwheedle Cartel is the largest and most influential goblin enterprise operating across modern Azeroth. Fiercely neutral, the cartel governs bustling commercial hubs like Booty Bay, Ratchet, and Gadgetzan, serving Alliance and Horde patrons alike so long as their coin is genuine. Their sprawling operations encompass cross-continental shipping, alchemy, salvaging, and cutthroat mercenary contracting. Originating from the subterranean goblin capital of Undermine, the Steamwheedle Cartel initially allied with the Old Horde during the Second War, supplying war machines, sappers, and naval engineering. After the dust settled, the cartel's leaders realized that picking sides cost more than it earned. Embracing absolute neutrality, they expanded across both continents, opening trade networks that welcome Alliance and Horde alike. Today, as open tensions simmer, Steamwheedle ports provide vital common ground where anyone with gold can purchase passage, bank resources, and hire local specialists. The cartel's influence rests on strategic ports and frontier towns. In Stranglethorn Vale, Baron Revilgaz presides over Booty Bay, a fortified harbor town carved into the cliffs alongside the Blackwater Raiders. Across the Great Sea, Chief Engineer Gazlowe directs Ratchet on the coast of the Barrens, running a deep-water ferry line directly back to Booty Bay. Deep within the deserts of Tanaris lies the boomtown of Gadgetzan, while smaller operations like Steamwheedle Port and remote outposts in Desolace, Azshara, and Stonetalon Mountains secure regional resources. Steamwheedle trade is constantly imperiled by opportunistic cutthroats. In the Southern Seas, the Bloodsail Buccaneers continually menace Booty Bay's naval lanes, while Southsea Freebooters raid the coastlines near Ratchet. On land, the cartel frequently clashes with their corporate arch-rivals, the Venture Company, competing violently for timber rights, oil fields, and shredder technology across Stonetalon and the Barrens. To maintain order and enforce trade contracts, cartel barons routinely hire passing mercenaries to settle grievances with extreme prejudice.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_steamwheedle-cartel-25521c0935aa247d178d/1-0000.mp3", duration = 127.608163, start = 0},
  },
}
P.transport["topic:stonefield-family"] = {
  hash = "a17be1",
  fullHash = "a17be1",
  text = "Stonefield family. The Stonefield family is a lineage of human farmers residing at the Stonefield Farm in western Elwynn Forest. Known for their long-standing rural roots, they tend their homestead while caught up in an ongoing rivalry with their neighboring peers, the Maclures. Despite the hostility between the two households, younger generations find themselves entangled across the family divide. The Stonefields are quintessential Elwynn agrarian stock, working the soil south of the road leading to Westfall. The homestead revolves around Gramma Mildred Stonefield, Ma Stonefield, and young Tommy Joe Stonefield. Daily life on the farm involves tending crops and managing livestock while fending off local pests and dealing with nearby kobold incursions that plague the region's mines and borders.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_stonefield-family-d98adef9f1b707b3daf0/1-0000.mp3", duration = 46.315102, start = 0},
  },
}
P.transport["topic:stormwind-guard"] = {
  hash = "812171",
  fullHash = "812171",
  text = "Stormwind Guard. The Stormwind Guard comprises the regional garrisons and sentries tasked with enforcing the kingdom's laws and defending its surrounding territories. Stretched perilously thin by political gridlock and distant military campaigns, its scattered marshals struggle to hold back gnolls, orcs, and bandits across Elwynn and Redridge. Operating as a vital branch of the Stormwind Army, the Stormwind Guard patrols the highways, crossroads, and stone watchtowers that bind the kingdom together. In outlying settlements, governance and defense fall to appointed marshals—such as Marshal McBride in Northshire Valley, Marshal Dughan in Goldshire, and Marshal Marris in Lakeshire. These officers muster recruits and maintain order, relying on trusty brown horses known for stamina to cover ground between fortified outposts like Westbrook Garrison. Following the Third War, the Guard successfully kept Elwynn Forest safe and quiet, but recent years have brought crisis. With King Varian Wrynn vanished and the kingdom's standing army tied down abroad, regional garrisons have received little aid. At Westbrook Garrison, Deputy Rainer can barely hold the western border against Riverpaw gnolls and Defias thieves, forcing local commanders to outsource crucial security tasks and bounties to visiting adventurers. While Duskwood and Westfall were abandoned, the crown kept a tenuous military presence in the Redridge Mountains. Even so, the guard's position is desperate. Overwhelmed by Shadowhide gnolls and Blackrock orcs descending from the Burning Steppes, soldiers were forced to cede Stonewatch Keep. In Lakeshire, blacksmith Verner Osgood burns through iron merely keeping guards outfitted, while exhausted sentries scan the road waiting for a 2nd Battalion that never arrives.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_stormwind-guard-01321224c2b16e257903/1-0000.mp3", duration = 104.437551, start = 0},
  },
}
P.transport["topic:tauren"] = {
  hash = "0703f2",
  fullHash = "0703f2",
  text = "Tauren. The tauren, or shu'halo in their native tongue, are a noble race of nomadic bovine humanoids native to central Kalimdor. Deeply devoted to the Earth Mother, shamanism, and the natural world, they were driven near extinction by ruthless centaur clans before forging a bond with Thrall's New Horde. Today, united under High Chieftain Cairne Bloodhoof, they have established a permanent home across the verdant plains of Mulgore and the high rises of Thunder Bluff. For countless generations, the tauren lived as seasonal nomads wandering the arid plains of the Barrens, hunting the great kodo and listening for the voice of the Earth Mother. However, their peaceful wanderings were plagued by centuries of brutal bloodshed. The ferocious centaur tribes, born from the tragic union of Zaetar and Princess Theradras, waged an unrelenting war of extermination against them. Lacking a fortified homeland and reluctant to wage endless war, the tauren tribes were pushed to the brink of annihilation, their very survival hanging by a thread. Survival came from an unexpected alliance across the sea. During the Third War, Chieftain Cairne Bloodhoof encountered Warchief Thrall and his newly arrived orcs. Recognizing a shared spirit of honor and a longing for shamanic heritage, the two leaders joined forces. With the Horde's assistance, the tauren crushed the marauding centaur and claimed the lush, sheltered grasslands of Mulgore. Upon its windswept mesas, Cairne raised the city of Thunder Bluff. Indebted by this salvation, the tauren marched alongside the Horde to Mount Hyjal to turn back the Burning Legion.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_tauren-2a36345f0dc8de9fd872/1-0000.mp3", duration = 94.2759184, start = 0},
  },
}
P.transport["topic:terenas-menethil-ii"] = {
  hash = "6c0d7c",
  fullHash = "6c0d7c",
  text = "Terenas Menethil II. King Terenas Menethil II was the venerable sovereign of Lordaeron who ruled for over five decades and forged the original Alliance of Lordaeron during the Second War. Renowned as a wise and diplomatic leader, he shielded humanity from the initial Horde invasion and sheltered the young Prince Varian Wrynn. His tragic murder by his corrupted son, Prince Arthas, directly triggered the collapse of Lordaeron to the Scourge. When refugees from Stormwind arrived in the north led by Sir Anduin Lothar, King Terenas Menethil II answered their call. Convening the monarchs of the fractured human kingdoms alongside envoys from Ironforge and Quel'Thalas, Terenas orchestrated the formation of the Alliance of Lordaeron. Rather than seizing military command for himself, he wisely nominated Lothar as supreme commander, uniting humanity's kingdoms for the first time in millennia to triumph over the Old Horde. In the wake of the Second War, Terenas insisted upon placing surviving orcs into internment camps rather than executing them, believing that peace could be preserved if their demonic fury dissipated. This humane but costly decision placed staggering taxes on Lordaeron's allies. Gilneas sealed itself behind the Greymane Wall, Stromgarde seceded over political disputes, and the high elves withdrew entirely, leaving Terenas to shoulder the burden with a fracturing coalition.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_terenas-menethil-ii-9395d56188fd74248438/1-0000.mp3", duration = 80.6922449, start = 0},
  },
}
P.transport["topic:third-war"] = {
  hash = "ed367f",
  fullHash = "ed367f",
  text = "Third War. The Third War was the apocalyptic conflict that shattered the old world order just a few years ago. Orchestrated by the Burning Legion and unleashed through the Lich King's Plague of Undeath, the war saw the fall of the Kingdom of Lordaeron and the near-total destruction of Quel'Thalas before culminating in a desperate, unified stand at Mount Hyjal. The war began subtly in northern Lordaeron, disguised as a virulent sickness carried in infected grain distributed from Andorhal. The tainted harvest did not merely slaughter its victims; it raised them as ravenous ghouls bound to the Lich King's will. Prince Arthas Menethil raced to stem the contagion alongside the Kirin Tor sorceress Jaina Proudmoore. Blinded by grief, fury, and dreadlord manipulations, Arthas purged the infected population of Stratholme before pursuing his foe to the frozen waste of Northrend. There, he took up the cursed runeblade Frostmourne, casting aside his soul. He returned south only to murder his father, King Terenas, delivering Lordaeron into the hands of the Scourge. Empowered by death, Arthas crushed the high elven realm of Quel'Thalas to resurrect the necromancer Kel'Thuzad at the Sunwell. The undead army then laid siege to Dalaran, seizing the spellbooks necessary to summon the demon lord Archimonde into Azeroth. With the commander of the Burning Legion walking mortal soil, Dalaran was leveled in an arcane display of devastation. The Scourge had served its purpose as an advance guard, and the Burning Legion turned its sights toward the eternal power resting across the Great Sea. Guided by cryptic warnings from the mysterious Prophet—later revealed as the redeemed Guardian Medivh—Warchief Thrall led the New Horde across the Great Sea, while Lady Jaina Proudmoore evacuated surviving Alliance refugees. In ancient Kalimdor, the newcomers clashed with the reclusive night elves before all three factions recognized the supreme threat looming over them. Beneath the World Tree Nordrassil atop Mount Hyjal, mortals stood together against impossible odds. Archimonde was destroyed by ancestral wisps when he reached the tree, shattering the Legion's vanguard and ending the war. Although Archimonde fell, the peace of 25 ADP is fragile and stained with loss. The Alliance of Lordaeron is gone, leaving the kingdom of Stormwind and Ironforge to anchor the southern Alliance while Lordaeron sits rotting as the Plaguelands. In Kalimdor, Thrall's Horde carved out Durotar, yet tensions with the newly allied night elves remain volatile. The Scourge endures in the northern ruins, and the freed undead—the Forsaken—now hold the catacombs of Capital City, waging a war of survival against both former masters and vengeful crusaders.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_third-war-b23f4a33c392ab26206e/1-0000.mp3", duration = 162.847347, start = 0},
  },
}
P.transport["topic:titan"] = {
  hash = "06a5fd",
  fullHash = "06a5fd",
  text = "Titan. The titans are a primordial race of colossal, godlike beings who wander the cosmos bringing order and shaping worlds. In ancient antiquity, they came to Azeroth to vanquish the chaotic Old Gods, establish massive terrestrial facilities, and foster life before departing into the Great Dark Beyond. The titans are cosmic giants forged from primordial matter and arcane magic, embodying the forces of order and creation. In their journeys across the Great Dark Beyond, they sought out slumbering worlds to cultivate, raising up continents, calming chaotic elemental forces, and designing life. To enforce balance, they established powerful constructs made of stone, iron, and sea to watch over their works. Long ago, the Pantheon of titans discovered Azeroth in the grip of the chaotic elemental lords and the horrific Old Gods. The titans waged war against these parasitic horrors, banishing the elementals to pocket planes and sealing the monstrous Old Gods deep beneath the crust of the earth. Upon securing the world, they carved great biomes, established vault complexes like Uldaman, and entrusted five great dragons—the Dragon Aspects—with stewardship of the land, magic, time, and life itself before journeying back among the stars. Not all titans remained aligned with the Pantheon's vision of perfect order. Sargeras, once the greatest warrior and defender of the titans, grew despondent and terrified by the deep cosmic darkness and demonic malevolence he was charged with combating. Rejecting the work of his kin, Sargeras turned to nihilism, founding the demonic Burning Legion to extinguish all creation rather than allow it to be corrupted.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_titan-499f3fe33bbef0529c81/1-0000.mp3", duration = 98.9257143, start = 0},
  },
}
P.transport["topic:trogg"] = {
  hash = "4eee46",
  fullHash = "4eee46",
  text = "Trogg. Troggs are brutish, subterranean humanoids descended from the earliest, failed titan-forged experiments sealed deep within the earth. Having recently clawed their way to the surface after dwarven excavations disturbed their ancient vaults, these relentless diggers have overrun dwarven quarries and driven the gnomes out of their beloved capital of Gnomeregan. Long before mortal races recorded history, the titan-forged keepers sought to fashion servants from stone. Their initial design went awry, yielding stone-skinned brutes of low intelligence and unbridled savagery. Distressed by their botched creations, the keepers refined the matrix into the earthen race, who would eventually become the ancestors of the dwarves. Unwilling to annihilate the imperfect troggs, the giantess Ironaya sealed them deep underground within the vault of Uldaman, intending for them to remain trapped in eternal stasis. For countless millennia, the troggs lay dormant until the Explorers' League of Ironforge breached the ancient subterranean complexes of Khaz Modan. Waking in an unfamiliar era, swarms of furious troggs poured from the depths, pursuing their distant dwarven relatives with ancestral fury. Finding the surface bright and unwelcoming, they carved sprawling tunnel networks beneath Dun Morogh, Loch Modan, and the Badlands, quickly ambushing quarries, archaeological dig sites, and trade outposts.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_trogg-227d60d6d7f11ad231f7/1-0000.mp3", duration = 84.7934694, start = 0},
  },
}
P.transport["topic:venture-company"] = {
  hash = "015725",
  fullHash = "015725",
  text = "Venture Company. The Venture Company is a notoriously ruthless goblin cartel focused on aggressive resource extraction, heavy industrial machinery, and logging. Unaligned with the major goblin ports like Booty Bay or Ratchet, the cartel strip-mines and clear-cuts territories across Kalimdor and the Eastern Kingdoms without regard for local populations or the natural world. Led overall by Mogul Razdunk from afar, the Venture Company operates by a simple corporate philosophy: if it can be chopped down, drilled into, or blasted out of a mountain, they will exploit it. The cartel deploys some of the most advanced heavy machinery on Azeroth, including massive lumber-harvesting shredders, drilling rigs, and industrial refineries. Unlike traditional merchant houses that focus on shipping or retail, the Venture Company specializes in seizing raw resources by force, ignoring treaties, borders, and local sovereign rights.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_venture-company-56d93767eb375f488433/1-0000.mp3", duration = 55.1444898, start = 0},
  },
}
P.transport["topic:westfall-brigade"] = {
  hash = "59d866",
  fullHash = "59d866",
  text = "People's Militia. The People's Militia is a grassroots defense force founded by Gryan Stoutmantle to protect Westfall's residents from the Defias Brotherhood. Operating out of Sentinel Hill, these volunteer defenders stand alone since Stormwind withdrew its troops from Westfall. They rely on local farmers and visiting adventurers to hold the line against rampant banditry. Westfall was once the breadbasket of the Kingdom of Stormwind, but Stormwind withdrew its troops and left the people defenseless. In the vacuum, the masked bandits of the Defias Brotherhood swept across the plains, seizing family homesteads, commandeering iron mines, and extorting local farmers. Facing lawlessness and seeing no sign of royal reinforcements, veteran warrior Gryan Stoutmantle rallied local citizens and retired soldiers to form the People's Militia. Based at Sentinel Tower atop Sentinel Hill, the Militia maintains a tenuous perimeter across the region's main thoroughfares. Lacking professional military gear and sustained supplies, their protectors patrol dusty roads while Stoutmantle directs volunteers to thin the swelling ranks of Defias highwaymen, thieves, and pillagers. When neighboring regions like Redridge plead for mutual aid, the Militia is forced to decline, as sparing even a handful of men would spell the total ruin of Westfall.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_westfall-brigade-d20a5bf10691231806e2/1-0000.mp3", duration = 77.1395918, start = 0},
  },
}
P.transport["topic:worgen"] = {
  hash = "43d6a3",
  fullHash = "43d6a3",
  text = "Worgen. Worgen are fierce, lupine humanoids cursed with uncontrollable primal rage, moving upright yet hunting with bestial swiftness. Once thought to be mere nightmares conjured from other planes, these savage pack-hunters now terrorize Silverpine Forest, Ashenvale, and Duskwood. Long before their recent emergence in Lordaeron and Kalimdor, wolf-men were whispered of in folktales and cautionary fables. Their true origins remain a mystery: scholars who have studied the beasts believe they were drawn into Azeroth from another realm, and both Archmage Arugal and the night elves' Scythe of Elune have proven able to call them forth. During the Third War, as the Scourge hordes overran Lordaeron and slain Kirin Tor wizards rose again as undead, Archmage Arugal sought a weapon to bolster Dalaran's dwindling ranks. Drawing from the forbidden research of the Dalaran wizard Ur, Arugal pierced the veil and summoned the beasts into Silverpine Forest. The summoned worgen devastated the undead invaders with savage abandon, but the archmage could not leash their fury. The beasts turned on the wizards themselves, spreading their curse through fang and claw. Driven mad by guilt and fascination, Arugal adopted the monsters as his children, seizing Baron Silverlaine's ancestral seat—now rechristened Shadowfang Keep—and cursing nearby villagers into monstrous nocturnal servitude.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_worgen-1c61b21d5befe526f1bb/1-0000.mp3", duration = 83.6702041, start = 0},
  },
}
P.transport["zone:arathi"] = {
  hash = "631e20",
  fullHash = "631e20",
  text = "Arathi Highlands. The Arathi Highlands are a rugged plateau in southeastern Lordaeron, renowned as the ancient birthplace of the Empire of Arathor. Today, the kingdom of Stromgarde lies in ruins, leaving the craggy realm engulfed in multi-front warfare between the remnants of Stromgarde, the Horde, criminal Syndicate nobles, and invading ogres. Millennia ago, King Thoradin united the fractured human tribes under the banner of the Arathi, constructing the majestic capital of Strom across these dry, defensible plains. It was here that humanity forged its legendary compact with the high elves during the Troll Wars, mastering the arcane arts to push back the Amani. Over time, noble bloodlines migrated north into Lordaeron and south toward Stormwind, but the imperial guard stayed behind to form the martial realm of Stromgarde. For ages, Stromgarde stood as a bastion of stalwart warriors dedicated to keeping the forest trolls at bay. Stromgarde proved vital in defending the Alliance during the Second War under King Thoras Trollbane, but the Third War and its aftermath shattered the nation. Although the kingdom spared itself the worst ravages of the Scourge plague, the mysterious death of King Thoras threw the realm into turmoil. Boulderfist ogres swept in from the hills, while the traitorous Alteraci nobles of the Syndicate seized sprawling districts of Stromgarde Keep. Today, Prince Galen Trollbane and his loyalist survivors cling to a tiny sliver of the city and their redoubt at Refuge Pointe, waging a bitter guerrilla war against hopeless odds.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_arathi-a485d84ee9371ac70b9e/1-0000.mp3", duration = 90.357551, start = 0},
  },
}
P.transport["zone:ashenvale"] = {
  hash = "6ca043",
  fullHash = "6ca043",
  text = "Ashenvale. Ashenvale is the ancient, rain-drenched ancestral forest of the night elves, held sacred under the protection of the Sentinels and the demigod Cenarius. Bordering the Barrens to the south and Darkshore to the north, it has erupted into a bitter war zone as the Horde harvests timber to build its young nation. Ancient trees and tranquil moonwells share canopy with demonic holdouts, hostile beastmen, and clash points along the contested frontier. Stretching beneath Mount Hyjal, Ashenvale has stood for millennia under the stewardship of the kaldorei and the children of Cenarius. Immense trees knit together into a dense canopy that turns daily rain into a gentle mist and casts the forest floor in eternal twilight. Ancient ruins of elven civilization poke through the moss, guarded by walking ancients and dryads. For thousands of years, the night elves built no true cities here, preferring to hunt lightly and preserve the wild domain in pristine balance. The peace shattered during the Third War when Grommash Hellscream and the Warsong clan penetrated the forest for lumber, slaying Cenarius after falling to demonic bloodlust. Today in 25 ADP, the struggle has become a full-scale territorial war. From Splintertree Post and the southern Mor'shan Rampart, the Warsong Outriders drive axes and shredders into the eastern woods to supply Orgrimmar. The Silverwing Sentinels, based in the sanctuary town of Astranaar, have sworn to expel every last orcish logger from the sacred grove. The lumber war is far from Ashenvale's only peril. The Burning Legion left scarred blights at Felfire Hill and Demon Fall Canyon, where Mannoroth met his end. Cruel satyrs operate out of ruins like Satyrnaar and Xavian, corrupting waterways and wildlife. Furbolg tribes, once friends of the elves, have largely succumbed to dark madness. Meanwhile, mysterious worgen stalk the northern shrine near Felwood, and cursed dragonkin prowl Bough Shadow, guarding a portal into the troubled Emerald Dream.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_ashenvale-e7c8e7de68976a5f03a2/1-0000.mp3", duration = 125.126531, start = 0},
  },
}
P.transport["zone:azshara"] = {
  hash = "083fb6",
  fullHash = "083fb6",
  text = "Azshara. Azshara is a rugged, windswept coastline in northeastern Kalimdor cloaked in vibrant, perpetual autumn foliage. Once part of the glorious night elven capital before the Great Sundering shattered it into the sea, it remains a dangerous wilderness littered with ancient ruins, brooding naga, and isolated practitioners of magic. Both the Horde and the Alliance maintain precarious outposts along its borders, wary of the restless ghosts and ocean horrors lurking within. Ten thousand years ago, this coast was the beating heart of the kaldorei civilization, surrounding the royal capital of Zin-Azshari. When Queen Azshara and her Highborne court drew the Burning Legion into Azeroth, the resulting War of the Ancients culminated in the catastrophic collapse of the Well of Eternity. The sea thundered inward, swallowing most of the magnificent city and leaving behind fractured cliffs, treacherous coral reefs, and waterlogged spires. The survivors renamed the ruined landscape after their fallen monarch, branding it as a cursed monument to pride and catastrophic betrayal. Azshara is famous for its stunning crimson, orange, and gold canopy, giving the impression of an eternal autumn unbroken by changing seasons. Beneath this tranquil canopy, however, lies an inhospitable expanse. Corrupted satyrs practice dark rituals in forested hollows, lingering Highborne apparitions haunt drowned foundations, and Spitelash naga prowl the shallow reefs of the Coral Sea. Ferocious beasts, giant hydras, and mountain giants roam unchecked across the highlands and ivory beaches. Because of its isolation and harsh terrain, Azshara draws recluse figures pursuing forgotten crafts or watching over dangerous powers. The enigmatic Archmage Xylem inhabits a secluded tower perched high above the cliffs, testing promising spellcasters and cunning rogues alike. Farther along the coast, the demon hunter Loramus Thalipedes watches the waves from a barren isle, while the immense sea giant Lord Arkkoroc demands blood sacrifices from his temple overlooking the churning waters.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_azshara-018d75399fd9d323b073/1-0000.mp3", duration = 125.466122, start = 0},
  },
}
P.transport["zone:badlands"] = {
  hash = "cb90ef",
  fullHash = "cb90ef",
  text = "Badlands. The Badlands is an arid, sun-baked expanse of cracked earth, dust storms, and rocky canyons nestled between Loch Modan and Searing Gorge. Despite being deep within dwarven Khaz Modan, it serves as a volatile frontier dominated by Dark Iron dwarves, troggs, Dustbelcher ogres, and nesting black dragonkin. It also houses the titan ruins of Uldaman and the Horde stronghold of Kargath, making it a critical strategic waypoint. Wedged south of Loch Modan's verdant hills, the Badlands quickly turns into a sweltering basin of barren flats and rugged ravines. Surviving here requires contending with merciless coyotes, cougars, vultures, and fierce sandstorms that obscure the horizon. Scattered across the plateaus are the crude encampments of the Dustbelcher ogres, while the brooding Dark Iron clan fortifies Angor Fortress and clashes with anyone trespassing on their territory. In the northern bluffs lies Uldaman, an ancient subterranean complex carved out by the titan-forged earthen. Recently uncovered by Ironforge prospectors, the excavation unearthed monumental secrets regarding the ancient ancestry of the dwarven race. However, digging into the subterranean vaults awoke hordes of vicious Stonevault troggs and animated earthen guardians, slaughtering archaeological teams and turning the digsites outside into bloody skirmish grounds. The Badlands is one of the Horde's most precarious footholds in the southern Eastern Kingdoms. Established in the northwest, the fortress of Kargath gives Warchief Thrall's forces a base of operations to keep watch on the rogue Dark Horde in nearby Blackrock Mountain. Meanwhile, to the far east lies Lethlor Ravine, a treacherous chasm where black whelps and dangerous black dragonkin guard their brooding grounds under the shadow of the mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_badlands-20cccbb11d22ea451d0a/1-0000.mp3", duration = 111.725714, start = 0},
  },
}
P.transport["zone:barrens"] = {
  hash = "44979c",
  fullHash = "44979c",
  text = "The Barrens. The Barrens is an expansive, sun-baked savanna that serves as the beating geographical and logistical heart of the Horde in central Kalimdor. Once a verdant forest prior to the Great Sundering, it is now an arid plain of red dust, hardy scrub, and wandering wildlife. Centered around the strategic hub of the Crossroads, the land remains locked in constant struggle against quilboar tribes, centaur raiders, and creeping corruption. For countless generations, nomadic tauren hunted kodo and zhevra across these plains while waging a defensive, cyclical war against marauding Kolkar centaur. When Thrall led the orcs to Kalimdor during the Third War, he aided Cairne Bloodhoof in repelling the centaur and traversing the savanna into Mulgore. Today, the Barrens connects Durotar, Mulgore, and Ashenvale. Outposts like the Crossroads and Camp Taurajo secure trade along the Gold Road, while orcish homesteads brave the arid climate to forge a lasting home. Despite Horde dominance, control over the savanna is hotly contested. Porcupine-like Razormane quilboar aggressively raid farms and supply lines from their thorn-choked redoubts, backed by the looming dens of Razorfen Kraul to the south. Along the eastern coast, Theramore forces garrison Northwatch Hold, while dwarven prospectors dig into the titan complex of Bael Modan. Meanwhile, the goblins of Ratchet enforce an uneasy mercantile neutrality, welcoming any traveler with coin.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_barrens-7dbe99ccd1fe6471562b/1-0000.mp3", duration = 90.2530612, start = 0},
  },
}
P.transport["zone:blastedlands"] = {
  hash = "977846",
  fullHash = "977846",
  text = "Blasted Lands. The Blasted Lands are a desolate expanse of red clay and barren rock at the southeastern tip of the Eastern Kingdoms, ruined by the chaotic energies of the Dark Portal. Once part of the verdant Black Morass, the shattered earth now harbors demonic remnants of the Burning Legion, brutal Dreadmaul ogres, and hardy desert beasts. Nethergarde Keep stands vigil over the desolate wasteland, guarding Azeroth from whatever horrors may spill out of the dormant gateway. Before the First War, this region was a continuation of the dense fenlands known as the Black Morass. That lush swamp was utterly eradicated when the warlock Gul'dan and the possessed Medivh tore open the Dark Portal to unleash the orcish Horde. Chaotic fel energies bled through the dimensional breach, stripping all moisture and baking the earth into cracked red clay. When the Dark Portal was later destroyed at the end of the Second War, catastrophic shockwaves scorched the terrain further, transmuting the native stone into its unearthly crimson hue. Perched upon the northern bluffs, Nethergarde Keep watches over the only road entering the valley. Commissioned by Archmage Khadgar and the Kirin Tor following the Second War, this stone bastion is manned by grim mages and stalwart soldiers sworn to prevent any renewed demonic or orcish incursions. It is an uninviting and strictly disciplined posting; infractions among the garrison are punished with banishment to the Stockade in Stormwind. The defenders face relentless pressure from the Dreadmaul ogres who stayed behind after Draenor's fall, raiding the roads and attacking the fortress gates under fell guidance. In the southwestern reaches lies the Tainted Scar, a cratered canyon teeming with the deadliest demonic force on the continent. Stranded after the defeat at Mount Hyjal, the doomguard commander Lord Kazzak gathers wandering demons, doomguard, and felhounds to his banner. High above the red barrens, his dreadlord lieutenant, Razelikh the Defiler, orchestrates mortal servitude among the Shadowsworn cultists at the Altar of Storms and commands the local Dreadmaul ogres. Despite the land's desolation, scholars and wanderers brave its horrors for unique discoveries. Just inside the northern pass, Bloodmage Drazial and Bloodmage Lynnore conduct eccentric alchemical experiments, extracting organs from local scorpids, basilisks, and boars to brew extraordinarily potent physical enhancers. Farther into the wastes, a lone draenei hermit named Kum'isha seeks scattered draenethyst fragments, rewarding travelers who recover these alien remnants left behind by Draenor's shattered past.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_blastedlands-8d90140862455d92eb69/1-0000.mp3", duration = 154.226939, start = 0},
  },
}
P.transport["zone:burningsteppes"] = {
  hash = "f70df7",
  fullHash = "f70df7",
  text = "Burning Steppes. The Burning Steppes are a scorched, volcanic wasteland flanking the southern base of Blackrock Mountain. Formed by the catastrophic summoning of Ragnaros centuries ago, this treacherous territory holds the primary overland passage between Stormwind and Khaz Modan. Today, it crawls with rogue Blackrock orcs, Firegut ogres, Dark Iron dwarves, and broodlings of the black dragonflight. Long ago, these foothills were simply the northern reaches of the Redridge Mountains. During the War of the Three Hammers, the exiled Dark Iron clan established their kingdom here, raising their capital city of Thaurissan. Facing total defeat at the hands of the Bronzebeard and Wildhammer clans, the desperate Sorcerer-Thane Thaurissan attempted to conjure elemental forces. Instead, he shattered the earth and summoned Ragnaros the Firelord into Azeroth. The violent explosion pulverized the surrounding mountains, tore open rivers of lava, and birthed the colossal volcano known as Blackrock Mountain, leaving the steppes forever charred and barren. During the Second War, the Old Horde claimed Blackrock Spire as its foremost seat of power. At the climax of the conflict, the Grand Alliance of Lordaeron pushed deep into the Burning Steppes to lay siege to the mountain. It was at the foot of Blackrock Mountain that Warchief Orgrim Doomhammer clashed with Lord Anduin Lothar, striking down the human champion. Rather than breaking the Alliance's resolve, Lothar's death galvanized the Allied armies to rout the orcs, sealing the victory of the Second War and leaving behind an enduring valley of ash and rusted steel. Though Thrall established a New Horde in distant Kalimdor, the Blackrock clan remaining in the steppes maintains the bloodthirsty cruelty of the Old Horde. Operating from Blackrock Stronghold, these orcs openly ally with the black dragonflight and local Firegut ogres rather than honor any truce. Meanwhile, Dark Iron dwarves and elemental servitors lurk among the fiery ruins, all while black drakes and wyrmkin prey upon unwary travelers attempting to use the thoroughfare to cross between Stormwind and the northern kingdoms.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_burningsteppes-c4952a87865f8a0407fb/1-0000.mp3", duration = 128.783673, start = 0},
  },
}
P.transport["zone:deadmines"] = {
  hash = "c630fb",
  fullHash = "c630fb",
  text = "The Deadmines. Deep beneath the dusty farm town of Moonbrook lies the Deadmines, an enormous subterranean complex that once supplied a third of Stormwind's gold reserves. Abandoned during the First War and long considered haunted, these labyrinthine tunnels have secretly been overtaken by the Defias Brotherhood as their ultimate staging ground. Here, Edwin VanCleef and his conscripted goblin engineers labor away from the eyes of the realm to build an engine of vengeance against the kingdom. Before the First War, the Deadmines were celebrated as the greatest gold-producing center in human lands, financing the prosperity of Stormwind. When the Orcish Horde swept through the kingdom and razed the capital, the mines were hastily abandoned to the dark. During those turbulent years, legendary figures walked these depths: Sir Anduin Lothar was imprisoned by subterranean ogres for twenty months while recovering the sacred Tome of Divinity, and Warchief Blackhand's rebellious daughter Griselda fled into the lower passages alongside the ogre Turok before both met their ends. Believed to be cursed and populated only by shambling undead and lurking subterranean vermin, the depths lay untouched for decades. When the Stonemasons' Guild was cast out of Stormwind without payment for rebuilding the city, Edwin VanCleef reorganized the disenfranchised artisans into the Defias Brotherhood. Seeking a secure headquarters safe from Gryan Stoutmantle's People's Militia, the thieves established their central redoubt within the abandoned tunnels. They drove out the legitimate Miners' League—leaving Foreman Thistlenettle's doomed workers to perish and rise as undead ghouls—and converted the shafts into an industrial war camp. Guarded by lumbering ogres, seasoned brigands, and mechanical constructs, the lower mines echo once again with picks, fires, and illicit industry.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_deadmines-c6f7b040c770ff33c1ce/1-0000.mp3", duration = 109.113469, start = 0},
  },
}
P.transport["zone:desolace"] = {
  hash = "524830",
  fullHash = "524830",
  text = "Desolace. Desolace is a bleak, windswept desert on Kalimdor's western coast, defined by cracked gray earth, constant stormy skies, and the bones of fallen beasts. It is the ancestral cradle of the vicious centaur race and a contested wasteland scarred by ancient Highborne ruins, encroaching demonic cults, and bitter tribal warfare. Both the Horde and Alliance maintain precarious footholds amidst the dust, each seeking to carve out influence while warding off spreading corruption. Desolace was not always a barren expanse of ash and yellowed pools. Legend holds that the land withered when the earth elemental Princess Theradras drained the surrounding life force to regenerate her form. Zaetar, son of Cenarius, came to her, but rather than subduing her, he took the princess as his mate. From their unnatural union sprang the first centaur. In shame and bloodthirsty wrath, the newborn race murdered their father and overran the plains, leaving behind the scarred wasteland known today. The interior of Desolace echoes with the thunder of thousands of hooves as four splintered centaur tribes wage endless war against all interlopers and each other. The Kolkar roam the eastern cliffs, the Magram hold crude yurts around brackish sinkholes, the Gelkis dwell behind rope bridges in deep southern ravines, and the fanatical Maraudine defend the approach to Maraudon itself. Travelers venturing across the wastes frequently find themselves drawn into this ancient blood feud, forced to slaughter one tribe to gain safe passage and tenuous parley with another. Beyond the warring centaur, darker perils fester along the borders. The Burning Blade cult operates freely out of Thunder Axe Fortress and Shadowbreak Ravine, summoning demons and satyrs that threaten to drown the region in fel fire. Along the stormy shoreline, naga creep onto the beaches of Ethel Rethor, while Darkspear trolls spear fish from the stilted platforms of Shadowprey Village. Tucked high in the northern crags, the Alliance watches from Nijel's Point, suspicious of the Horde's expansion and ever wary of the demonic taint spreading from Mannoroc Coven.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_desolace-907641b3468a75a93227/1-0000.mp3", duration = 126.955102, start = 0},
  },
}
P.transport["zone:dunmorogh"] = {
  hash = "b44509",
  fullHash = "b44509",
  text = "Dun Morogh. Dun Morogh is a snow-swept mountain highland situated at the heart of Khaz Modan. It serves as the ancestral starting ground and shared homeland for the dwarves of Ironforge and the displaced gnomes of Gnomeregan. Though guarded by towering peaks and fortified passes, the snowy realm faces rising internal threats from troggs, Frostmane trolls, and irradiated leper gnomes. Dun Morogh occupies the highest peaks in the Eastern Kingdoms, an alpine expanse ringed by jagged summits that shield it from Searing Gorge to the south and the Wetlands to the north. These snowy mountains feed the rivers flowing across Khaz Modan and provide near-limitless veins of copper and iron. Access is heavily restricted to mountain tunnels like North Gate Pass and South Gate Pass, watched closely by dwarven Mountaineers. At the heart of the region sits Ironforge, an ancient subterranean wonder and the capital of King Magni Bronzebeard's realm, linked straight to Stormwind by the marvel of the Deeprun Tram. Centuries ago, the dwarves drove the native Frostmane ice trolls into the crags, carving out room for themselves alongside their brilliant gnome allies. The two races flourished in neighboring mountain halls until the recent catastrophe in Gnomeregan during the Third War. A horrific trogg invasion and a catastrophic radioactive venting ruined the technological wonder, turning its defenders into mindless leper gnomes and driving High Tinker Gelbin Mekkatorque and his surviving folk into exile. Now, the gnomes dwell as guests inside Ironforge, while leper gnomes and surviving troggs spill out into Chill Breeze Valley. Life in the drifts is far from quiet. The Frostmane tribe has grown emboldened, establishing heavily armed encampments from Shimmer Ridge down to Coldridge Valley. Meanwhile, primitive troggs have clawed their way out of ancient subterranean fissures into Gol'Bolar Quarry, threatening the region's mining operations. Between prowling wendigos, wild boars, infiltrating Dark Iron dwarven agents, and toxic fallout spreading from the ruins of Gnomeregan, the dwarven Mountaineers are stretched thin maintaining order from Kharanos to the border gates.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_dunmorogh-da96f8ce539a4c5c66ca/1-0000.mp3", duration = 131.004082, start = 0},
  },
}
P.transport["zone:durotar"] = {
  hash = "ae1b6e",
  fullHash = "ae1b6e",
  text = "Durotar. Durotar is the arid, red-rock homeland founded by Warchief Thrall following the Third War, named in honor of his father, Durotan. Bounded by the Southfury River and the Great Sea, it serves as the heartland of the New Horde and the proving ground for young orcs and Darkspear trolls. Within its harsh canyons lie fortified settlements like Razor Hill, the sprawling warrior city of Orgrimmar, and entrenched hostile holdouts ranging from quilboar tribes to stranded Alliance troops. When Thrall led his people across the Great Sea to Kalimdor, he deliberately sought an untamed frontier where the orcs could carve out an honest existence through labor and grit rather than conquest. Durotar's cracked red soil, baked gullies, and towering red-rock spires remind the orcs deeply of Draenor before its destruction. While the climate is unforgiving, offering little arable land and sparse water, the Horde embraced the landscape's natural defense and austere majesty. Bordered to the west across the Southfury River by the open Barrens and to the north by the ruined wilderness of Azshara, Durotar stands as living proof that the orcs have forged their own destiny. Though Durotar is firmly under Horde dominion, securing it remains an active war. Razormane quilboar, pushed out during the nation's founding, relentlessly raid settlements and farms from the western crags. Farther south, remnants of Grand Admiral Daelin Proudmoore's Kul Tiras fleet still hold the crumbling garrison of Tiragarde Keep under Lieutenant Benedict, refusing to surrender. Worse still, demonic remnants of the Burning Blade coven lurk within hidden ravines and deep sea caves, subtly seeking to re-corrupt young orcs with promises of fel power. Along the southern coast lies Sen'jin Village, the staging ground for the exiled Darkspear trolls. Led by Master Gadrin, the Darkspear were forced from their home on the nearby Echo Isles when the witch doctor Zalazane lost his mind and used dark voodoo to enslave his kin. Unable to reclaim their islands alone, the Darkspear rely on newly trained orc and troll warriors stepping forth from the Valley of Trials to break Zalazane's hold and secure the coast.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_durotar-61c1d0dbae151c179e3b/1-0000.mp3", duration = 128.470204, start = 0},
  },
}
P.transport["zone:dustwallow"] = {
  hash = "e88812",
  fullHash = "e88812",
  text = "Dustwallow Marsh. Dustwallow Marsh is a vast, sweltering swampland in central Kalimdor, trapped between the arid plains of the Barrens and the Great Sea. Fed by perpetual subterranean springs, its treacherous fens harbor dangerous predators, covert faction skirmishes, and the lurking presence of the black dragonflight. It serves as home to the Alliance fortress-island of Theramore in the east and the Horde-allied Stonemaul ogres of Brackenwall Village to the northwest. Before the Great Sundering, Dustwallow was a high, grassy plain teeming with herd animals. The cataclysm shattered the valley, causing the water table to rise and drown the earth in endless stagnant pools, mossy shallows, and choking mud. Underground springs ensure the marsh remains perpetually humid and submerged, blanketed in thick fog and infested with crocolisks, raptors, and spiders. Jagged shallows and wandering bogs make travel perilous for any adventurer stepping off the crumbling causeways. Dustwallow was largely wild until the aftermath of the Third War, when Lady Jaina Proudmoore led human refugees across the sea to establish the citadel of Theramore Isle on its eastern coast. Soon after, Kul Tiran forces under Grand Admiral Daelin Proudmoore waged war against Thrall's fledgling Horde, culminating in bloody battles across the wetlands and the Admiral's defeat. Today, an official armistice exists between Theramore and Orgrimmar, yet tension smolders beneath the surface. Theramore struggles with desertions and sabotage, while spies wage quiet, deadly conflicts across the fens.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_dustwallow-39503bcc23ecb5cd2866/1-0000.mp3", duration = 94.484898, start = 0},
  },
}
P.transport["zone:easternplaguelands"] = {
  hash = "0dc9e9",
  fullHash = "0dc9e9",
  text = "Eastern Plaguelands. The Eastern Plaguelands represent the devastated heart of the fallen Kingdom of Lordaeron, suffocated under Scourge blight, toxic mists, and corrupted fungal growths. Stratholme looms in the north as the undead power base in the region, while the zealous Scarlet Crusade entrenches in the east. Amid the nightmare, Light's Hope Chapel stands as a resolute, neutral sanctuary for anyone brave enough to fight back. Once known as the fertile Eastweald, this region was the agricultural spine of northern Lordaeron, anchored by the great metropolis of Stratholme and prosperous towns like Darrowshire and Corin's Crossing. During the Third War, Prince Arthas purged Stratholme after discovering its grain supply had been laced with the Plague of Undeath. Following the kingdom's collapse, the Scourge's dark magic ran unchecked. The soil turned brown and rotten, ordinary flora warped into colossal mushrooms, and an eerie orange mist settled across the valleys. Stratholme serves as the southern seat of Scourge authority in Lordaeron, commanded by Baron Rivendare under the direction of the lich Kel'Thuzad. Defying the undead from the southeast is the fanatical Scarlet Crusade, which has fortified the town of Tyr's Hand and assaults Stratholme's scarlet bastions. Their dogmatic hatred extends beyond the dead to any living traveler who crosses their borders. To the north, the Mossflayer forest trolls of Zul'Mashar wage their own isolated, desperate campaigns, caught in the crossfire of the greater conflict. Survival in the Eastern Plaguelands requires careful footing. The neutral Argent Dawn operates out of Light's Hope Chapel in the far east, offering a safe haven, essential supplies, and flight routes to both Alliance and Horde champions. Beyond the chapel, the ruined watchtowers of Crown Guard, Eastwall, Northpass, and Plaguewood stand as silent reminders of Lordaeron's lost defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_easternplaguelands-4a01024ef95bd44ffc4a/1-0000.mp3", duration = 109.505306, start = 0},
  },
}
P.transport["zone:felwood"] = {
  hash = "146059",
  fullHash = "146059",
  text = "Felwood. Felwood is a blighted forest nestled between Ashenvale and Mount Hyjal, deeply poisoned by demonic magic during the Third War. Once a lush paradise of meadows and groves tended by the night elves, it now crawls with demonic satyrs, slavering beasts, and twisted ancients. Cenarion Circle druids, alongside outposts of the Alliance and Horde, desperately work to cleanse the land and purge the Shadow Council from its depths. Before the Third War, this valley was a peaceful haven of singing birds, clear streams, and tranquil groves guarded by ancient protectors. That ended when the dreadlord Tichondrius and the Burning Legion deployed the Skull of Gul'dan to poison northern Kalimdor ahead of their assault on Mount Hyjal. The skull's vile sorceries twisted the forest floor into a blackened mire. Though Illidan Stormrage eventually slew Tichondrius and consumed the artifact's essence, the land remained steeped in fel corruption. Mighty treants and ancients rotted from within, rivers turned to boiling bile, and the forest's beasts were driven into cannibalistic madness. Healing Felwood has proven agonizingly slow. At the Emerald Sanctuary along the southern border, the Cenarion Circle wages an uphill battle against the blighted corruption. Druids equip wanderers with Cenarion beacons and cleansing salves, laboring to heal poisoned plants like songflowers and night dragon bulbs. Both factions maintain footholds in the tainted wilds—the night elves at Talonbranch Glade in the north and the Horde at Bloodvenom Post. These outposts serve as fragile bulwarks amid a deadly wilderness where nature has turned against all mortal flesh.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_felwood-865956b6902455988ac1/1-0000.mp3", duration = 97.6718367, start = 0},
  },
}
P.transport["zone:feralas"] = {
  hash = "aca08d",
  fullHash = "aca08d",
  text = "Feralas. Feralas is a vast, mist-shrouded rainforest nestled between Desolace, Thousand Needles, and the Veiled Sea. Sheltered by soaring mountain walls, it preserves an ancient ecosystem dotted with overgrown Kaldorei ruins and primordial beasts. Today, the wilderness is contested territory, caught between ancient Highborne remnants, invasive Gordunni ogres, and rival outposts established by the Alliance and the Horde. While neighboring Desolace and Thousand Needles have dried into barren badlands and desiccated canyons, Feralas remains intensely verdant. Mountain ranges seal off the canopy, sustaining a warm microclimate of deep mists, ancient trees, and towering waterfalls. Before the Great Sundering, much of Kalimdor looked like this. Over millennia, the deep jungle swallowed the monuments of the Kaldorei civilization that once ruled here, hiding forgotten temples and pavilions beneath strangling moss and thick fern brush. Dominating central Feralas is the ruined metropolis of Eldre'Thalas, now called Dire Maul. Built at the peak of the Kaldorei empire, its vast stone courtyards have fallen into ruin, desecrated by the savage Gordunni ogre clan. These ogres spread across the valley, pillaging sacred sites, defiling pristine groves, and driving indigenous wildlife into territorial frenzy. Deep within Dire Maul's sealed chambers, whispers persist of Highborne remnants and trapped powers dating back ten thousand years. Both the Alliance and the Horde have mounted major expeditions into the jungle, though traversing it remains dangerous. From Feathermoon Stronghold on Sardor Isle, General Shandris Feathermoon directs Sentinels against both ogre expansion and encroaching naga. To the east lies Camp Mojache, a central Horde garrison struggling against aggressive Woodpaw gnolls, hostile Grimtotem tauren, and the relentless ogre clans. Neither faction commands true control over the untamable interior.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_feralas-dac13ca98194c1fd2591/1-0000.mp3", duration = 120.476735, start = 0},
  },
}
P.transport["zone:hallofthanes"] = {
  hash = "8044c9",
  fullHash = "8044c9",
  text = "Hall of Thanes. Deep beneath the bustling city of Ironforge lies the Hall of Thanes, an ancient subterranean complex steeped in dwarven history. Intended for early Alliance adventurers, this secluded dungeon holds relics of the mountain kingdom's past that have fallen into peril. Gaining entry requires unearthing forgotten routes through the mountain itself. While Ironforge hums with the ringing of hammers in the Great Forge, forgotten halls delve far deeper beneath the stone. The Hall of Thanes represents one of these venerable subterranean reaches. Long tied to ancestral dwarven bloodlines and relics of stonecraft, it now requires intrepid Alliance champions to venture into its shadowed vaults to secure the depths. Accessing the Hall of Thanes is no casual feat. The corridors leading to these ancient vaults have been sealed away or hidden from everyday travelers in Ironforge. Adventurers must decipher forgotten charting, beginning with recovering an Underground Map, before they can navigate the deeper tunnels and breach the threshold of the dungeon.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_hallofthanes-2ecc8483d5410ec35f9a/1-0000.mp3", duration = 59.0628571, start = 0},
  },
}
P.transport["zone:hillsbrad"] = {
  hash = "3080e7",
  fullHash = "3080e7",
  text = "Hillsbrad Foothills. Hillsbrad Foothills is a green, fertile region that represents the last pastoral bastion of the fallen kingdom of Lordaeron. Despite having largely escaped the Scourge's plague, the land is torn apart by brutal open war between the humans of Southshore and the Forsaken entrenched at Tarren Mill. It serves as a violent crossroads where the armies of the Alliance and the Horde clash without mercy. While northern Lordaeron rots under the blight of the Scourge, Hillsbrad remains strikingly green. Its rolling pastures, pine groves, and working farmsteads offer travelers a rare glimpse of what the kingdom looked like before the Third War. Yet that tranquil appearance is deceptive. The peaceful fields and rural roads are constantly swept by armed patrols, rogue mercenaries, and scavenger beasts. What should be Lordaeron's breadbasket has instead become its most contested borderland. The political heart of Hillsbrad is defined by two entrenched strongholds. In the south along the coast lies Southshore, an Alliance haven populated by human refugees and soldiers fiercely loyal to the Alliance. To the north sits Tarren Mill, once a quiet human farming hamlet that was wiped out by the Scourge and later fortified as the Forsaken's southernmost garrison. The open ground between the two settlements is known throughout Azeroth as a relentless kill zone, where Alliance and Horde champions wage perpetual skirmishes for control of the region. Hillsbrad's history of violence runs deep. During the Second War, its coast and hills witnessed the first massive clashes between the Grand Alliance and the Old Horde. Later, the fortress of Durnholde Keep served as the internment camp where Thrall was raised before leading the orcish rebellion. Today, Durnholde lies in ruins, seized by the Syndicate—displaced human nobles turned bandit cutthroats. Coastal murlocs, hostile gnolls, and the shadowed dead on Purgation Isle ensure that no corner of the hills is truly secure.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_hillsbrad-2c06b6bc8d08ac5ca442/1-0000.mp3", duration = 114.442449, start = 0},
  },
}
P.transport["zone:hinterlands"] = {
  hash = "a53dc6",
  fullHash = "a53dc6",
  text = "The Hinterlands. The Hinterlands are a rugged, densely forested wilderness in eastern Lordaeron, tucked between the Plaguelands and the sea. The region is defined by ancient Amani troll temple ruins, the towering aeries of the Wildhammer clan at Aerie Peak, and a colossal Great Tree anchoring a mysterious rift to the Emerald Dream. Long before humans or dwarves walked northern Lordaeron, the forest trolls of the Amani Empire held dominion over the Hinterlands. Following their defeat in the ancient Troll Wars, their empire shattered into disparate tribes. Centuries later, after the tragic War of the Three Hammers drove the Wildhammer dwarves from Grim Batol, the dwarves migrated north and made their home on the surface at Aerie Peak. Taming the native gryphons and embracing shamanic traditions, the Wildhammer constructed a massive skybound stronghold. The trolls viewed these surface-dwelling dwarves as unwelcome squatters upon ancestral lands, sparking a ceaseless feud of skirmishes and raids. Three distinct forest troll factions occupy the dense canopy and crumbling stone temples. The brutal and fanatical Vilebranch tribe is the strongest, maintaining sprawling strongholds at the terraced temple-city of Jintha'Alor and the towering Altar of Zul. To the south, the weaker Witherbark tribe clings to Shadra'Alor and Hiri'Watha. The nomadic Revantusk tribe, long scorned by their cousins and lacking a true home, chose a radical path after the Third War: they struck a treaty with Thrall's New Horde. Bolstered by orcish and Forsaken aid, the Revantusk founded Revantusk Village on the eastern sea cliffs, carving out a defiant coastal bastion.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_hinterlands-5c807dd3a46b805a3e7d/1-0000.mp3", duration = 100.414694, start = 0},
  },
}
P.transport["zone:lochmodan"] = {
  hash = "a5e8c9",
  fullHash = "a5e8c9",
  text = "Loch Modan. Loch Modan is a temperate mountain valley east of Dun Morogh, renowned for its massive alpine lake held in place by the monumental Stonewrought Dam. Centered around the dwarven town of Thelsamar, the region struggles under encroaching trogg infestations, kobolds in the mines, and aggressive ogres in the northeast highlands. Situated in eastern Khaz Modan, Loch Modan presents a stark, pleasant contrast to the frozen snowfields of Dun Morogh. Rugged mountain peaks enclose a temperate valley of pine and birch, cradling the Loch itself. This massive body of fresh water is held in place by the Stonewrought Dam, an architectural triumph that towers along the northern rim. The peaceful settlement of Thelsamar serves as the civic heart of the territory, housing traveling mountaineers, hunters, and miners who ply the productive veins of copper and tin scattered throughout the hills. Loch Modan's tranquil scenery conceals recurrent violence. Broken catapults and ballistae resting on the lake bed remain from the Second War, when the orcish Horde occupied the valley before the dwarves drove them out. More recently, dwarven archaeological excavations accidentally unearthed subterranean swarms of savage troggs. Led by savage chieftains, trogg tribes have overrun the southern canyons of Stonesplinter Valley and the Valley of Kings, threatening trade routes and forcing the Ironforge Mountaineers to wage a desperate defense.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_lochmodan-b8602b1251a48b2015c1/1-0000.mp3", duration = 81.4236735, start = 0},
  },
}
P.transport["zone:mulgore"] = {
  hash = "698d52",
  fullHash = "698d52",
  text = "Mulgore. Mulgore is the ancestral homeland of the tauren, a lush, sheltered valley of emerald grasslands, towering plateaus, and rolling plains nestled beneath the Stonetalon Mountains. Surrounded by high natural mountain walls, the realm was secured after Cairne Bloodhoof allied with Thrall's Horde to drive out the marauding centaur. Today, it serves as the spiritual and territorial heartland of the united tauren tribes, overseen from the great mesa city of Thunder Bluff. For generations, the tauren lived as nomads, perpetually hunted and displaced across the central plains by aggressive centaur warbands. Their fortune shifted when High Chieftain Cairne Bloodhoof encountered Thrall and his displaced orcs. Recognizing shared ideals of honor, shamanism, and strength, the tauren forged an alliance with the nascent Horde. With orcish assistance, Cairne broke the centaur's grip on the region and led his people into Mulgore. Here, they built permanent settlements for the first time in centuries, crowning the highest northern mesas with their capital, Thunder Bluff. Reaching maturity in Mulgore requires answering the call of the Great Hunt and honoring the Earthmother. Young tauren begin their training on the southern plateau of Red Cloud Mesa at Camp Narache under Chief Hawkwind. As they descend into the Golden Plains and Bloodhoof Village, they undertake the Rites of the Earthmother, learning to commune with ancestral spirits, forage native herbs, and respect the herds of kodos and tallstriders that sustain their civilization. Despite its tranquil appearance, Mulgore faces growing threats from all quarters. Displaced quilboar have entrenched themselves within Brambleblade Ravine and defiled the sacred burial grounds of Red Rocks. In the mountains, Windfury harpies prey upon wild game, while Palemane gnolls strike from hidden caves. More troubling still are external exploitations: the commercial goblins of the Venture Company have begun defiling the sacred water wells and quarrying the eastern hills, while dwarven explorers from Bael Modan have established the Bael'dun Digsite to unearth ancient titan artifacts against tauren protests.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_mulgore-c8215af678a1254283c9/1-0000.mp3", duration = 130.272653, start = 0},
  },
}
P.transport["zone:orgrimmar"] = {
  hash = "3d5e0c",
  fullHash = "3d5e0c",
  text = "Orgrimmar. Orgrimmar is the fortress capital of the orcs and the beating heart of Thrall's New Horde. Carved directly into the towering red-rock canyons of northern Durotar, the fortified city stands as a monument to orcish perseverance and an unyielding sanctuary for trolls, tauren, and Forsaken allies alike. Following the Third War, Warchief Thrall led the orcs to the arid coasts of Kalimdor to build a homeland free from demonic corruption and human bondage. Naming the harsh region Durotar after his father, Thrall established Orgrimmar in memory of his fallen mentor, Orgrim Doomhammer. Raising the city required blood and sweat; aided by the tauren, the Darkspear trolls, goblin engineers, and the Champion Rexxar, the Horde drove back encroaching centaur, harpies, and ferocious thunder lizards to secure the canyon stronghold. Orgrimmar is naturally fortified by rugged mountains that shield it from both foreign invaders and the violent razor-winds sweeping through Durotar. The settlement is partitioned into distinct natural hollows. The Valley of Strength serves as the bustling civic gatehouse, leading deeper into the trade bazaar of The Drag. Tauren druids and shaman congregate in the serene pools of the Valley of Wisdom, while Darkspear shadow hunters and witch doctors dwell among the stilted pavilions of the Valley of Spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_orgrimmar-63245c052bb0512554a3/1-0000.mp3", duration = 83.0432653, start = 0},
  },
}
P.transport["zone:ragefire"] = {
  hash = "f9b5eb",
  fullHash = "f9b5eb",
  text = "Ragefire Chasm. Ragefire Chasm is a network of winding volcanic tunnels situated directly beneath the orcish capital of Orgrimmar. Entered through the dark hollows of the Cleft of Shadow, the chasm is overrun by savage troggs and a demonic sect of cultists known as the Searing Blade. Left unchecked, the dark powers and subterranean swarms festering below threaten the very foundation of the young Horde nation. Beneath the dust and red rocks of Orgrimmar lies a blistering maze of volcanic corridors and lava pits. While orcish builders forged their new home above, aggressive Ragefire troggs began erupting from deep below the surface. Magatha Grimtotem sought to open diplomatic channels with the brutes on behalf of Thunder Bluff, but her envoy Maur Grimtotem was slaughtered, proving the troggs will yield only to force. Far more dangerous than simple troggs is the presence of the Searing Blade, a fanatical cell loyal to the Shadow Council. Operating from the dark caverns alongside the magma streams, this demonic cult plots the utter ruin of the fledgling Horde. They are led by the warlock Jergosh the Invoker, a cunning satyr named Bazzalan, and the vicious felguard Taragaman the Hungerer, who presides over an altar in the lava lake.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_ragefire-0aa273d3b9dc09b56cb7/1-0000.mp3", duration = 73.3518367, start = 0},
  },
}
P.transport["zone:redridge"] = {
  hash = "221caf",
  fullHash = "221caf",
  text = "Redridge Mountains. East of Elwynn Forest, the Redridge Mountains feature rushing rivers, wooded slopes, and the serene expanse of Lake Everstill. Despite its scenic heights, the region is besieged by hostile Shadowhide gnolls and the encroaching Blackrock orcs of the Dark Horde. With the kingdom's military tied up by internal strife in Stormwind, the lakeside town of Lakeshire must rely on wandering mercenaries to hold the line. The Redridge range was once among the most peaceful corners of the kingdom, supplying Stormwind with timber, freshwater fish, and crops. Today, that quiet life has eroded. The lakeside township of Lakeshire sits perpetually fortified against aggressive incursions. To the east, Stonewatch Keep—once a proud bastion of the kingdom—has fallen under the control of renegade Blackrock orcs, cutting off roads and threatening to overrun the eastern valleys entirely. Geographically, these peaks form part of the spine running down the subcontinent of Azeroth. Centuries ago, the mountain chain reached much farther north until the Dark Iron clan inadvertently summoned the Firelord Ragnaros, tearing the earth asunder and creating the fiery crater of Blackrock Mountain. That cataclysm severed the northern peaks into the ash-choked Burning Steppes, leaving only the southern Redridge valleys lush, green, and vulnerable to attacks descending from the slopes above. While Magistrate Solomon and Marshal Marris plead for reinforcements, the regency council in Stormwind has effectively abandoned Lakeshire to fend for itself. Desperate entreaties sent to Sentinel Hill and Darkshire yield nothing, as both sister settlements are crippled by their own crises. With reinforcements nowhere in sight, local magistrates must hire any capable sellsword willing to brave the Lakeridge Highway, clear the gnoll camps, and push back the shadow looming over Lake Everstill.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_redridge-bbe008f79d4d02d73d88/1-0000.mp3", duration = 110.524082, start = 0},
  },
}
P.transport["zone:riverglades"] = {
  hash = "f8c733",
  fullHash = "f8c733",
  text = "Riverglades. The Riverglades is a contested river valley east of the Burning Steppes and Badlands, historically claimed by the Kingdom of Stormwind. Overrun by the Old Horde during the First War and largely abandoned by the crown, the region remains a battleground as local human loyalists clash with modern Horde outposts and local wildlife. It borders Redridge Mountains to the southwest, Swamp of Sorrows to the south, and faces Tanaris across the sea. Historically part of the Kingdom of Stormwind, the Riverglades fell into ruin during the First War when the Old Horde swept through the region. Its central settlement, Sunnyglade, was sacked by the orcs, who spared its mage tower solely to study human sorcery before enslaving the surviving townsfolk. Though Stormwind soldiers mounted an effort to liberate the captives and rebuild, the kingdom eventually deemed the entire valley lost and diverted resources toward defending the core homelands. For years, the region remained largely cut off from formal crown support. Despite being left behind by Stormwind's higher leadership, the human defenders never fully surrendered their homeland. Under Knight Commander Demar Brant of the legendary Brotherhood of the Horse, the remaining loyalists hold Farholde Keep as a bastion against the wilderness and hostile invaders. Meanwhile, the modern Horde maintains their own strong presence nearby at outposts like Rog'mar and Bolder'ok, ensuring that the ancient conflict over the glades continues to smolder. Stretching along the coast of the Forbidding Sea, the Riverglades is flanked by mountainous terrain and winding waterways. Travelers on foot can cross west through Blackrock Pass to the Burning Steppes, wind southwest through Redridge Pass toward the Redridge Mountains, navigate south into the Swamp of Sorrows, or trek northwest past Twilight's Shroud into the Badlands. On the coast, Powderfuse Port provides sea passage connecting directly across the ocean to Steamwheedle Port in Tanaris.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_riverglades-141c78933c6f6f5e79cb/1-0000.mp3", duration = 116.924082, start = 0},
  },
}
P.transport["zone:ruinsoflordaeron"] = {
  hash = "d6fd25",
  fullHash = "d6fd25",
  text = "Ruins of Lordaeron. Perched directly above the subterranean Undercity, the Ruins of Lordaeron are the hollow remains of humanity's once-mighty northern kingdom. Fallen to the Scourge and Prince Arthas during the Third War, the surface streets and cracked plazas now crawl with wandering monstrosities, vengeful specters, and vile experimenters. Both the Alliance and the Horde dispatch ventures into this blighted citadel to reclaim relics of the fallen past or purge the horrors lurking above the Forsaken capital. Capital City was once the crown jewel of the Eastern Kingdoms, the seat of King Terenas Menethil II and the beating heart of human civilization. When Prince Arthas returned from Northrend, he slew his father in the throne room and unleashed the undead upon the citizenry. Today, while the Forsaken dwell in the catacombs of the Undercity below, the surface ruins remain a forsaken twilight zone. Broken archways and weed-choked cobbles shelter feral beasts like Witherfang and deranged remnants of the past. The dangers within the ruined grounds go beyond restless dead. Apothecaries and sinister figures like Viktor the Vile work on testing new plagues among the shadows, while twisted experiments like The Abandoned roam freely. Wrathful spirits such as Rath'mael and cursed retainers like The Baron haunt the collapsed hallways, locked in unending torment and striking out against any living or undead trespassers who cross their paths.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_ruinsoflordaeron-efaf3c29740294d9b4f3/1-0000.mp3", duration = 88.1110204, start = 0},
  },
}
P.transport["zone:searinggorge"] = {
  hash = "ee1599",
  fullHash = "ee1599",
  text = "Searing Gorge. Searing Gorge is a scorched, desolate canyon in southern Khaz Modan, bordering Blackrock Mountain to the south. Once a verdant expanse of the Redridge Mountains, it was devastated over two centuries ago by the apocalyptic summoning of Ragnaros the Firelord. Today, the gorge is heavily worked by the Dark Iron clan, whose extensive slave mines in the Cauldron are closely monitored by the breakaway Thorium Brotherhood. Before the War of the Three Hammers, the territory that is now Searing Gorge was a green, rolling mountain region connected to the Redridge chain. That lush landscape ceased to exist over two hundred and thirty years ago when Sorcerer-Thane Thaurissan, desperate to turn the tide of defeat, summoned Ragnaros from the depths beneath the world. The cataclysmic emergence of the Firelord tore the earth asunder, raised Blackrock Mountain, reduced the grand Dark Iron city of Thaurissan to smoking ruins, and burned the northern valley into a cracked expanse of ash, sulfur, and volcanic glass. Seeking raw materials to supply their war machine after the loss of their old capital, the Dark Iron dwarves seized the desolate gorge. In the center of the valley lies the Cauldron, a colossal open-pit excavation plunging deep into the stone. Within its lower recesses sits the Slag Pit, a brutal subterranean mining complex. Here, Dark Iron overseers and lumbering war golems drive captured enemies into grueling slave labor, pulling iron, mithril, and rare deposits of Dark Iron ore out of the burning rock under the constant threat of lava surges and roaming beasts. Perched on the northern crags overlooking the excavation sits Thorium Point, the fortified outpost of the Thorium Brotherhood. Having split from their kin in Blackrock Mountain, these master craftsmen offer neutral shelter to travelers willing to undermine the Dark Iron operations or supply them with rare smelting components. Access to the gorge itself is tightly restricted: the Alliance keeps the Stonewrought Pass locked down behind heavy iron gates toward Loch Modan, while Horde expeditions from nearby Kargath have cut a narrow trail through the eastern badlands to scout the region.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_searinggorge-c39fa8b7e3adf6662df1/1-0000.mp3", duration = 130.246531, start = 0},
  },
}
P.transport["zone:shadowfang"] = {
  hash = "409aaf",
  fullHash = "409aaf",
  text = "Shadowfang Keep. Perched on the rugged bluffs above Pyrewood Village, Shadowfang Keep is the gloomy stronghold of the rogue Kirin Tor wizard, Archmage Arugal. Once the ancestral estate of Baron Silverlaine, the bastion now teems with feral worgen beasts and the tormented phantoms of its slaughtered defenders. For adventurers traversing southern Silverpine, the keep represents the dark epicenter of the beastly scourge consuming the region. Before it was shrouded in nightmare, Shadowfang was known as Silverlaine Keep, a noble seat garrisoned by the pious Commander Springvale. When the Scourge swept through Lordaeron during the Third War, Dalaran's wizards fell in droves. Desperate to stem the rising dead, Archmage Arugal defied Kirin Tor leadership and delved into the research of the wizard Ur, summoning extra-dimensional worgen to turn the tide. The summoned beasts savaged the undead, but rapidly slipped beyond all mortal control, breaking into southern Silverpine and storming the bastion. Baron Silverlaine and his entire court were massacred, doomed to haunt the stone halls alongside the feral monsters that overran their home. Broken by guilt and madness, Arugal retreated within the blood-stained battlements, adopting the ravenous wolf-men as his beloved 'children' and christening the castle Shadowfang Keep. Deep in the stone roosts, lupine packs and shadowy hounds flourish under trainers like Wolf Master Nandos, watched over by Arugal's massive lupine beast, Fenrus the Devourer. Outside the walls, the curse did not halt; nearby Pyrewood Village remains trapped in a horrifying nocturnal cycle, its residents walking as men by day and hunting as ravenous worgen beneath the moon, tethered inexorably to the mad archmage perched on the heights above.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_shadowfang-bacf25f92b175b3ca200/1-0000.mp3", duration = 103.967347, start = 0},
  },
}
P.transport["zone:shendralas"] = {
  hash = "13175a",
  fullHash = "13175a",
  text = "Shen'dralas. Shen'dralas is a rugged, contested wilderness situated between Feralas, Mulgore, and south-eastern Desolace. Dominated by ancient night elven remnants and troubled borders, it serves as a volatile crossroads where encroaching centaur, displaced outcasts, and bristling quilboar collide. Tucked away in the heights south-east of Desolace and bordered by Mulgore and Feralas, Shen'dralas is a raw borderland far removed from major faction capitols. Its craggy passes and hidden enclaves harbor desperate groups carving out existence on the edge of wild Kalimdor. From secluded vantage points like Evenshade Overlook to lawless refuges like Outcast Hideaway, the zone is defined by those who wish to watch unseen or stay forgotten. The land bears the distinct mark of the highborne legacy that gave it its name, yet it is far from peaceful. Centaur conflict bleeds across the Magram Front, keeping old blood feuds alive and well along its borders. Meanwhile, encroaching quilboar maintain fortified redoubts such as Bristleback Retreat, turning every shadowed ravine into contested territory for any traveler passing through. Leading out north-west toward Desolace lies the Valley of Bones, a grim corridor that serves as the primary overland access route into Shen'dralas. Bleached by sun and wind, this passage stands as a harsh reminder of the violent struggles that constantly ripple through these crags.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_shendralas-130734e739db7ead42ed/1-0000.mp3", duration = 87.9804082, start = 0},
  },
}
P.transport["zone:silithus"] = {
  hash = "90083a",
  fullHash = "90083a",
  text = "Silithus. Silithus is a desolate, wind-scoured desert located in the far southwestern corner of Kalimdor. Beneath its arid sands lie vast colonies of insectoid silithid and the ancient ruins of Ahn'Qiraj, sealed a millennium ago behind the formidable Scarab Wall. Today, the druids of the Cenarion Circle maintain an embattled vigil against creeping swarms, doomsday cultists. Reaching Silithus requires navigating through the primeval jungle of Un'Goro Crater and ascending a wide, rocky pass nestled in its northwestern corner. The transition is stark: lush primordial growth vanishes into a vast expanse of shifting dunes, jagged stone, and unnatural towering hives. Water is virtually nonexistent, and the winds carry the hum of insect wings and the whispering sands. The Cenarion Circle maintains Cenarion Hold near the center of the desert, serving as the sole bastion of civilization and shelter for travelers, researchers, and warriors braving the hostile wastes. A thousand years ago, this arid expanse served as the battlefield for the War of the Shifting Sands. An allied army of night elves and great dragonflights fought desperately to drive back the Qiraji, an insidious insectoid empire spawned from the ancient Aqiri civilization. When total victory proved impossible, the defenders sealed the swarms within their stronghold using the Scarab Wall and the enchanted Scarab Dais. While the monumental gates held, subterranean tunnels allowed the beast-like silithids to burrow out, establishing sprawling colonies such as Hive'Ashi, Hive'Zora, and Hive'Regal throughout the sands. The apocalyptic Twilight's Hammer cult has entrenched itself across several fortified outposts, summoning elemental terrors and venerating the dark power slumbering beneath Ahn'Qiraj. Cenarion Circle observers monitor the desert's spreading silithid colonies and the ancient threat behind the Scarab Wall.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_silithus-8b539d344bbfc0fcded3/1-0000.mp3", duration = 116.37551, start = 0},
  },
}
P.transport["zone:silverpine"] = {
  hash = "a9abbb",
  fullHash = "a9abbb",
  text = "Silverpine Forest. Silverpine Forest is an eerie, mist-laden woodland stretching along Lordaeron's western coast between Tirisfal Glades and the sealed Greymane Wall. Haunted by the lingering scars of the Scourge plague, it serves as the contested southern frontier of the Forsaken. Travelers here face feral worgen roaming the shadows, diseased gnolls, and hostile human enclaves. Once celebrated as a lush wonder of Lordaeron through which noble travelers journeyed to Capital City, Silverpine Forest has withered under the touch of the Third War. Ghostly fogs weave between dying, silver-barked pines, and ruined farmsteads sit abandoned to the wilderness. To the north lies Tirisfal Glades, while the eastern shore borders Lordamere Lake. To the south stands the imposing and shut Greymane Wall, sealing off the isolationist kingdom of Gilneas from the surrounding chaos. The Forsaken maintain their central outpost at the Sepulcher, striving to secure the woods from enemies on all sides. Silverpine's most infamous peril is the worgen curse. High above the southwest woods sits Shadowfang Keep, the former seat of Baron Silverlaine, now dominated by the mad Dalaran archmage Arugal. Seeking to repel the Scourge during the Third War, Arugal summoned extra-dimensional wolf-beasts. The creatures turned on their summoners, spreading a lycanthropic curse across the southern woods. In Pyrewood Village, ordinary-looking human villagers go about their chores by daylight, but transform into savage worgen beneath the night sky.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_silverpine-64ddc5fc8e7c934b0e26/1-0000.mp3", duration = 93.5444898, start = 0},
  },
}
P.transport["zone:stonetalon"] = {
  hash = "71506c",
  fullHash = "71506c",
  text = "Stonetalon Mountains. The Stonetalon Mountains are a rugged, wind-carved chain of craggy peaks bordering Ashenvale, the Barrens, and Desolace. Revered by both the night elves and the tauren as a sacred sanctuary, the region's sacred heights stand in sharp contrast to the smoke and machinery choking its lower canyons. Today, the mountains are torn by deforestation, volatile elemental devastation, and simmering border hostilities. Rising sharply out of central Kalimdor, the Stonetalon range catches the moisture drifting from the western seas, giving birth to sudden downpours and treacherous, rain-slick sandstone trails. The dominant feature of the lower valleys is the incessant scouring gale known as the Ill Winds, capable of blinding travelers with grit or throwing the careless straight off sheer cliffsides. Higher up, evergreen forests mantle the ridges surrounding Stonetalon Peak, where the night elves tend ancestral barrows and glades, watching over the sacred roosts of wyverns and hippogryphs that nest along Mirkfallon Lake. The peaceful solitude of the range has been violently disrupted by the arrival of the Venture Company. Setting up sprawling logging camps and digging deep strip mines in Windshear Crag, the goblins—aided by the deranged leper gnome Gerenzo Wrenchwhistle—have clear-cut old-growth timber, blackened the skies with furnace smoke, and poured industrial sludge into the mountain runoff. Their greed has provoked swift retaliation: local shamans from Orgrimmar answered the agonized cries of the mountain spirits, while small Alliance camps stationed nearby fight back against the defilers to protect what remains of the highlands. To the south lies the Charred Vale, once a blossoming wilderness, now reduced to an ash-covered wasteland churning with rogue fire elementals, black dragonspawn, and harpies. While the peaks were the historic site where the Horde and Alliance forged an uneasy truce during the Third War under the guidance of the mysterious Oracle, current relations are fraying. Renegade Grimtotem tauren operate out of seized encampments, and Darkspear trolls in Malaka'jin clash with Alliance incursions pushing outward from the Barrens and Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_stonetalon-40b43c22447f2b71cb40/1-0000.mp3", duration = 130.45551, start = 0},
  },
}
P.transport["zone:swampofsorrows"] = {
  hash = "89c06e",
  fullHash = "89c06e",
  text = "Swamp of Sorrows. The Swamp of Sorrows is a murky, brackish wetland tucked between Deadwind Pass and the arid Blasted Lands. Once the northern expanse of the ancient Black Morass, its salt-crusted bogs are home to dangerous wildlife, green dragonspawn, and the ruined Temple of Atal'Hakkar sunken beneath the Pool of Tears. While the Horde maintains the fortified garrison of Stonard, the Alliance has no safe haven within the mire, leaving the wilderness largely untamed. Long before the coming of the Orcish Horde, these marshes formed the northern half of an enormous wetlands known as the Black Morass. Following the shattering of the Gurubashi Empire, the fanatical Atal'ai trolls fled into the mire to erect the Temple of Atal'Hakkar, intending to summon their bloodthirsty loa, Hakkar the Soulflayer. Sensing the catastrophe, the Aspect Ysera unleashed her powers, drowning the cursed pyramid beneath the waters of the Pool of Tears. Green dragonflight guardians led by Eranikus were stationed to vigilantly watch over the drowned structure. When the Dark Portal's cataclysm later scorched the southern morass into the Blasted Lands, this northern fen earned its current sorrowful name. Stonard serves as the primary civilized foothold in the swamp. Originally established during the First War alongside the now-ruined settlements of Rockard and Kyross, the outpost was rebuilt under Thrall to serve as the Horde's southernmost staging ground in the Eastern Kingdoms. Beyond Stonard's palisades, strange wanderers roam the fen. A group of draenei stragglers stranded on Azeroth succumbed to homesickness and madness, degenerating into feral Lost Ones. However, a small enclave of lucid Broken exiles persists at the Harborage, wary but willing to trade peacefully with travelers. Surviving the swamp requires constant vigilance against its predatory wildlife. Deep bogs hide lunging crocolisks, venomous spiders, prowling swamp jaguars, and wandering bog beasts encrusted with marsh debris. Coastal caverns and the Misty Reed Strand crawl with vicious murlocs, while the salt-laden tide creeps continually inland, preserving rotten logs in thick briny crusts. Farther east lies Sorrowmurk, where aggressive elite dragonspawn fiercely guard the approaches to the Sunken Temple, attacking anyone who strays near their vigil.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_swampofsorrows-e4fa0d8548d50a7c6952/1-0000.mp3", duration = 143.307755, start = 0},
  },
}
P.transport["zone:teldrassil"] = {
  hash = "3be20d",
  fullHash = "3be20d",
  text = "Teldrassil. Teldrassil, meaning 'Crown of the Earth', is a gargantuan new World Tree raised off Kalimdor's northwest coast. Grown by the druids in the wake of the Third War, its colossal boughs support an entire twilit wilderness and the night elf capital of Darnassus. Yet beneath its tranquil, moonlit canopy, a creeping corruption has begun to stir. Teldrassil is not merely a tree; it is an elevated ecosystem standing tall amidst the waters of the Veiled Sea. Its gargantuan limbs support rolling hills, flowing rivers fed by morning dew, misty lakes, and dense ancient glades. At its western edge sits Darnassus, the grand capital of the kaldorei. At the base of its monumental trunk lies Rut'theran Village, connected to the crown above by a mystical gateway and serving as the island's primary harbor. Following the sacrifice of Nordrassil during the Third War and the mysterious disappearance of Shan'do Malfurion Stormrage into the Emerald Dream, Archdruid Fandral Staghelm convinced the Circle of Ancients to grow a replacement. Staghelm hoped to restore the kaldorei to their lost immortality. However, Nozdormu and the Dragon Aspects deemed the effort hubristic and withheld their blessings. Without their vital warding, Teldrassil's growth has suffered from unnatural flaws.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_teldrassil-357a25b4c1a08efbd0a9/1-0000.mp3", duration = 79.7518367, start = 0},
  },
}
P.transport["zone:thousandneedles"] = {
  hash = "3fb560",
  fullHash = "3fb560",
  text = "Thousand Needles. Thousand Needles is a sprawling canyon of sheer sandstone pillars and sunbaked salt pans in southern Kalimdor. Tauren tribes cling to settlements atop towering mesas to escape aggressive centaur packs, while gnomish and goblin tinkerers run high-speed rocket cars across the dried-up seabed of the Shimmering Flats. Before the Great Sundering shattered ancient Kalimdor, this territory was a lush river canyon fed by inland waterways flowing out toward the sea. The cataclysm tore the continent apart, thrusting the riverbed above the water table and altering the river's path until only dry stone and sandstone spires remained. Today, dozens of slender cylindrical columns rise from the canyon floor like a petrified forest. Tauren settled on the summits, stringing precarious rope bridges between peaks to establish villages out of reach of the hostile centaur marauders patrolling the shadow-draped canyon floor below. Atop the needle-like spires, life is far from peaceful. At Freewind Post, tauren loyal to the Horde contend not only with predatory wind serpents and wyverns from Highperch, but also with their treacherous kin: the militant Grimtotem clan entrenched at Darkcloud Pinnacle. Cliffwatcher Longhorn oversees the defense of the plateau, seeking bold fighters to strike at Grimtotem agitators and secure the fragile bridges linking the peaks. To the north, the enormous mechanical winches of the Great Lift carry travelers down from the southern Barrens, though crossing the canyon floor remains a deadly gambit. To the southeast, the canyon walls peel back into the Shimmering Flats, an enormous, desiccated salt pan sitting below sea level. In this harsh, blinding white expanse, gnomes and goblins maintain an uneasy neutrality around the Mirage Raceway. Rival engineers Pozzik and Fizzle Brassbolts race experimental rocket cars across the hard salt to settle which race possesses technological superiority. The pit stop attracts scoundrels, swindlers like Kravel Koalbeard, and hunters hunting the hardy scorpions, turtles, and basilisks that roam the searing basin.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_thousandneedles-bcf2ef9a169747219bbd/1-0000.mp3", duration = 127.190204, start = 0},
  },
}
P.transport["zone:thunderbluff"] = {
  hash = "f8b36f",
  fullHash = "f8b36f",
  text = "Thunder Bluff. Thunder Bluff is the magnificent capital city of the tauren, perched atop windswept red-rock mesas rising above the grasslands of Mulgore. Founded by High Chieftain Cairne Bloodhoof after uniting the nomadic tribes with the aid of the New Horde, it serves as the cultural, spiritual, and mercantile heart of his people. Connected by swaying rope bridges and wooden lifts, the city offers safety from centaur marauders and a peaceful sanctuary for travelers across Kalimdor. For countless generations, the tauren lived as nomadic wanderers across Kalimdor, locked in a brutal struggle for survival against ravenous centaur tribes. That desperate era ended during the Third War when Cairne Bloodhoof joined forces with Warchief Thrall. Together, the orcs and tauren broke the centaur assaults and secured the lush pastures of Mulgore. To protect their future, Cairne led the allied tribes to the safety of these natural stone bastions, founding Thunder Bluff as the first unified, permanent home the tauren had possessed in centuries. Spanning several high mesas linked by suspended rope bridges, Thunder Bluff seamlessly blends natural architecture with tauren practicality. The central bluffs host the bustling markets, bank, inn, and towering Wind Rider roost, while three specialized mesas branch out across the abyss. Hunter Rise serves the city's scouts and trackers; Elder Rise hosts lorekeepers and the Cenarion Circle under Archdruid Hamuul Runetotem; and Spirit Rise is devoted to spiritual communion, sheltering shamans, priests, and the mysterious subterranean caverns known as the Pools of Vision.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_thunderbluff-52eb1d8a9f5f8c59d8ea/1-0000.mp3", duration = 94.4065306, start = 0},
  },
}
P.transport["zone:tirisfal"] = {
  hash = "99d507",
  fullHash = "99d507",
  text = "Tirisfal Glades. Tirisfal Glades is the haunting northern territory of Lordaeron, now serving as the heartland of Lady Sylvanas Windrunner and the Forsaken. Beneath blighted skies and rotting boughs lie fallen manors, dormant crypts, and the vast underground capital of the Undercity. Surrounded by mindless Scourge and zealous Scarlet crusaders, it is a perilous realm where free-willed undead carve out their survival. Once the fertile cradle of humanity, Tirisfal Glades has withered beneath the curse of the Lich King's plague. The sun rarely penetrates the murky gloom, casting an eternal sickly pale over dying woods, neglected pumpkin patches, and cold coastal hills. While remnants of old farmsteads like the Agamand Mills and Balnir Farmstead remain, their former masters have largely been swept into mass graves or risen as restless dead. Despite the devastation, a dark resilience permeates the countryside, anchored by towns like Brill and the cloistered sanctuary of Deathknell, where freshly awakened Forsaken learn to endure their second life. Though Lady Sylvanas claims dominion over the region from the subterranean Ruins of Lordaeron, the Forsaken remain embattled on all sides. Residual Scourge thralls still infest hollows, fields, and dilapidated crypts, entirely subservient to the frozen throne of Northrend. To the east, the fanatical Scarlet Crusade has made northern Tirisfal its primary bastion, operating out of the Scarlet Monastery. Zealously devoted to the extermination of every undead creature, living and unliving alike, their outposts and patrols wage constant guerrilla warfare against Forsaken scouts and civilian travelers. Long before human kingdoms crowned their first monarchs, the Glades bore an ancient legacy. High elven exiles briefly tried to settle these woods before shadowy energies deep beneath the earth began driving them mad, prompting their migration north. In later centuries, the secret mortal cabal known as the Council of Tirisfal chose these shadowed groves to empower solitary Guardians, shielding Azeroth from demonic intrusion.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_tirisfal-955efef9f6f37e7c63a5/1-0000.mp3", duration = 129.567347, start = 0},
  },
}
P.transport["zone:undercity"] = {
  hash = "d78295",
  fullHash = "d78295",
  text = "Undercity. Deep beneath the shattered ruins of Lordaeron's Capital City lies the Undercity, the dark stronghold of the Forsaken. Originally carved out of ancient royal crypts and dungeons by the Scourge, it was seized by Lady Sylvanas Windrunner and remade into an impenetrable subterranean sanctuary. Today it serves as the seat of Forsaken power and the Horde's vital bastion in the northern Eastern Kingdoms. Long before the plague swept Lordaeron, the catacombs, dungeons, and sewers beneath the palace were collectively known as the Undercity. It held the tombs of nobility, the kingdom's deepest prisons—where the former Warchief Orgrim Doomhammer was once held before his escape—and the poorest denizens of the realm. When Arthas Menethil murdered King Terenas and laid waste to the capital in 20 ADP, the prince ordered his undead servants to excavate and expand the subterranean passages into a fortified seat of Scourge rule. The Scourge never saw their dark capital completed. When the Lich King's powers waned following the battle of Mount Hyjal, Lady Sylvanas Windrunner broke free from the hive mind, taking thousands of undead with her. She lured Arthas into an ambush and drove him back to Northrend. After a vicious three-way civil war against Scourge remnants, dreadlords, and human resistance, Sylvanas claimed the half-finished catacombs. Naming her people the Forsaken, she oversaw years of labor completing the sprawling subterranean city. The Undercity is laid out in concentric rings divided into functional quarters. At its heart lies the Trade Quarter, connected by great lifts to the palace ruins above. Surrounding it are the War Quarter, Rogues' Quarter, Magic Quarter, and the toxic Apothecarium, where the Royal Apothecary Society brews virulent plagues in green slime-filled canals. Deeper still lies the Royal Quarter, where the Banshee Queen holds court alongside her dreadlord commander, Varimathras, guarded by legions of towering abominations.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_undercity-2fb6209709ced3b3cf7b/1-0000.mp3", duration = 117.86449, start = 0},
  },
}
P.transport["zone:ungoro"] = {
  hash = "10ee3a",
  fullHash = "10ee3a",
  text = "Un'Goro Crater. Un'Goro Crater is a sunken, primordial jungle tucked between the arid wastes of Tanaris and Silithus. Dominated by roaming dinosaurs, living elementals, and a central volcano, this lush caldera is filled with ancient Titan relics and power crystals whose origins remain a profound mystery. Sandwiched between desert expanses, Un'Goro Crater defies the geography of southern Kalimdor. Ancient night elf records detailing the War of the Shifting Sands note that the insectoid Qiraji were turned back at the crater's edges, unable to penetrate what their tongue named the 'God Lands.' Scholars theorize the caldera served as a testing ground or ancient dwelling for the Titans during the shaping of Kalimdor. Stone pylons rise along the ridges, humming with energy, while crystal formations of blue, red, green, and yellow sprout through the primeval earth. Un'Goro contains no cities, towns, or native humanoid societies. Instead, life thrives in an untamed, primeval state. Apex devilsaurs stalk the flats of Terror Run, predatory bloodpetals lash out in the marshlands, and oozes creep across the tar pits of Lakkari. At the heart of the crater looms Fire Plume Ridge, an active volcanic peak teeming with hostile fire elementals led by the entity Blazerunner. For explorers and skinners, the basin offers unmatched natural wealth—including the coveted hides of devilsaurs—provided one survives the food chain. Civilized presence in the crater is limited almost entirely to Marshal's Refuge, an elevated camp tucked into the northern cliffs. Led by Williden Marshal, an expedition of scientists, naturalists, and fortune seekers attempted to catalogue the basin's treasures only to be battered by the monstrous wildlife and driven to high ground. Today, the refuge serves as an embattled staging ground for intrepid travelers studying the crater's mysterious power crystals, mapping volcanic activity, and keeping a watchful eye on encroaching silithid swarms breaching the southern ridges.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_ungoro-1da7209737934e76b640/1-0000.mp3", duration = 122.253061, start = 0},
  },
}
P.transport["zone:wailing"] = {
  hash = "d5f0a1",
  fullHash = "d5f0a1",
  text = "Wailing Caverns. Tucked beneath the Lushwater Oasis in the arid Barrens lies the Wailing Caverns, a labyrinthine system of subterranean springs and fissures named for the eerie whistling of trapped steam. What began as a noble druidic effort to revitalize Kalimdor's sun-bleached savanna has devolved into a warped, poisonous underworld. The caverns now teem with twisted wildlife and fallen disciples corrupted by a deep, unnatural nightmare. The night elf druid Naralex originally discovered this vast water system and devised an ambitious design: by opening a conduit straight into the Emerald Dream, he would siphon pure primal life essence through the subterranean springs, transforming the parched Barrens back into a thriving, verdant paradise. Deep within the caverns, Naralex slipped into communion with the Dream, anchored by his loyal acolytes. Tragically, rather than tapping into pure vitality, the druid's sleeping mind touched the Emerald Nightmare. The festering corruption instantly seized him, transforming his well-intentioned conduit into a valve pouring venom and madness into the underground waterways. As the Nightmare's dark energy radiated from Naralex's helpless form, his students succumbed to the madness. Forsaking the tranquil wisdom of the Cenarion Circle, they formed the fanatical Druids of the Fang. Taking reptilian forms, the sect's leaders—Lady Anacondra, Lord Cobrahn, Lord Pythas, and Lord Serpentis—now embrace the venomous mutation of the caverns rather than fighting it. They actively shield their sleeping master from any outside interference, believing this twisted growth is the true evolution of nature.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_wailing-28b339ccac3d2bfd2387/1-0000.mp3", duration = 99.84, start = 0},
  },
}
P.transport["zone:westernplaguelands"] = {
  hash = "dc8171",
  fullHash = "dc8171",
  text = "Western Plaguelands. Once the fertile agricultural breadbasket of northern Lordaeron, the Western Plaguelands now choke beneath a toxic mist and legions of undead. While Kel'Thuzad's cauldrons ruined the region's farms and towns, the soil still clings tenaciously to life. The Argent Dawn, the Alliance, the Forsaken, and the Scarlet Crusade all wage desperate campaigns across its blighted fields. Before the Third War, this land was a verdant corridor of farms stretching east from Tirisfal Glades toward Darrowmere Lake. Hearthglen governed the northern administration from Mardenholde Keep, while the sprawling town of Andorhal orchestrated the storage and export of grain across the kingdom. That crucial agricultural role made the region Kel'Thuzad's primary target. By introducing the Plague of Undeath directly into the grain shipments at Andorhal, the Cult of the Damned turned Lordaeron's sustenance into its doom. To permanently poison the soil, the Scourge raised four massive plague cauldrons across the largest agricultural estates: Felstone Field, Dalson's Tears, the Writhing Haunt, and Gahrron's Withering. Today, monstrous Cauldron Lords maintain these noxious vats, pumping venomous fog into the atmosphere. The surrounding trees twist with swollen, tumorous growths, and blighted wildlife rampages through the brush. Beneath Caer Darrow on Darrowmere Lake, Darkmaster Gandling trains necromancers within Scholomance, compounding the undead threat. Despite the omnipresence of the Scourge, several factions maintain embattled footholds. The Scarlet Crusade controls the fortress of Hearthglen in the north, purging anything they deem tainted with rabid zeal. To the south, Alliance forces stage from Chillwind Camp, while the Forsaken defend their borders at the Bulwark. Mediating and directing the fight against the undead cauldrons is the neutral Argent Dawn, which aids champions of both factions and guards Uther's Tomb—the last truly sanctified ground in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_westernplaguelands-9c6fc62d915a17ed6469/1-0000.mp3", duration = 121.70449, start = 0},
  },
}
P.transport["zone:westfall"] = {
  hash = "51e782",
  fullHash = "51e782",
  text = "Westfall. Once the fertile breadbasket of the Kingdom of Stormwind, Westfall has collapsed into a windswept, neglected territory overrun by outlaws. Deprived of official crown support and military garrisons, its surviving homesteaders cling to their farms while the Defias Brotherhood tightens its grip from the abandoned mining town of Moonbrook. For generations, Westfall fed the Kingdom of Stormwind. Its rolling pastures and wheat fields flourished until the aftermath of the Second War brought financial exhaustion and political neglect. When the kingdom poured its resources elsewhere and failed to maintain its garrisons, the territory grew fallow. Today, barren pastures, howling coastal gusts, rogue harvest golems, and raiding Riverpaw gnolls make daily survival a constant trial for the stubborn few who refuse to abandon their homesteads. Westfall's collapse accelerated when the Stonemasons Guild, denied payment for rebuilding Stormwind City, turned to open revolt. Outlawed and exiled under Edwin VanCleef, the stonemasons reconstituted themselves as the Defias Brotherhood. They claimed Westfall as their stronghold, burning stubborn farmers' fields, salting soil, and seizing abandoned mines. Operating out of the ghost town of Moonbrook, the Brotherhood now rules the majority of the countryside in all but name. With the House of Nobles ignoring Westfall's plight, local inhabitants took up their own defense. Based at the fortified post of Sentinel Hill, Gryan Stoutmantle organized the People's Militia—a volunteer force attempting to hold the line against gnolls and bandits. Lacking formal soldiers and supplies from Stormwind, the Militia relies on wandering adventurers to push back the Defias tide and protect the remaining farms.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_westfall-7aceaa920c5f1cbef177/1-0000.mp3", duration = 100.336327, start = 0},
  },
}
P.transport["zone:zephras"] = {
  hash = "72d458",
  fullHash = "72d458",
  text = "Zephras Isle. Zephras Isle is a flying island suspended within Skywall, the Elemental Plane of air. It serves as the ancestral starting home of the Skyborne, whose society now faces an existential crisis as the island's sustaining magic steadily erodes. With contact severed from neighboring sky-realms, its inhabitants struggle against elemental collapse and arriving refugees. Zephras Isle is an isolated landmass adrift in the endless winds of Skywall. For generations, the Skyborne lived here alongside native air elementals who helped preserve the magical currents holding the isle aloft. However, several centuries ago, those elemental stewards vanished entirely. Deprived of their presence and guardianship, the latent enchantments upholding the land have slowly begun to fail, causing Zephras to slowly fracture and destabilize. Zephras was not the only sanctuary inhabited by the Skyborne within the Elemental Plane. Sister islands known as Anvilas and Siroccas also drifted across Skywall, but communications between them ceased after the elementals vanished. In recent times, refugees from these crumbling neighboring landmasses have managed to reach Zephras seeking safety, bearing grim tidings that the other islands are disintegrating outright beneath their feet. With their own landmass in slow decay, the Skyborne of Zephras have begun looking beyond the boundaries of Skywall toward Azeroth. From the skydocks of Valanaar, airships now venture forth to establish rare lifelines to the mortal realm. These voyages connect the airy domain directly to points on Azeroth, including the outskirts of Dalaran in the Alterac Mountains and the Skywatcher Plateau in Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_zone_zephras-a0f876f43a42cdac045d/1-0000.mp3", duration = 100.937143, start = 0},
  },
}
